INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('ef6f6ed0-d463-4e03-8e4a-45dd1a4704b3', 'Incline Single Arm Y Raise (Dumbbell)', 'Shoulders', 'Dumbbells, Incline Bench', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'Target your delts with the Dumbbell Incline Single Arm Y Raise, an effective shoulder raising exercise. You''ll also feel your upper back working to support the movement. The incline angle shifts emphasis toward the upper portion of the target muscles. Dumbbells allow each arm to work independently, helping correct imbalances. Strong shoulders improve overhead strength and support nearly all upper body movements.', '72311201', '72311201-Dumbbell-Incline-Single-Arm-Y-Raise_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Raise the weight in the prescribed direction for Dumbbell Incline Single Arm Y Raise. 3. Lower with control, maintaining tension throughout. 4. Complete all reps on one side, then switch to the other side. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'lateral_raise', 'Incline Single Arm Y Raise', 'shoulder_press, front_raise, rear_delt', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('ef8fa9e2-6918-4829-975a-4b4580b5dd48', 'Chin Tuck', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Chin Tuck targets your neck muscles through a controlled movement motion. This bodyweight exercise requires no equipment and can be done anywhere. Include this exercise in your routine for balanced strength development.', '31511201', '31511201-Chin-Tuck-(female)_Neck_.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Set up in the starting position for Chin Tuck. 2. Execute the movement with proper form, focusing on your neck. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Chin Tuck', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ef997992-e2bb-41a5-b1cc-4a1e2d7ae630', 'Single Arm Clean And Jerk (Kettlebell)', 'Full Body', 'Kettlebell', '{"Full Body"}'::text[], '{"Quads","Glutes","Traps"}'::text[], 'The Kettlebell One Arm Clean And Jerk is a compound movement exercise that engages your entire body. Secondary activation of your quads, glutes, traps provides additional muscle engagement. The kettlebell''s offset center of mass increases the stability challenge. Compound movements like this develop coordination, power, and overall fitness.', '81081201', '81081201-Kettlebell-One-Arm-Clean-and-Jerk-(female)_Shoulde.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Select an appropriately weighted kettlebell for Kettlebell One Arm Clean And Jerk. 2. Explosively pull the weight upward from the starting position. 3. Pull yourself under the weight and catch it at shoulder level. 4. Stand to complete the lift, then lower with control. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 53, 7, 8, TRUE, TRUE, 'clean', 'Single Arm Clean And Jerk', 'clean, jerk, thruster', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('efa86b04-bbd7-4ebc-a50f-ab7f4c66401e', 'Hyperextension (Hyperextension Bench)', 'Back', 'Hyperextension Bench', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger glutes with this extension movement focused on hip extension. You''ll also feel your hamstrings, lower back working to support the movement. Leg training boosts metabolism and builds functional, real-world strength.', '70151201', '70151201-Hyperextension-(VERSION-2)-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Raise your torso by extending at the lower back/hips. 2. Lower with control, maintaining tension. 3. Complete all reps with control before resting. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'back_extension', 'Hyperextension', 'good_morning, bird_dog, superman', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('efad8241-296b-4ce4-942a-a80d9b01115e', 'Headbanger', 'Arms', 'Bodyweight', '{"Biceps"}'::text[], '{}'::text[], 'Build bigger biceps with this movement movement that targets the front of your arms. A versatile bodyweight movement perfect for home or gym training. Arm strength supports grip, pulling, and pushing in compound movements.', '107361201', '107361201-Headbanger-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Set up in the starting position for Headbanger. 2. Execute the movement with proper form, focusing on your biceps. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Headbanger', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('efb8f7d1-0aa6-42fc-b8fc-2ee03499cc81', 'Landmine Deadlift (Landmine)', 'Back', 'Landmine Attachment, Barbell', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'The Landmine Deadlift is a lower body hip hinge exercise that targets your hamstrings/glutes. The glutes, lower back assist throughout the movement, making this a well-rounded exercise. Lower body strength improves everything from walking to heavy compound lifts.', '78831201', '78831201-Landmine-Deadlift-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Hinge at hips and bend knees to grip the weight. 2. Drive through your heels, extending hips and knees to stand. 3. Lower by reversing the movement with control. 4. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 85, 7, 9, TRUE, FALSE, 'deadlift', 'Landmine Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', TRUE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('efbe903f-a23e-47bd-8386-6b9d0ce6a9be', 'Standing Sissy Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes"}'::text[], 'The Bodyweight Standing Sissy Squat is a squatting exercise that primarily loads your quadriceps. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '47231201', '47231201-Bodyweight-Standing-Sissy-Squat_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Stand with feet about shoulder-width apart. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions. Focus on maintaining proper breathing throughout.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 87, 7, 8, TRUE, TRUE, 'squat', 'Standing Sissy Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('efc1f6f9-6a35-4368-b3f0-827ad78bf3f4', 'Side Plank With Knee Bend', 'Core', 'Bodyweight', '{"Core","Abs"}'::text[], '{"Shoulders"}'::text[], 'Build a stronger core with the Side Plank With Knee Bend, focusing on your abs. Your shoulders, lower back work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '103521201', '103521201-Side-Plank-with-Knee-Bend-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set. This variation specifically emphasizes the abs.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'side_plank', 'Side Plank With Knee Bend', 'plank, russian_twist, woodchop', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('efd1aa5a-f883-4340-89db-10bbc81a8985', 'Lying Ankle Flexion And Extension', 'Full Body', 'Bodyweight', '{"Ankles"}'::text[], '{"Calves"}'::text[], 'Target your ankles with this extension stretch that helps restore range of motion. The calves assist throughout the movement, making this a well-rounded exercise. Performing this lying down removes momentum for stricter form. Flexibility work like this enhances performance and prevents stiffness.', '72951201', '72951201-Lying-Ankle-Flexion-and-Extension-(female)_Stretch.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie down in the appropriate position for Lying Ankle Flexion And Extension. 2. Extend through the target joint(s) for Lying Ankle Flexion And Extension. 3. Move into the stretch position for Lying Ankle Flexion And Extension. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'general_exercise', 'Lying Ankle Flexion And Extension', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('efd3494e-b509-48d6-b65e-e9133fcf972b', 'Standing Single Leg Knee Extensio (Resistance Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This full-body movement exercise challenges multiple muscle groups simultaneously. The standing position engages your core for stability. Bands are joint-friendly and portable, perfect for any training environment. Compound movements like this develop coordination, power, and overall fitness.', '105361201', '105361201-Resistance-Band-Standing-Single-Leg-Knee-Extensio.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Secure the resistance band appropriately for Resistance Band Standing Single Leg Knee Extensio. 2. Begin in a standing position with good posture. 3. Complete all reps on one side, then switch to the other side. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'leg_exercise', 'Standing Single Leg Knee Extensio', 'squat, leg_extension, lunge', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('efd95e2e-84a3-49f0-a396-dc813138f1e0', 'Squat Front Side Kick', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic squatting movement gets your heart rate up while developing explosive strength. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '58511201', '58511201-Squat-Front-Side-Kick-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled. A solid choice for plyometrics day.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Squat Front Side Kick', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('efdb27a3-cc1f-47c7-b183-a6cb0a2bb62e', 'Slam Burpee (Medicine Ball)', 'Full Body', 'Medicine Ball', '{"Full Body"}'::text[], '{"Chest","Quads","Core"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. You''ll also feel your chest, quads working to support the movement. Great for improving athletic performance, burning calories, and building conditioning.', '76091201', '76091201-Medicine-Ball-Slam-Burpee-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Hold a medicine ball at the appropriate position for Medicine Ball Slam Burpee. 2. Squat down and place hands on the floor, jump feet back to plank. 3. Jump feet back toward hands, then explosively jump up with arms overhead. 4. Land softly and immediately begin the next rep. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'burpee', 'Medicine Ball Slam Burpee', 'mountain_climber, box_jump, jumping_jack', TRUE, 'medicine_ball', FALSE, 3, 60, 4, 70, 88, 95, 65),
('efdd2be8-eeab-4fcd-9e71-12b431c84bdc', 'Bent Over Row (Machine)', 'Back', 'Row Machine', '{"Back","Lats"}'::text[], '{"Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. Your biceps, lats work as secondary movers, adding to the training stimulus. Bending over allows gravity to provide resistance in a different plane. The fixed path allows you to focus purely on muscular effort. Back development is crucial for pulling strength and overall upper body function.', '5741201', '05741201-Lever-Bent-over-Row-(plate-loaded)_Back-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Bent Over Row. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 78, 7, 9, TRUE, FALSE, 'bent_over_row', 'Lever Bent Over Row', 'cable_row, dumbbell_row, t_bar_row, lat_pulldown', FALSE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('efdd4341-5723-4b0c-9e61-f0235755c6bc', 'Rack Pull (Barbell)', 'Back', 'Barbell, Power Rack', '{"Upper Back"}'::text[], '{"Lats","Biceps"}'::text[], 'The Barbell Rack Pull targets your hamstrings through a controlled pulling motion. You''ll also feel your glutes, lower back working to support the movement. The barbell allows you to handle heavier loads for maximum strength gains. Lower body strength improves everything from walking to heavy compound lifts.', '57201201', '57201201-Barbell-Rack-Pull-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Rack Pull. 2. Set up in the starting position for Barbell Rack Pull. 3. Execute the movement with proper form, focusing on your hamstrings. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', 'Hip Hinge', 'Pull', 'Compound', 'Bilateral', NULL, 3, NULL, 7, 8, NULL, 5, 'Standing', NULL, 'Overhand (Pronated)', 'Standard', 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'general_exercise', 'Rack Pull', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('efed3d1f-74ef-4eb2-9901-22634ef8827e', 'Seated Overhead Reach Press', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Seated Overhead Reach Press is a pressing exercise that develops back strength and muscle. The seated position helps isolate the target muscles by removing momentum. A strong back improves posture, prevents injury, and balances pressing movements.', '87291201', '87291201-Seated-Overhead-Reach-Press-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement. This variation specifically emphasizes the core.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'shoulder_press', 'Seated Overhead Reach Press', 'lateral_raise, front_raise, rear_delt', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('eff07e1f-d3ed-4888-8435-feae8d9f1ce8', 'Wall Side Lunge Torso Rotation (Wall)', 'Legs', 'Wall', '{"Quads"}'::text[], '{"Glutes","Inner Thighs"}'::text[], 'Build stronger quads with this lunging movement that develops leg drive and power. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Lower body strength improves everything from walking to heavy compound lifts.', '76781201', '76781201-Wall-Side-Lunge-Torso-Rotation-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Position yourself at the appropriate distance from a wall. 2. Step to the side, bending that knee while keeping the other leg straight. 3. Push through your front/working leg to return to the starting position. 4. Complete all reps with control before resting. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'lunge', 'Wall Side Lunge Torso Rotation', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('eff682b8-9133-49f5-9a2f-36f554363caf', 'Bicep Curl - Reverse Grip (Dumbbell)', 'Arms', 'Dumbbells', '{"Forearms"}'::text[], '{"Biceps"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. Your forearms work as secondary movers, adding to the training stimulus. Using dumbbells requires more stabilization than barbell variations. Arm strength supports grip, pulling, and pushing in compound movements.', '70001201', '70001201-Dumbbell-Reverse-grip-Biceps-Curl-(female)_Forearm.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Reverse Grip Biceps Curl. 2. Use a reverse grip (opposite of the standard grip for this exercise). 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'bicep_curl', 'Biceps Curl - Reverse Grip', 'Biceps Curl - Reverse Grip', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('f0187894-6981-4caa-9324-d51729ed0d42', 'Seated Calf Press (Machine)', 'Legs', 'Calf Raise Machine', '{"Calves"}'::text[], '{}'::text[], 'The Lever Seated Calf Press isolates your calf muscles through a pressing motion. Being seated provides stability, allowing you to focus on the working muscles. Machine exercises are great for isolating muscles and training to failure safely. Lower body strength improves everything from walking to heavy compound lifts.', '25581201', '25581201-Lever-Seated-Calf-Press-(female)_Calves_.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Calf Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Execute the pressing motion for Lever Seated Calf Press, extending through the target muscles. 4. Repeat for the prescribed number of repetitions. Keep your core engaged for stability. Ideal for calves strength and endurance.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'calf_raise', 'Lever Seated Calf Press', 'standing_calf_raise, seated_calf_raise, tibialis_raise', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('f0273d81-1d72-473b-a419-fd694c33d994', 'Static Lunge Rotational Chop', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Static Lunge Rotational Chop is an explosive exercise that combines cardiovascular training with dynamic lunging movements. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '74621201', '74621201-Static-Lunge-Rotational-Chop-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Repeat for the prescribed number of repetitions. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 62, 9, 8, TRUE, TRUE, 'woodchop', 'Static Lunge Rotational Chop', 'squat, split_squat, step_up, leg_press', FALSE, 'bodyweight', TRUE, 3, 60, 4, 70, 88, 95, 65),
('f03aa5da-961b-4e23-9ed2-d771c4eb7a5b', 'Reverse Spider Curl (Kettlebell)', 'Arms', 'Kettlebell', '{"Forearms"}'::text[], '{"Biceps"}'::text[], 'The Kettlebell Reverse Spider Curl is a curling exercise that isolates your biceps. The forearms assist throughout the movement, making this a well-rounded exercise. The kettlebell grip position adds a unique training stimulus. Arm strength supports grip, pulling, and pushing in compound movements.', '68361201', '68361201-Kettlebell-Reverse-Spider-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Select an appropriately weighted kettlebell for Kettlebell Reverse Spider Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'bicep_curl', 'Reverse Spider Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78),
('f03daa59-de32-41ed-b84b-8b7f13d77684', 'Around Pullover (Dumbbell)', 'Chest', 'Dumbbells, Flat Bench', '{"Chest"}'::text[], '{"Lats","Triceps"}'::text[], 'Target your chest with the Dumbbell Around Pullover, an effective pulling movement for upper body strength. The lats, triceps assist throughout the movement, making this a well-rounded exercise. Using dumbbells requires more stabilization than barbell variations. A well-developed chest contributes to upper body strength and aesthetics.', '2881201', '02881201-Dumbbell-Around-Pullover_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Around Pullover. 2. With arms slightly bent, lower the weight behind your head in an arc. 3. Pull the weight back over your chest, squeezing your lats and chest. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'pullover', 'Around Pullover', 'bicep_curl, face_pull, lat_pulldown', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('f04e0f0b-3ef9-4187-af9f-69c033ac52b6', 'Arm Flap March', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. Secondary activation of your hip flexors provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '85231201', '85231201-Arm-Flap-March-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Set up in the starting position for Arm Flap March. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'marching', 'Arm Flap March', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f04f57c2-c066-4513-8bb1-abf27df7481c', 'Lying Double Leg Kick', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Lying Double Leg Kick provides a deep stretch for your full body, ideal for recovery and mobility work. Performing this lying down removes momentum for stricter form. Include this in your routine for better mobility and reduced muscle tension.', '64931201', '64931201-Lying-Double-Leg-Kick-(male)_Pilates_.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Lie down in the appropriate position for Lying Double Leg Kick. 2. Move into the stretch position for Lying Double Leg Kick. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Lying Double Leg Kick', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f06721d9-99ef-415b-9474-9f807d90a2e9', 'Rear Lunge (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this lunging exercise for quad development. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Dumbbells allow each arm to work independently, helping correct imbalances. Strong legs are the foundation for athletic performance and functional fitness. Perfect for including in both strength and hypertrophy programs.', '22191201', '22191201-Dumbbell-Rear-Lunge-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Rear Lunge. 2. Step forward into a lunge until both knees are at about 90 degrees. 3. Push through your front/working leg to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'lunge', 'Rear Lunge', 'split_squat, step_up, squat', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('f073ac85-c4ee-4a62-9a59-da43567b168f', 'Shrimp Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. You''ll also feel your glutes, hamstrings working to support the movement. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '58291201', '58291201-Shrimp-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Focus on maintaining proper breathing throughout. An effective movement for your legs routine.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Shrimp Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f077862b-f19d-49fd-aeb8-e49ce5f1a20f', 'Rear Delt Row (Barbell)', 'Shoulders', 'Barbell', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'This rowing exercise works your rear delts for improved shoulder strength and aesthetics. You''ll also feel your upper back working to support the movement. The barbell allows you to handle heavier loads for maximum strength gains. Strong shoulders improve overhead strength and support nearly all upper body movements.', '761201', '00761201-Barbell-Rear-Delt-Row_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Grip a barbell with hands at the appropriate width for Barbell Rear Delt Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'rear_delt', 'Rear Delt Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('f07c3931-716b-461f-a0bc-621964c55400', 'Jumping Air Clap', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'A challenging plyometric exercise, the Jumping Air Clap builds reactive power and improves conditioning. The quads, calves assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '72491201', '72491201-Jumping-Air-Clap-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.831811+00', '1. Set up in the starting position for Jumping Air Clap. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'general_exercise', 'Jumping Air Clap', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('f084f4b1-d249-47f3-ac30-0fa1271414a1', 'Bicep Curl - Single Arm (TRX)', 'Arms', 'TRX', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Your forearms work as secondary movers, adding to the training stimulus. Suspension training adds instability, increasing core activation throughout. Dedicated arm training builds both strength and muscular definition.', '59271201', '59271201-Suspender-One-Arm-Biceps-Curl-(male)_Upper-arms_.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender One Arm Biceps Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'bicep_curl', 'Suspender Single Arm Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'trx', FALSE, 3, 60, 2, 68, 85, 85, 70),
('f08f93ea-b7a2-4c00-a930-60ea31524856', 'Jump Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness. Keep your core engaged throughout the exercise.', '5141201', '05141201-Jump-Squat_Thighs-FIX.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Explode upward from the bottom, jumping as high as possible. 4. Land softly with bent knees and immediately descend into the next rep. 5. Complete all reps with control before resting. Start with lighter weight to perfect your form.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 85, 9, 8, TRUE, TRUE, 'squat_jump', 'Jump Squat', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('f09427d5-0e4e-4ab1-9789-d285533714bd', '4 Reverse Lunge And 4 Side Taps', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Quads","Hamstrings"}'::text[], 'Build stronger quads with this lunging movement that develops leg drive and power. Secondary activation of your glutes, hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength. Quality repetitions are more important than quantity.', '61341201', '61341201-4-Reverse-Lunge-and-4-Side-Taps-(female)_Plyometri.mp4', 'female', FALSE, '2025-12-03 23:26:30.292204+00', '1. Step backward, lowering your back knee toward the floor. 2. Push through your front/working leg to return to the starting position. 3. Complete all reps with control before resting. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', '4 Reverse Lunge And 4 Side Taps', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f0989a3d-937b-443c-9c55-47964a69365d', 'Bent Knee Inverted Row (TRX)', 'Back', 'TRX', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. Your biceps work as secondary movers, adding to the training stimulus. Suspension training adds instability, increasing core activation throughout. Back development is crucial for pulling strength and overall upper body function.', '10711201', '10711201-Suspender-Bent-knee-Inverted-Row-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Bent Knee Inverted Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'general_exercise', 'Suspender Bent Knee Inverted Row', 'squat, leg_extension, lunge', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('f0af2ca0-cad7-4903-8c00-8b81b401ba97', 'Seated Single Leg Raise', 'Legs', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this raising movement focusing on your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. Leg training boosts metabolism and builds functional, real-world strength.', '87521201', '87521201-Seated-Single-Leg-Raise-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Keeping legs mostly straight, raise them toward the ceiling. 3. Lower with control, stopping just before touching down. 4. Complete all reps on one side, then switch to the other side. 5. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 67, 5, 7, FALSE, TRUE, 'leg_raise', 'Seated Single Leg Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f0ba7bdd-d100-4708-8ca4-54dadd7217e1', 'Side Lying Abdominal Press Against Arm', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Side Lying Abdominal Press Against Arm is a core pressing exercise that primarily targets your core. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '92991201', '92991201-Side-Lying-Abdominal-Press-against-Arm-(female)_Wa.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Lie on your side with your body aligned. 2. Execute the pressing motion for Side Lying Abdominal Press Against Arm, extending through the target muscles. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'arm_exercise', 'Side Lying Abdominal Press Against Arm', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f0dc8ff0-bd52-4989-bae9-16c75f160147', 'Concentration Curl (Band)', 'Arms', 'Resistance Band', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Band Concentration Curl is a curling exercise that isolates your biceps. You''ll also feel your forearms working to support the movement. Resistance bands provide accommodating resistance that increases through the range of motion. Arm strength supports grip, pulling, and pushing in compound movements.', '81011201', '81011201-Band-Concentration-Curl-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Secure the resistance band appropriately for Band Concentration Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', 'Isolation', 'Unilateral', NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, 'Underhand (Supinated)', 'Neutral', 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'concentration_curl', 'Concentration Curl', 'tricep_pushdown, tricep_extension, bicep_curl, hammer_curl', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('f0de4399-af39-4b5b-a554-6590514a674f', 'Side Split Squat (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. The barbell allows you to handle heavier loads for maximum strength gains. Strong legs are the foundation for athletic performance and functional fitness.', '971201', '00971201-Barbell-Side-Split-Squat-(version-2)_Thighs-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Side Split Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'split_squat', 'Side Split Squat', 'lunge, bulgarian_split_squat, squat', FALSE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('f0ded4a8-003b-4414-96da-9de8fcdbb1cd', 'Dimel Deadlift (Barbell)', 'Back', 'Barbell', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. The glutes, lower back assist throughout the movement, making this a well-rounded exercise. The barbell allows you to handle heavier loads for maximum strength gains. Lower body strength improves everything from walking to heavy compound lifts.', '69381201', '69381201-Barbell-Dimel-Deadlift-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Grip a barbell with hands at the appropriate width for Barbell Dimel Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'deadlift', 'Dimel Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', TRUE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('f0e6a628-4378-4f4e-9202-a3e02c9fe3b1', 'Split Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Split Squat is a squatting exercise that primarily loads your quadriceps. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '7811201', '07811201-Split-Squat-(female)_Hips-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction. This exercise is excellent for quads development.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'split_squat', 'Split Squat', 'lunge, bulgarian_split_squat, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f0e9afce-e8a0-4a9c-9ada-e388c25a3155', 'Seated Hip External Rotation (Band)', 'Shoulders', 'Resistance Band, Anchor Point', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'The Band Seated Hip External Rotation is a lower body rotation exercise that targets your rotator cuff. The seated position helps isolate the target muscles by removing momentum. Bands are joint-friendly and portable, perfect for any training environment. Strong legs are the foundation for athletic performance and functional fitness.', '9951201', '09951201-Band-Seated-Hip-External-Rotation_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:24.203368+00', '1. Secure the resistance band appropriately for Band Seated Hip External Rotation. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Rotate your torso through the movement pattern for Band Seated Hip External Rotation. 4. Control the rotation in both directions—avoid using momentum. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 57, 7, 8, TRUE, TRUE, 'external_rotation', 'Seated Hip External Rotation', 'squat, bench_press, deadlift', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('f0ef6fd1-7385-44bb-afb1-ff528ffda466', 'Weighted Standing Twist', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this twisting exercise that strengthens your obliques. The abs assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Core strength is foundational for athletic performance and injury prevention.', '8551201', '08551201-Weighted-Standing-Twist_Waist-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Stand with feet about shoulder-width apart. 2. Rotate your torso through the movement pattern for Weighted Standing Twist. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'russian_twist', 'Weighted Standing Twist', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f10d2206-d95f-496f-a885-953908836330', 'Crab', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Crab provides a deep stretch for your full body, ideal for recovery and mobility work. Include this in your routine for better mobility and reduced muscle tension.', '28421201', '28421201-Crab_Pilates_.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Move into the stretch position for Crab. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Crab', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f10d6b90-7fd9-4456-a19d-87131994140d', 'Lying Hip Abduction Knee Bent', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hip Abductors"}'::text[], 'The Lying Hip Abduction Knee Bent is a lower body movement exercise that targets your glute med/abductors. Your glutes work as secondary movers, adding to the training stimulus. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '72991201', '72991201-Lying-Hip-Abduction-Knee-Bent-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Hip Abduction Knee Bent. 2. Set up in the starting position for Lying Hip Abduction Knee Bent. 3. Execute the movement with proper form, focusing on your glute med/abductors. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_abduction', 'Lying Hip Abduction Knee Bent', 'hip_adduction, glute_bridge, clamshell', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f119b3f2-748e-4503-a726-a72087ad5d8a', 'Feet And Ankles Rotation Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Feet And Ankles Rotation Stretch isolates your calf muscles through a rotation motion. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '32461201', '32461201-Feet-and-Ankles-Rotation-Stretch-(female)_Calves.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Rotate your torso through the movement pattern for Feet And Ankles Rotation Stretch. 2. Control the rotation in both directions—avoid using momentum. 3. Repeat for the prescribed number of repetitions. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Feet And Ankles Rotation Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('f11a21c5-7b4f-4407-b3c2-4471777d08d7', 'Butterfly Yoga Flaps', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Use this stretch to open up your full body area and enhance overall flexibility. Include this in your routine for better mobility and reduced muscle tension. Start with lighter weight to master the movement pattern.', '88411201', '88411201-Butterfly-Yoga-Flaps-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. With a slight bend in your elbows, move the weight in a wide arc. 2. Squeeze your chest muscles at the center/top of the movement. 3. Return with control, feeling the stretch at the bottom. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'groin_stretch', 'Butterfly Yoga Flaps', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('f11cac1c-4e04-4d89-8a04-dbf44febe969', 'Woodchoppers', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'A challenging plyometric exercise, the Bodyweight Woodchoppers builds reactive power and improves conditioning. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '56861201', '56861201-Bodyweight-Woodchoppers-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:31.60311+00', '1. Set up in the starting position for Bodyweight Woodchoppers. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'woodchop', 'Woodchoppers', 'russian_twist, pallof_press, cable_crunch', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('f12595ef-03a0-4cd2-8a84-f7af8538f43a', 'Roll Around The World Lying On Floor', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Roll Around The World Lying On Floor is a movement exercise that develops back strength and muscle. You''ll also feel your chest working to support the movement. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. A strong back improves posture, prevents injury, and balances pressing movements.', '54251201', '54251201-Roll-Around-the-World-Lying-on-Floor-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Position yourself on the floor for Roll Around The World Lying On Floor. 2. Lie down in the appropriate position for Roll Around The World Lying On Floor. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'around_world', 'Roll Around The World Lying On Floor', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f125d1ca-3613-4b2a-ae5a-8c0661b66ac5', 'Boat Yoga Pose', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Boat Yoga Pose is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '1361201', '01361201-Boat-Yoga-Pose-(female)_Stretching-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:31.347577+00', '1. Move into the stretch position for Boat Yoga Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'v_up', 'Boat Yoga Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('f127f010-1926-4c42-9a3f-b52d077d8fc6', 'Seated Isometric Peroneal Squeeze', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This movement movement focuses on your gastrocnemius and soleus. The seated position helps isolate the target muscles by removing momentum. Leg training boosts metabolism and builds functional, real-world strength.', '100151201', '100151201-Sitting-Isometric-Peroneal-Squeeze-(female)_Calve.mp4', 'female', FALSE, '2025-12-03 23:26:37.756436+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Hold the position for the prescribed time, maintaining tension. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Isometric Peroneal Squeeze', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('f12c08ec-f2fb-4f50-b827-8bdc072a0f60', 'Reverse Plank With Leg Lift', 'Core', 'Bodyweight', '{"Glutes","Hamstrings"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Reverse Plank With Leg Lift is a lower body stabilization exercise that targets your abs. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '88981201', '88981201-Reverse-Plank-with-Leg-Lift-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Ensure full range of motion on each rep. A solid choice for legs day. Variation: Reverse Plank With Leg Lift.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Reverse Plank With Leg Lift', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('f150b4f5-c348-47aa-8ef4-01327f30df27', 'Standing Twist (Barbell)', 'Core', 'Barbell', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Barbell Standing Twist targets your obliques through a twisting motion, building rotational core strength. Your abs work as secondary movers, adding to the training stimulus. The standing position engages your core for stability. Using a barbell provides stability for progressive overload. Core strength is foundational for athletic performance and injury prevention.', '1121201', '01121201-Barbell-Standing-Twist_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Grip a barbell with hands at the appropriate width for Barbell Standing Twist. 2. Begin in a standing position with good posture. 3. Rotate your torso through the movement pattern for Barbell Standing Twist. 4. Control the rotation in both directions—avoid using momentum. 5. Repeat for the prescribed number of repetitions. Engage your stabilizer muscles for better control.', 'Flexion', NULL, 'Isolation', 'Unilateral', NULL, 3, NULL, 5, 7, NULL, 6, 'Standing', NULL, 'Overhand', 'Wide', 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 64, 5, 7, FALSE, TRUE, 'russian_twist', 'Standing Twist', 'squat, bench_press, deadlift', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('f1530476-30d3-41c5-8861-1e113a2a2fe1', 'Isometric Squat Hip Abduction (Machine)', 'Legs', 'Hip Abduction Machine', '{"Glutes","Hips"}'::text[], '{"Hamstrings"}'::text[], 'Build leg strength with this squatting movement focusing on your glute med/abductors. Secondary activation of your glutes provides additional muscle engagement. The fixed path allows you to focus purely on muscular effort. Strong legs are the foundation for athletic performance and functional fitness.', '101131201', '101131201-Lever-Isometric-Squat-Hip-Abduction-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Isometric Squat Hip Abduction. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Hold the position for the prescribed time, maintaining tension.', 'Squat', NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 53, 7, 8, TRUE, TRUE, 'hip_abduction', 'Lever Isometric Squat Hip Abduction', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'machine', TRUE, 3, 90, 4, 80, 75, 20, 88),
('f17a3ec8-466a-430d-a031-4e1978bbfd91', 'Low Seated Row (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Cable Low Seated Row is a rowing exercise that builds thickness in your upper back. The biceps, lats assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. Cable resistance creates smooth, continuous muscle engagement. A strong back improves posture, prevents injury, and balances pressing movements.', '1801201', '01801201-Cable-Low-Seated-Row_Back.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Set the cable pulley to the lowest position and attach your preferred handle. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 92, 7, 8, TRUE, TRUE, 'cable_row', 'Low Seated Row', 'bent_over_row, lat_pulldown, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('f17d93cd-97d2-4f5f-ac18-2859441eec69', 'Standing Front Heel Tap Back Squeeze', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'A challenging plyometric exercise, the Standing Front Heel Tap Back Squeeze builds reactive power and improves conditioning. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '98551201', '98551201-Standing-Front-Heel-Tap-Back-Squeeze-(female)_Plyo.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Front Heel Tap Back Squeeze. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'back_exercise', 'Standing Front Heel Tap Back Squeeze', 'crunch, bicycle_crunch, russian_twist', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f18bd449-59ca-4891-ace5-6301caa48352', 'Decline Bench Press - Reverse Close Grip (Smith Machine)', 'Arms', 'Smith Machine, Decline Bench', '{Triceps}'::text[], '{"Front Delts"}'::text[], 'Build stronger triceps with this movement exercise for bigger arms. Secondary activation of your chest provides additional muscle engagement. Declining shifts the emphasis to hit the muscles from a different angle. The fixed path allows you to focus purely on muscular effort. Arm strength supports grip, pulling, and pushing in compound movements.', '16261201', '16261201-Smith-Machine-Reverse-Decline-Close-Grip-Bench-Pre.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Smith Machine Reverse Decline Close Grip Bench Pre. 2. Set the bench to a decline angle and secure your feet. 3. Use a close/narrow grip (hands closer than shoulder-width). 4. Continue for your target rep count, maintaining good form throughout.', 'Press', 'Push', 'Compound', 'Bilateral', NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 69, 7, 8, TRUE, TRUE, 'close_grip_bench', 'Smith Reverse Decline Bench Pre - Close Grip', 'Reverse Decline Bench Pre - Close Grip', FALSE, 'smith_machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('f19f05ae-bf4f-4f37-a89a-f91babb80440', 'Lateral Walk (Resistance Band)', 'Full Body', 'Resistance Band', '{"Full Body"}'::text[], '{}'::text[], 'The Resistance Band Lateral Walk is a lower body stepping exercise that targets your full body. Resistance bands provide accommodating resistance that increases through the range of motion. Leg training boosts metabolism and builds functional, real-world strength.', '66071201', '66071201-Resistance-Band-Lateral-Walk-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Secure the resistance band appropriately for Resistance Band Lateral Walk. 2. Set up in the starting position for Resistance Band Lateral Walk. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'walking', 'Lateral Walk', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('f1b8d435-98d4-47c9-a38a-a4fce7cee1e2', 'Sphinx Pose Twist', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Obliques"}'::text[], 'The Sphinx Pose Twist provides a deep stretch for your full body, ideal for recovery and mobility work. Your abs work as secondary movers, adding to the training stimulus. Flexibility work like this enhances performance and prevents stiffness.', '89611201', '89611201-Sphinx-Pose-Twist-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. Rotate your torso through the movement pattern for Sphinx Pose Twist. 2. Control the rotation in both directions—avoid using momentum. 3. Move into the stretch position for Sphinx Pose Twist. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'back_stretch', 'Sphinx Pose Twist', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('f1baeab0-fe42-4cec-b1d4-b8f068a04dad', 'Prone Incline Curl (Barbell)', 'Arms', 'Barbell, Incline Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Secondary activation of your forearms provides additional muscle engagement. Performing this lying down removes momentum for stricter form. Using a barbell provides stability for progressive overload. Dedicated arm training builds both strength and muscular definition.', '25061201', '25061201-Barbell-Prone-Incline-Curl-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Grip a barbell with hands at the appropriate width for Barbell Prone Incline Curl. 2. Lie face down (prone position) for Barbell Prone Incline Curl. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting.', 'Curl', 'Pull', 'Isolation', 'Bilateral', NULL, 3, NULL, 5, 7, NULL, 6, 'Lying', NULL, 'Underhand (Supinated)', 'Standard', 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 95, 5, 7, FALSE, TRUE, 'incline_curl', 'Prone Incline Curl', 'bicep_curl, hammer_curl, preacher_curl', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('f1bc5cae-219e-43ee-997f-fe8a81cb0d7f', 'Hook Grip Deadlift (Barbell)', 'Back', 'Barbell', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'Elevate your training with this hip hinge exercise that develops speed, power, and coordination. The shoulders, core assist throughout the movement, making this a well-rounded exercise. The barbell allows you to handle heavier loads for maximum strength gains. Plyometric training builds explosive power that transfers to sports and daily activities.', '72371201', '72371201-Barbell-Hook-grip-Deadlift-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Grip a barbell with hands at the appropriate width for Barbell Hook Grip Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'deadlift', 'Hook Grip Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', FALSE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('f1cedd56-0537-467b-83f9-8ab0cf09b90a', 'Double Side Step Triceps Kickback', 'Arms', 'Bodyweight', '{"Triceps"}'::text[], '{"Rear Delts"}'::text[], 'Elevate your training with this kicking exercise that develops speed, power, and coordination. The hamstrings assist throughout the movement, making this a well-rounded exercise. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '93711201', '93711201-Double-Side-Step-Tricep-Kickback-(female)_Plyometr.mp4', 'female', FALSE, '2025-12-03 23:26:32.624497+00', '1. Set up a box or step platform at the appropriate height. 2. Keep your upper arm stationary and extend your forearm back. 3. Squeeze at full extension, then return with control. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Double Side Step Triceps Kickback', 'tricep_pushdown, tricep_extension', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f1cf7a29-422b-45ee-8836-039cb245d8ed', 'Standing Front Leg Lift Cross Toe Touches Side Ben', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. You''ll also feel your hip flexors working to support the movement. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '84031201', '84031201-Standing-Front-Leg-Lift-Cross-Toe-Touches-Side-Ben.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Front Leg Lift Cross Toe Touches Side Ben. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'toe_touch', 'Standing Front Leg Lift Cross Toe Touches Side Ben', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f1d24dd8-40ac-4605-8024-cf7843c454f0', 'Rear Delt Fly (Dumbbell)', 'Shoulders', 'Dumbbells, Flat Bench', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'The Dumbbell Rear Delt Fly is a flying exercise that targets your rear delts for shoulder development. Your upper back work as secondary movers, adding to the training stimulus. Using dumbbells requires more stabilization than barbell variations. Shoulder development enhances both performance and upper body aesthetics.', '24871201', '24871201-Dumbbell-Rear-Delt-Fly-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Rear Delt Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'rear_delt', 'Rear Delt Fly', 'bench_press, incline_bench_press, push_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('f1da7500-88f4-403a-aa50-d30c4809d804', 'Lying Raised Shoulders Windshield Wiper', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Lying Raised Shoulders Windshield Wiper, focusing on your core. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '77761201', '77761201-Lying-Raised-Shoulders-Windshield-Wiper-(male)_Wai.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Lie down in the appropriate position for Lying Raised Shoulders Windshield Wiper. 2. Raise the weight in the prescribed direction for Lying Raised Shoulders Windshield Wiper. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'shoulder_exercise', 'Lying Raised Shoulders Windshield Wiper', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f1e90f83-58a2-4505-a79a-094534dc04c1', 'Lying Hip Internal Rotation Pullover', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Designed to lengthen your rotator cuff, the Lying Hip Internal Rotation Pullover helps improve mobility and prevent stiffness. Secondary activation of your lats, triceps provides additional muscle engagement. The lying position provides back support and helps isolate the target muscles. Flexibility work like this enhances performance and prevents stiffness.', '81491201', '81491201-Lying-Hip-Internal-Rotation-Pullover-(female)_Stre.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie down in the appropriate position for Lying Hip Internal Rotation Pullover. 2. Rotate your torso through the movement pattern for Lying Hip Internal Rotation Pullover. 3. Control the rotation in both directions—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'external_rotation', 'Lying Hip Internal Rotation Pullover', 'bicep_curl, face_pull, lat_pulldown', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f1eac1e0-1232-4c16-83f9-e9aeaaf21556', 'Incline Push Up With Bench', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'This pushing exercise focuses on your pectorals for improved chest strength and development. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. The incline angle shifts emphasis toward the upper portion of the target muscles. A well-developed chest contributes to upper body strength and aesthetics.', '98061201', '98061201-Incline-Push-up-with-Bench-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Set the bench to an incline angle (30-45 degrees). 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 73, 7, 8, TRUE, TRUE, 'push_up', 'Incline Push Up With Bench', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f209e9a2-b5d1-42e0-a2bb-340be663969b', 'Knee Raise Side Jabs', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Knee Raise Side Jabs is an explosive exercise that combines cardiovascular training with dynamic raising movements. Secondary activation of your hip flexors provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '59581201', '59581201-Knee-Raise-Side-Jabs-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Raise your arms out to the sides until parallel to the floor. 2. Lower with control, maintaining tension throughout. 3. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement. This variation specifically emphasizes the full body.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Knee Raise Side Jabs', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f21f00b5-327b-4998-bcb3-c15d215d19bc', 'Reverse Hyperextension (Machine)', 'Back', 'Lever Machine', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This extension exercise isolates your glutes for improved hip strength and power. You''ll also feel your hamstrings, lower back working to support the movement. The fixed path allows you to focus purely on muscular effort. Lower body strength improves everything from walking to heavy compound lifts.', '31771201', '31771201-Lever-Reverse-Hyperextension-(plate-loaded)-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Reverse Hyperextension. 2. Raise your torso by extending at the lower back/hips. 3. Lower with control, maintaining tension. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'back_extension', 'Lever Reverse Hyperextension', 'good_morning, bird_dog, superman', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('f2200096-3689-4be5-a9d7-a31e4be396ba', 'Countermovement Jump Arms Pull', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'Elevate your training with this pulling exercise that develops speed, power, and coordination. Your quads, calves work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '95131201', '95131201-Countermovement-Jump-Arms-Pull-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Set up in the starting position for Countermovement Jump Arms Pull. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'arm_exercise', 'Countermovement Jump Arms Pull', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('f2254951-b48b-4489-a671-e8c1ce7a1736', 'Standing Peroneus Muscles Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This stretching movement focuses on your gastrocnemius and soleus. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '67721201', '67721201-Standing-Peroneus-Muscles-Stretch-(female)_Calves_.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Peroneus Muscles Stretch. 3. Execute the movement with proper form, focusing on your calves. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'stretch_general', 'Standing Peroneus Muscles Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('f225de40-d602-4dd4-9cda-8da56ee3c993', 'Inchworm And Plank Leg Lift', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Inchworm And Plank Leg Lift is an explosive exercise that combines cardiovascular training with dynamic stabilization movements. Your shoulders, lower back work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '59301201', '59301201-Inchworm-and-Plank-Leg-Lift-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Repeat for the prescribed number of repetitions. Keep the movement smooth and controlled. Works well for abs activation.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'inchworm', 'Inchworm And Plank Leg Lift', 'crunch, leg_raise, russian_twist, dead_bug', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('f22da852-b33a-4031-a457-d9d62150a51c', 'Standing Jab (Cable)', 'Full Body', 'Cables', '{"Full Body"}'::text[], '{"Shoulders","Core"}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. You''ll also feel your shoulders, core working to support the movement. The standing position engages your core for stability. The cable setup allows you to adjust the angle of resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '88801201', '88801201-Cable-Standing-Jab-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing Jab. 2. Stand with feet about shoulder-width apart. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'boxing', 'Standing Jab', 'core_exercise, shoulder_exercise, burpee', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('f22f059d-56ef-452b-bfc2-775189a020f0', 'Roll Hip Thrust', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'This thrusting exercise isolates your glutes for improved hip strength and power. Secondary activation of your hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '22001201', '22001201-Roll-Hip-Thrust-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Continue for your target rep count, maintaining good form throughout. Don''t rush—quality over quantity. An effective movement for your legs routine.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'hip_thrust', 'Roll Hip Thrust', 'glute_bridge, romanian_deadlift, leg_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f2351fa3-a118-4b61-80b0-96e0e9d404e6', 'Standing Side Circle Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Standing Side Circle Stretch is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Performing this standing challenges your balance and core engagement. Flexibility work like this enhances performance and prevents stiffness.', '80631201', '80631201-Standing-Side-Circle-Stretch-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Stand with feet about shoulder-width apart. 2. Move into the stretch position for Standing Side Circle Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 5. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'stretch_general', 'Standing Side Circle Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('f235367c-60d8-44a7-9066-a9570521b6d4', 'T Bar Row (Machine)', 'Back', 'Row Machine', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. You''ll also feel your biceps, lats working to support the movement. The fixed path allows you to focus purely on muscular effort. Back development is crucial for pulling strength and overall upper body function.', '6061201', '06061201-Lever-T-bar-Row-(plate-loaded)_Back-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever T Bar Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 78, 7, 9, TRUE, FALSE, 't_bar_row', 'Lever T Bar Row', 'bent_over_row, lat_pulldown, deadlift', FALSE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('f2395587-ee40-459d-bf5d-8554d7264881', 'Jack Knife Floor', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Jack Knife Floor is a core movement exercise that primarily targets your abs. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '5021201', '05021201-Jack-knife Floor_Waist-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Position yourself on the floor for Jack Knife Floor. 2. Set up in the starting position for Jack Knife Floor. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 45, 9, 8, TRUE, TRUE, 'general_exercise', 'Jack Knife Floor', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('f239ba17-4f09-4c2a-805f-a49fa1a5c391', 'Sphinx Pose', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Sphinx Pose provides a deep stretch for your full body, ideal for recovery and mobility work. Flexibility work like this enhances performance and prevents stiffness.', '61321201', '61321201-Sphinx-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Move into the stretch position for Sphinx Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'back_stretch', 'Sphinx Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('f2570564-d2b2-412a-bdc5-58fcc0ae0b4c', 'Cross Arms Front Leg Kick', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Shoulders","Core"}'::text[], 'The Cross Arms Front Leg Kick is an explosive exercise that combines cardiovascular training with dynamic kicking movements. You''ll also feel your shoulders, core working to support the movement. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '105191201', '105191201-Cross-Arms-Front-Leg-Kick-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Set up in the starting position for Cross Arms Front Leg Kick. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Cross Arms Front Leg Kick', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f260070f-46fa-4f93-82e1-fe748eabd78c', 'Single Arm High Row (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. You''ll also feel your biceps, rear delts working to support the movement. Cables provide constant tension throughout the full range of motion. A strong back improves posture, prevents injury, and balances pressing movements.', '97551201', '97551201-Cable-Single-Arm-High-Row-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Set the cable pulley to the highest position and attach your preferred handle. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'cable_row', 'Single Arm High Row', 'bent_over_row, lat_pulldown, bicep_curl', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('f26172f1-2734-4a34-9f70-739cc0604946', 'Pogo Jump 2 Foot', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'Elevate your training with this jumping exercise that develops speed, power, and coordination. Your quads, calves work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '90701201', '90701201-Pogo-Jump-2 Foot-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Set up in the starting position for Pogo Jump 2 Foot. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'general_exercise', 'Pogo Jump 2 Foot', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('f2833797-5c2e-46e0-ac4b-a366022959d1', 'Tip Toe Glute Bridge Abduction', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger glutes with this bridging movement focused on hip extension. Secondary activation of your hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness. Aim for full range of motion on every rep.', '65741201', '65741201-Tip-Toe-Glute-Bridge-Abduction-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:39.623429+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Complete all reps with control before resting. Engage your stabilizer muscles for better control. Include this in your legs training.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'glute_bridge', 'Tip Toe Glute Bridge Abduction', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f2835189-7fdd-4bbb-a319-cb7c273026c6', 'Scapular Retraction (TRX)', 'Back', 'TRX', '{"Upper Back"}'::text[], '{"Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this movement movement. Your rear delts work as secondary movers, adding to the training stimulus. Suspension training adds instability, increasing core activation throughout. Back development is crucial for pulling strength and overall upper body function.', '75051201', '75051201-Suspender-Scapular-Retraction_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Scapular Retraction. 2. Set up in the starting position for Suspender Scapular Retraction. 3. Execute the movement with proper form, focusing on your upper back. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'general_exercise', 'Suspender Scapular Retraction', 'squat, bench_press, deadlift', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('f2926ac0-0162-4765-9e6e-6fbc6e14a20a', 'Saw', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Target your full body with this movement stretch that helps restore range of motion. Regular stretching improves flexibility, reduces injury risk, and aids recovery. This is a great exercise for all fitness levels with proper scaling.', '28611201', '28611201-Saw-(female)_Pilates_.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Move into the stretch position for Saw. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Saw', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f2976b41-f79b-4cd5-b067-d9654d91aa14', 'Standing Calf Raise (Kettlebell)', 'Legs', 'Kettlebell', '{"Calves"}'::text[], '{}'::text[], 'This raising movement focuses on your gastrocnemius and soleus. Performing this standing challenges your balance and core engagement. The kettlebell''s offset center of mass increases the stability challenge. Strong legs are the foundation for athletic performance and functional fitness.', '66971201', '66971201-Kettlebell-Standing-Calf-Raise-(female)_Calves_.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Select an appropriately weighted kettlebell for Kettlebell Standing Calf Raise. 2. Begin in a standing position with good posture. 3. Lower your heels below the platform to get a full stretch. 4. Rise up onto your toes as high as possible, squeezing your calves. 5. Lower with control and repeat. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'calf_raise', 'Standing Calf Raise', 'calf_raise, seated_calf_raise', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78),
('f2979206-51ca-405c-b46e-ced8d587a417', 'Standing 90 Degrees Shoulder Extre (Resistance Band)', 'Full Body', 'Resistance Band', '{"Full Body"}'::text[], '{}'::text[], 'Build total body strength and coordination with this multi-joint movement movement. The standing position engages your core for stability. Resistance bands provide accommodating resistance that increases through the range of motion. Compound movements like this develop coordination, power, and overall fitness.', '83631201', '83631201-Resistance-Band-Standing-90-degrees-Shoulder-Extre.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Secure the resistance band appropriately for Resistance Band Standing 90 Degrees Shoulder Extre. 2. Stand with feet about shoulder-width apart. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 47, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Standing 90 Degrees Shoulder Extre', 'lateral_raise, shoulder_press, front_raise', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('f29ffa4f-2861-4bdf-9b8d-e21e76ec23c0', 'Quickly Swing Arms In Place', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Quickly Swing Arms In Place is a swinging exercise that targets your delts for shoulder development. A versatile bodyweight movement perfect for home or gym training. Strong shoulders improve overhead strength and support nearly all upper body movements.', '55521201', '55521201-Quickly-Swing-Arms-in-place-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Hinge at your hips, letting the weight swing back between your legs. 2. Explosively drive hips forward, propelling the weight forward/up. 3. Let gravity bring it back as you hinge for the next rep. 4. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set. Include this in your shoulders training.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'arm_exercise', 'Quickly Swing Arms In Place', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f2a1fefa-4f74-49a8-a2e4-27f760321466', 'Hammer Curl (Cable)', 'Arms', 'Cables', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Cable Hammer Curl is a curling exercise that isolates your biceps. Your forearms work as secondary movers, adding to the training stimulus. Cables provide constant tension throughout the full range of motion. Arm strength supports grip, pulling, and pushing in compound movements.', '1661201', '01661201-Cable-Hammer-Curl_Forearm.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable Hammer Curl. 2. Use a hammer/neutral grip with palms facing each other throughout. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'hammer_curl', 'Hammer Curl', 'bicep_curl, preacher_curl', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('f2bb86e2-5a5b-4aa5-9729-33f589cbcbd7', 'Weighted Triceps Dip (Dip Bars)', 'Arms', 'Dip Bars', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Weighted Triceps Dips targets your triceps through a dipping motion. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Arm strength supports grip, pulling, and pushing in compound movements.', '105851201', '105851201-Weighted-Tricep-Dips-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Lower your body by bending your elbows to about 90 degrees. 2. Push back up until your arms are fully extended. 3. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'dip', 'Weighted Triceps Dip', 'bench_press, tricep_pushdown, push_up', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f2be0a9f-a795-4e0b-b316-10258e1ef30b', 'Crunch Legs On Stability Ball (Stability Ball)', 'Core', 'Stability Ball', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This crunching exercise engages your abs for improved core stability and strength. You''ll also feel your hip flexors working to support the movement. The stability ball adds an instability challenge that activates more stabilizer muscles. A strong core improves posture, protects your spine, and enhances all other lifts.', '2691201', '02691201-Crunch-(legs-on-stability-ball)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Position the stability ball as needed for Crunch. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'crunch', 'Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'stability_ball', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f2c92ed9-f551-49ab-9f09-45523717e6bf', 'Lying Straight Arms Pullover (Dumbbell)', 'Chest', 'Dumbbells, Flat Bench', '{"Chest"}'::text[], '{"Lats","Triceps"}'::text[], 'Build a stronger back with this pulling movement targeting your chest. You''ll also feel your lats, triceps working to support the movement. Performing this lying down removes momentum for stricter form. Dumbbells allow each arm to work independently, helping correct imbalances. Back development is crucial for pulling strength and overall upper body function.', '98101201', '98101201-Dumbbell-Lying-Straight-Arms-Pullover-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:24.831811+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lying Straight Arms Pullover. 2. Lie down in the appropriate position for Dumbbell Lying Straight Arms Pullover. 3. With arms slightly bent, lower the weight behind your head in an arc. 4. Pull the weight back over your chest, squeezing your lats and chest. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'pullover', 'Lying Straight Arms Pullover', 'bicep_curl, face_pull, lat_pulldown', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('f2e1587f-679b-4780-b355-21ef5958bacd', 'Walking', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This cardio exercise keeps your heart rate elevated for improved cardiovascular fitness. Cardiovascular exercise improves heart health, endurance, and helps manage weight. Perfect for including in both strength and hypertrophy programs.', '22611201', '22611201-Walking-(female)_Cardio_.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Set up in the starting position for Walking. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'walking', 'Walking', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('f2e54c34-ad23-4c7c-a4f8-e4f83e1ba9d6', 'Plie Squat Knee Tap', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness. Progress gradually by increasing resistance over time.', '103781201', '103781201-Plie-Squat-Knee-Tap-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction. A solid choice for legs day.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Plie Squat Knee Tap', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f2e7ed2c-9035-4a43-9adc-7740f8cbf013', 'Seated Knee To Elbow Twist - Alternating', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this twisting exercise that strengthens your obliques. Your abs work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. A strong core improves posture, protects your spine, and enhances all other lifts.', '76931201', '76931201-Sitting-Alternate-Knee-to-Elbow-Twist-(male)_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Rotate your torso through the movement pattern for Seated Alternate Knee To Elbow Twist. 3. Control the rotation in both directions—avoid using momentum. 4. Alternate between sides/arms/legs with each repetition. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'leg_raise', 'Seated Knee To Elbow Twist - Alternating', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f2effeca-b1b9-47e8-bd6c-68912ca5fb55', 'Seated Arms Archer Back Rotation - Alternating', 'Core', 'Bodyweight', '{"Quads"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Seated Alternate Arms Archer Back Rotation, focusing on your core. Being seated provides stability, allowing you to focus on the working muscles. Building core stability helps with everything from heavy deadlifts to daily activities.', '87331201', '87331201-Seated-Alternate-Arms-Archer-Back-Rotation-(female.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Rotate your torso through the movement pattern for Seated Alternate Arms Archer Back Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Alternate between sides/arms/legs with each repetition. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'back_exercise', 'Seated Arms Archer Back Rotation - Alternating', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f2f732f0-978d-4e2e-9752-32d513e6a016', 'Standing Forward Leg Swing', 'Full Body', 'Bodyweight', '{"Quads"}'::text[], '{"Hip Flexors"}'::text[], 'The Back Forward Leg Swings is a flexibility exercise that targets your back, helping to release tension and improve range of motion. Flexibility work like this enhances performance and prevents stiffness.', '25731201', '25731201-Back-Forward-Leg-Swings-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Hinge at your hips, letting the weight swing back between your legs. 2. Explosively drive hips forward, propelling the weight forward/up. 3. Let gravity bring it back as you hinge for the next rep. Focus on the mind-muscle connection.', NULL, 'Static', NULL, 'Bilateral', NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'leg_exercise', 'Standing Forward Leg Swing', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f31458ef-24ae-46da-9c9c-24d72baa9885', 'Walking Outer Draw - Alternating', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity stepping exercise that challenges your entire body. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning. Excellent for pre-exhausting the target muscle before compound lifts.', '99151201', '99151201-Walking-Alternating-Outer-Draw-(female)_Plyometric.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Alternate between sides/arms/legs with each repetition. 2. Set up in the starting position for Walking Alternating Outer Draw. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'walking', 'Walking Outer Draw - Alternating', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('f31701e8-a805-4f4b-89ef-c805b20e7d7e', 'Curl - Close Grip (EZ Bar)', 'Arms', 'EZ Bar', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. Your forearms work as secondary movers, adding to the training stimulus. Using a barbell provides stability for progressive overload. Arm strength supports grip, pulling, and pushing in compound movements.', '24991201', '24991201-EZ-Barbell-Close-grip-Curl-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Grip a barbell with hands at the appropriate width for EZ Barbell Close Grip Curl. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'general_exercise', 'EZ Curl - Close Grip', 'EZ Curl - Close Grip', FALSE, 'ez_bar', FALSE, 3, 60, 2, 95, 80, 65, 95),
('f33e5e49-c3f8-497d-a3f2-7745c1a09969', 'Walking On Spot Hands Push', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Walking On Spot Hands Push is an explosive exercise that combines cardiovascular training with dynamic pushing movements. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '93791201', '93791201-Walking-On-Spot-Hands-Push-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Set up in the starting position for Walking On Spot Hands Push. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'walking', 'Walking On Spot Hands Push', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('f349e568-4b28-4ffc-b410-06643e26143c', 'Single Leg Split Squat With Low Box (Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Secondary activation of your glutes, hamstrings provides additional muscle engagement. The band creates increasing tension as it stretches, challenging the lockout. Strong legs are the foundation for athletic performance and functional fitness.', '72411201', '72411201-Band-Single-Leg-Split-Squat-with-Low-Box_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Secure the resistance band appropriately for Band Single Leg Split Squat With Low Box. 2. Set up a box or step platform at the appropriate height. 3. Push your hips back and bend your knees to lower your body. 4. Keep your chest up and knees tracking over your toes. 5. Drive through your heels to stand back up, squeezing your glutes at the top. 6. Complete all reps on one side, then switch to the other side. 7. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'split_squat', 'Single Leg Split Squat With Low Box', 'lunge, bulgarian_split_squat, squat', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('f34a545a-9170-4c43-9c46-66a9d70a817b', 'Side Step Overhead Swing', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic swinging movement gets your heart rate up while developing explosive strength. The quads assist throughout the movement, making this a well-rounded exercise. Great for improving athletic performance, burning calories, and building conditioning.', '65271201', '65271201-Side-Step-Overhead-Swing-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:26.808474+00', '1. Set up a box or step platform at the appropriate height. 2. Hinge at your hips, letting the weight swing back between your legs. 3. Explosively drive hips forward, propelling the weight forward/up. 4. Let gravity bring it back as you hinge for the next rep. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Side Step Overhead Swing', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f34aa21e-dcea-4323-bbe7-2d305d5642e9', 'Seated Behind Head Military Press (Barbell)', 'Shoulders', 'Barbell, Flat Bench', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'This pressing exercise works your delts for improved shoulder strength and aesthetics. Secondary activation of your triceps provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. The barbell allows you to handle heavier loads for maximum strength gains. Shoulder development enhances both performance and upper body aesthetics.', '26031201', '26031201-Barbell-Seated-Behind-Head-Military-Press-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Grip a barbell with hands at the appropriate width for Barbell Seated Behind Head Military Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Complete all reps with control before resting.', 'Push', 'Push', 'Compound', 'Bilateral', NULL, 3, NULL, 10, 10, NULL, 4, 'Seated', NULL, 'Overhand', 'Wide', 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 99, 7, 9, TRUE, FALSE, 'shoulder_press', 'Seated Behind Head Military Press', 'lateral_raise, front_raise, rear_delt', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('f3608275-e582-47cb-a0fc-3d5d3f8d61d0', 'Lateral Raise (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'This raising exercise works your lateral delts for improved shoulder strength and aesthetics. The dumbbell variation provides freedom of movement and greater range of motion. Shoulder development enhances both performance and upper body aesthetics.', '3341201', '03341201-Dumbbell-Lateral-Raise_shoulder-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lateral Raise. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'lateral_raise', 'Lateral Raise', 'shoulder_press, front_raise, rear_delt', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('f3622034-1be0-49f0-8f71-5e6f34f37b2e', 'Lat Pulldown - Reverse Grip (Machine)', 'Back', 'Machine', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this pulling movement. You''ll also feel your biceps, upper back working to support the movement. The machine guides your movement path for safer, more controlled repetitions. Back development is crucial for pulling strength and overall upper body function.', '36151201', '36151201-Reverse-Grip-Machine-Lat-Pulldown-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Reverse Grip Machine Lat Pulldown. 2. Use a reverse grip (opposite of the standard grip for this exercise). 3. Pull the bar/handle down toward your upper chest. 4. Drive your elbows down and back, squeezing your lats. 5. Control the weight back up without letting it yank your arms. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 88, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Lat Pulldown - Reverse Grip', 'Lat Pulldown - Reverse Grip', TRUE, 'machine', FALSE, 3, 90, 4, 85, 88, 30, 92);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('f36e965e-ed6c-4c4b-8e27-21261d429665', 'Landmine 180 (Landmine)', 'Core', 'Landmine Attachment, Barbell', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. Building core stability helps with everything from heavy deadlifts to daily activities. Start with lighter weight to master the movement pattern.', '5621201', '05621201-Landmine-180_waist.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Set up in the starting position for Landmine 180. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Landmine 180', 'squat, bench_press, deadlift', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('f3707498-a392-442d-a192-c38f26c76bf3', 'Weighted Inverted Row', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. Your biceps work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. A strong back improves posture, prevents injury, and balances pressing movements.', '11841201', '11841201-Weighted-Inverted-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Continue for your target rep count, maintaining good form throughout. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'general_exercise', 'Weighted Inverted Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f370a07c-41f6-4eeb-8574-2c2b85bce9d9', 'Half Kneeling Single Arm Row (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. You''ll also feel your biceps, rear delts working to support the movement. Kneeling helps eliminate lower body momentum from the movement. The cable setup allows you to adjust the angle of resistance. A strong back improves posture, prevents injury, and balances pressing movements.', '82991201', '82991201-Cable-Half-Kneeling-Single-Arm-Row-(VERSION-2)-(ma.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Adjust the cable machine to the correct height and attachment for Cable Half Kneeling Single Arm Row. 2. Get into a half-kneeling position (one knee down, opposite foot forward). 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps on one side, then switch to the other side. 7. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'dumbbell_row', 'Half Kneeling Single Arm Row', 'bent_over_row, lat_pulldown, bicep_curl', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('f37d72e1-9d3b-4af2-b90f-6dc8d1062d6b', 'Stationary Arms Throw', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. A strong back improves posture, prevents injury, and balances pressing movements.', '96671201', '96671201-Stationary-Arms-Throw-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'arm_exercise', 'Stationary Arms Throw', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f38a5ef7-62d4-4fc2-afe5-3fa95833a469', 'Seated Single Leg Knee Extension', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This extension movement emphasizes your quadriceps for stronger, more powerful legs. The seated position helps isolate the target muscles by removing momentum. Leg training boosts metabolism and builds functional, real-world strength.', '105381201', '105381201-Seated-Single-Leg-Knee-Extension-(VERSION-2)-(mal.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Extend your legs until straight, squeezing your quads at the top. 3. Lower with control back to the starting position. 4. Complete all reps on one side, then switch to the other side. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 67, 5, 7, FALSE, TRUE, 'leg_extension', 'Seated Single Leg Knee Extension', 'squat, leg_press, lunge', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f38bef07-525d-49b4-8015-268a3fff02d4', 'Chest Raise And Rotate', 'Shoulders', 'Bodyweight', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'Target your delts with the Chest Raise And Rotate, an effective shoulder raising exercise. No equipment needed—your body provides all the resistance. Shoulder development enhances both performance and upper body aesthetics.', '52791201', '52791201-Chest-Raise-and-Rotate_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Raise the weight in the prescribed direction for Chest Raise And Rotate. 2. Lower with control, maintaining tension throughout. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'lateral_raise', 'Chest Raise And Rotate', 'shoulder_press, front_raise, rear_delt', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f39528bd-7ae0-4f7d-9173-3b8fcd164a2f', 'Glute Single Leg Bridge From B (Kettlebell)', 'Legs', 'Kettlebell', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Weighted Kettlebell Glute Single Leg Bridge From B is a hip-dominant bridging exercise that targets your glutes. You''ll also feel your hamstrings working to support the movement. The kettlebell grip position adds a unique training stimulus. Leg training boosts metabolism and builds functional, real-world strength.', '80171201', '80171201-Weighted-Kettlebell-Glute-Single-Leg-Bridge-from-B.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Select an appropriately weighted kettlebell for Weighted Kettlebell Glute Single Leg Bridge From B. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 53, 7, 8, TRUE, TRUE, 'glute_bridge', 'Glute Single Leg Bridge From B', 'hip_thrust, romanian_deadlift', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('f3ac53bf-ce3c-4188-8202-b58d05ecc3d8', 'Twist Front Raise', 'Shoulders', 'Bodyweight', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'A challenging plyometric exercise, the Twist Front Raise builds reactive power and improves conditioning. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '66721201', '66721201-Twist-Front-Raise-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Raise the weight in front of you to shoulder height. 2. Lower with control, maintaining tension throughout. 3. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'front_raise', 'Twist Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f3af5a01-997f-4b1e-97e0-0ad0ebc1868e', 'Seated Row (Chair)', 'Back', 'Chair', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. You''ll also feel your biceps, rear delts working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. Back development is crucial for pulling strength and overall upper body function.', '91011201', '91011201-Sitting-Row-on-a-Chair-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:37.877283+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Continue for your target rep count, maintaining good form throughout. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Row On A Chair', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f3d627d0-c7f6-4c26-9e5c-b8318503cd03', 'Zercher Squat (Smith Machine)', 'Legs', 'Smith Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. The fixed path allows you to focus purely on muscular effort. Strong legs are the foundation for athletic performance and functional fitness. Progress gradually by increasing resistance over time.', '15981201', '15981201-Smith-Zercher-Squat_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Zercher Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 35, 7, 9, TRUE, FALSE, 'squat', 'Smith Zercher Squat', 'Zercher Squat', FALSE, 'smith_machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('f3e0c6f8-643b-4e99-92c9-1ec702806514', 'Curl Press Extension (Dumbbell)', 'Arms', 'Dumbbells', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Dumbbell Curl Press Extension targets your triceps through a pressing motion. The forearms assist throughout the movement, making this a well-rounded exercise. Dumbbells allow each arm to work independently, helping correct imbalances. Dedicated arm training builds both strength and muscular definition.', '58841201', '58841201-Dumbbell-Curl-Press-Extension-(male)_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Curl Press Extension. 2. Execute the pressing motion for Dumbbell Curl Press Extension, extending through the target muscles. 3. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'general_exercise', 'Curl Press Extension', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('f3e13df5-9a67-40de-b2c4-75b4e487e67b', 'Biceps Stretch Behind The Back', 'Arms', 'Bodyweight', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this stretching movement that targets the front of your arms. A versatile bodyweight movement perfect for home or gym training. Arm strength supports grip, pulling, and pushing in compound movements.', '14801201', '14801201-Biceps-Stretch-Behind-The-Back_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Set up in the starting position for Biceps Stretch Behind The Back. 2. Execute the movement with proper form, focusing on your biceps. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Biceps Stretch Behind The Back', 'tricep_extension, hammer_curl', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('f3e64165-9ff6-445d-990e-0b78355a99ba', 'Bridge Mountain Climber (cross Body)', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors","Shoulders"}'::text[], 'The Bridge Mountain Climber (cross Body) is a core bridging exercise that primarily targets your abs. Your hip flexors, shoulders work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '1411201', '01411201-Bridge---Mountain-Climber-(Cross-Body)-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'mountain_climber', 'Bridge Mountain Climber', 'hip_thrust, romanian_deadlift, leg_curl', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('f3e7804b-56ab-42d1-8293-e30ed150d7aa', 'Prone Ys (TRX)', 'Core', 'TRX', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Suspender Prone Ys is a core movement exercise that primarily targets your abs. The lying position provides back support and helps isolate the target muscles. The TRX allows you to adjust difficulty by changing your body angle. Building core stability helps with everything from heavy deadlifts to daily activities.', '75081201', '75081201-Suspender-Prone-Ys_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Prone Ys. 2. Lie face down (prone position) for Suspender Prone Ys. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'general_exercise', 'Suspender Prone Ys', 'squat, bench_press, deadlift', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('f3ebe025-5a28-4890-9caf-0f1409deb71c', 'Single Arm Twisting Seated Row (Band)', 'Back', 'Resistance Band, Anchor Point', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Band One Arm Twisting Seated Row is a rowing exercise that builds thickness in your upper back. Your biceps, lats work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. The band creates increasing tension as it stretches, challenging the lockout. A strong back improves posture, prevents injury, and balances pressing movements.', '9901201', '09901201-Band-One-Arm-Twisting-Seated-Row_Back.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Secure the resistance band appropriately for Band One Arm Twisting Seated Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps on one side, then switch to the other side. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 74, 7, 8, TRUE, TRUE, 'cable_row', 'Single Arm Twisting Seated Row', 'bent_over_row, lat_pulldown, bicep_curl', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('f40470f6-ee04-4bce-a0a6-8721d785f2ae', 'Lying Butterfly (abduction)', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this flying movement focusing on your glute med/abductors. The front delts assist throughout the movement, making this a well-rounded exercise. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '67031201', '67031201-Lying-Butterfly-(Abduction)-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Lie down in the appropriate position for Lying Butterfly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'groin_stretch', 'Lying Butterfly', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f409666d-f13c-4635-a146-d118f914434a', 'Lateral Raise (Machine)', 'Shoulders', 'Lever Machine', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this raising movement focusing on your lateral delts. Machine exercises are great for isolating muscles and training to failure safely. Strong shoulders improve overhead strength and support nearly all upper body movements.', '5841201', '05841201-Lever-Lateral-Raise_shoulder.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Lateral Raise. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 88, 5, 7, FALSE, TRUE, 'lateral_raise', 'Lever Lateral Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('f40994aa-f095-47c0-8870-4bf77d2d245e', 'Seated Chest Open', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Shoulders"}'::text[], 'The Seated Chest Open (front Pov) provides a deep stretch for your chest, ideal for recovery and mobility work. Your shoulders work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '61541201', '61541201-Sitting-Chest-Open-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Chest Open. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Maintain consistent tempo throughout the set. Ideal for chest strength and endurance.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'chest_exercise', 'Seated Chest Open', 'bench_press, chest_fly, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f420530c-aa66-41de-835a-298cfc1a52fe', 'Roll Biceps Lying On Floor', 'Arms', 'Bodyweight', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this movement movement that targets the front of your arms. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Dedicated arm training builds both strength and muscular definition.', '54131201', '54131201-Roll-Biceps-Lying-on-Floor-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Position yourself on the floor for Roll Biceps Lying On Floor. 2. Lie down in the appropriate position for Roll Biceps Lying On Floor. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'arm_exercise', 'Roll Biceps Lying On Floor', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f426f39f-1825-4504-9edb-0add55be77a0', 'Lean Back Heel Tap', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts. Excellent for pre-exhausting the target muscle before compound lifts.', '78511201', '78511201-Lean-Back-Heel-Tap-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Set up in the starting position for Lean Back Heel Tap. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Lean Back Heel Tap', 'stretch_hip, dynamic_warmup, yoga_pose', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f441229f-3afc-4b13-a2f8-14b6fd4e0ef4', 'Pendulum (TRX)', 'Core', 'TRX', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. The TRX allows you to adjust difficulty by changing your body angle. A strong core improves posture, protects your spine, and enhances all other lifts.', '11561201', '11561201-Suspender-Pendulum-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Pendulum. 2. Set up in the starting position for Suspender Pendulum. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'general_exercise', 'Suspender Pendulum', 'squat, bench_press, deadlift', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('f44e4dac-65e7-47f7-a7e5-f6b8dbb84e6c', 'Side Step Hands On Waist', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity stepping exercise that challenges your entire body. Your quads work as secondary movers, adding to the training stimulus. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '92521201', '92521201-Side-Step-Hands-On-Waist-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.303932+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Side Step Hands On Waist. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Side Step Hands On Waist', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f4546216-569f-437a-9920-97b730a63d92', 'Swimmer Kicks', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build leg strength with this kicking movement focusing on your full body. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '32071201', '32071201-Swimmer-Kicks-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:39.623429+00', '1. Set up in the starting position for Swimmer Kicks. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'swimming', 'Swimmer Kicks', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f457e92c-c7d7-42b1-88c3-0614033967f6', 'Swing (Kettlebell)', 'Full Body', 'Kettlebell', '{"Full Body"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Kettlebell Swing is a lower body swinging exercise that targets your full body. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. The kettlebell grip position adds a unique training stimulus. Lower body strength improves everything from walking to heavy compound lifts.', '5491201', '05491201-Kettlebell-Swing_Hips-FIX2_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Select an appropriately weighted kettlebell for Kettlebell Swing. 2. Hinge at your hips, letting the weight swing back between your legs. 3. Explosively drive hips forward, propelling the weight forward/up. 4. Let gravity bring it back as you hinge for the next rep. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'general_exercise', 'Swing', 'squat, bench_press, deadlift', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('f45ec3f9-82db-40b0-a4ec-3405029240e7', 'Plank Power Tuck', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'A challenging plyometric exercise, the Plank Power Tuck builds reactive power and improves conditioning. Your shoulders, lower back work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '71951201', '71951201-Plank-Power-Tuck-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Perform the concentric (lifting) phase explosively with maximum effort. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Plank Power Tuck', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('f4666f12-78b7-422f-b652-18958e5dd0ee', 'Triceps Dip (Machine)', 'Arms', 'Tricep Extension Machine', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Lever Triceps Dip (plate Loaded) is an arm dipping exercise targeting your chest. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. The machine guides your movement path for safer, more controlled repetitions. Arm strength supports grip, pulling, and pushing in compound movements.', '105871201', '105871201-Lever-Triceps-Dip-(plate-loaded)-(female)_Upper-A.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Triceps Dip. 2. Lower your body by bending your elbows to about 90 degrees. 3. Push back up until your arms are fully extended. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'dip', 'Lever Triceps Dip', 'bench_press, tricep_pushdown, push_up', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('f469860d-f281-4816-822e-d4244fd54c02', 'Star Push Up (TRX)', 'Chest', 'TRX', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Strengthen your midsection with this pushing movement that works your abs. Your triceps, front delts work as secondary movers, adding to the training stimulus. The TRX allows you to adjust difficulty by changing your body angle. A strong core improves posture, protects your spine, and enhances all other lifts.', '11461201', '11461201-Suspender-Star-Push-up-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Star Push Up. 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'push_up', 'Suspender Star Push Up', 'bench_press, chest_fly, dip', TRUE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('f47205db-9563-4839-9f91-0b32c02191c5', 'Bent Over Row (Machine)', 'Back', 'Row Machine', '{"Back","Lats"}'::text[], '{"Biceps","Rear Delts"}'::text[], 'The Lever Bent Over Row (plate Loaded) is a rowing exercise that builds thickness in your upper back. You''ll also feel your biceps, lats working to support the movement. The bent over position requires core engagement to maintain a neutral spine. The machine guides your movement path for safer, more controlled repetitions. A strong back improves posture, prevents injury, and balances pressing movements.', '30971201', '30971201-Lever-Bent-over-Row-(plate-loaded)-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Bent Over Row. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Repeat for the prescribed number of repetitions. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 78, 7, 9, TRUE, FALSE, 'bent_over_row', 'Lever Bent Over Row', 'cable_row, dumbbell_row, t_bar_row, lat_pulldown', FALSE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('f472ef22-4c18-4269-844a-8aaf15e9fcd8', 'Forward Step Front Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Build leg strength with this stabilization movement focusing on your abs. You''ll also feel your shoulders, lower back working to support the movement. Leg training boosts metabolism and builds functional, real-world strength.', '39591201', '39591201-Forward-Step-Front-Plank-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Set up a box or step platform at the appropriate height. 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Forward Step Front Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('f47738e0-ac7b-4fe0-b820-0cb0ccedca63', 'High Row (Plate Loaded Machine)', 'Back', 'Row Machine', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. You''ll also feel your biceps, rear delts working to support the movement. The fixed path allows you to focus purely on muscular effort. A strong back improves posture, prevents injury, and balances pressing movements.', '5811201', '05811201-Lever-High-Row-(plate-loaded)_Back.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever High Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 78, 7, 9, TRUE, FALSE, 'cable_row', 'Lever High Row', 'squat, bench_press, deadlift', TRUE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('f47b6329-afea-4915-bea1-81826e8b4206', 'Glute Ham Developer Hip Extension (Machine)', 'Legs', 'GHD Machine', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger glutes with this extension movement focused on hip extension. The hamstrings assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '47621201', '47621201-Glute-Ham-Developer-Hip-Extension_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Extend through the target joint(s) for Glute Ham Developer Hip Extension. 2. Set up in the starting position for Glute Ham Developer Hip Extension. 3. Execute the movement with proper form, focusing on your glutes. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'glute_kickback', 'Glute Ham Developer Hip Extension', 'hip_thrust, glute_bridge, leg_curl', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('f47c96f8-453d-498d-87f4-cb4730f7a84c', 'Seated Side To Side Forward Backward Neck Stretch', 'Neck', 'Bodyweight', '{"Neck"}'::text[], '{"Traps"}'::text[], 'Designed to lengthen your neck, the Seated Side To Side Forward Backward Neck Stretch helps improve mobility and prevent stiffness. The seated position helps isolate the target muscles by removing momentum. Flexibility work like this enhances performance and prevents stiffness.', '85681201', '85681201-Sitting-Side-to-Side-Forward-Backward-Neck-Stretch.mp4', 'female', FALSE, '2025-12-03 23:26:37.877283+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Side To Side Forward Backward Neck Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 5. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'neck_stretch', 'Seated Side To Side Forward Backward Neck Stretch', 'stretch_hip, stretch_hamstring, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('f47e9374-ad50-4d98-bc02-03c7daced175', 'Incline Hammer Chest Press (Machine)', 'Chest', 'Chest Press Machine', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'Target your chest with the Lever Incline Hammer Chest Press, an effective pressing movement for upper body strength. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. The incline angle shifts emphasis toward the upper portion of the target muscles. Machine exercises are great for isolating muscles and training to failure safely. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '11951201', '11951201-Lever-Incline-Hammer-Chest-Press_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Incline Hammer Chest Press. 2. Use a hammer/neutral grip with palms facing each other throughout. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 81, 7, 8, TRUE, TRUE, 'incline_press', 'Lever Incline Hammer Chest Press', 'bench_press, shoulder_press, chest_fly', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('f4a33853-bfcd-4e43-969f-77890c3ff6a0', 'Walkout To Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pushing exercise engages your abs for improved core stability and strength. You''ll also feel your triceps, front delts working to support the movement. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention. Quality repetitions are more important than quantity.', '105221201', '105221201-Walkout-to-Push-up-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Walkout To Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f4a3c438-9c45-42d9-a9dd-4b217c1215a3', 'Lying Incline Side Leg Raise (Cable)', 'Core', 'Cables', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Cable Lying Incline Side Leg Raise is a lower body raising exercise that targets your hip abductors. Secondary activation of your glutes provides additional muscle engagement. Performing this lying down removes momentum for stricter form. The cable setup allows you to adjust the angle of resistance. Lower body strength improves everything from walking to heavy compound lifts.', '99271201', '99271201-Cable-Lying-Incline-Side-Leg-Raise-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable Lying Incline Side Leg Raise. 2. Lie on your side with your body aligned. 3. Keeping legs mostly straight, raise them toward the ceiling. 4. Lower with control, stopping just before touching down. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 83, 5, 7, FALSE, TRUE, 'leg_raise', 'Lying Incline Side Leg Raise', 'crunch, plank, v_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('f4ab7b6a-874d-4680-b8fc-8f69d1308c3c', 'Side Two Front Toe Touching', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Side Two Front Toe Touching, focusing on your abs. Secondary activation of your hip flexors provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '32501201', '32501201-Side-Two-Front-Toe-Touching-(female).mp4', 'female', FALSE, '2025-12-03 23:26:37.429219+00', '1. Set up in the starting position for Side Two Front Toe Touching. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'toe_touch', 'Side Two Front Toe Touching', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f4ace20d-9de6-4f9d-b990-0f085903561a', 'Standing Isometric Hold Calf Raise', 'Legs', 'Bodyweight', '{"Calves"}'::text[], '{}'::text[], 'Build stronger calves with this targeted raising exercise. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts. Can be modified for beginners or progressed for advanced athletes.', '93101201', '93101201-Standing-Isometric-Hold-Calf-Raise-(female)_Calves.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Stand tall with your feet firmly planted. 2. Lower your heels below the platform to get a full stretch. 3. Rise up onto your toes as high as possible, squeezing your calves. 4. Lower with control and repeat. 5. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'calf_raise', 'Standing Isometric Hold Calf Raise', 'calf_raise, seated_calf_raise', FALSE, 'bodyweight', TRUE, 3, 60, 2, 70, 88, 95, 65),
('f4b063fe-65a4-40b0-a8c5-b8cdcd7f3f25', 'Stepback Diagonal Rainbow Arms', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Stepback Diagonal Rainbow Arms is an explosive exercise that combines cardiovascular training with dynamic stepping movements. Secondary activation of your quads provides additional muscle engagement. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '98991201', '98991201-Stepback-Diagonal-Rainbow-Arms-(female)_Plyometric.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Stepback Diagonal Rainbow Arms. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Stepback Diagonal Rainbow Arms', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f4c1e81a-196a-4da0-a030-037b9d2077d8', 'Back Squeeze Knee Lift', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities. A staple exercise that belongs in most training programs. Consistency with this movement will yield noticeable results.', '98561201', '98561201-Back-Squeeze-Knee-Lift-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Set up in the starting position for Back Squeeze Knee Lift. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Back Squeeze Knee Lift', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f4c6ab39-2a63-454d-bf97-740b58b98f9f', 'Cross Body Mountain Climber Hop Over Bench', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors","Shoulders"}'::text[], 'A challenging plyometric exercise, the Cross Body Mountain Climber Hop Over Bench builds reactive power and improves conditioning. Your shoulders, core work as secondary movers, adding to the training stimulus. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '106371201', '106371201-Cross-Body-Mountain-Climber-Hop-over-Bench_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. From plank position, drive one knee toward your chest. 2. Quickly switch legs, bringing the other knee forward. 3. Continue alternating at a quick pace while maintaining plank form. 4. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'mountain_climber', 'Cross Body Mountain Climber Hop Over Bench', 'burpee, plank, high_knees', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('f4c93ded-fc41-432d-9b8e-16c6d108a77f', 'Standing Chest Fly - Alternating', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Target your chest with the Bodyweight Standing Alternate Chest Fly, an effective flying movement for upper body strength. Secondary activation of your front delts provides additional muscle engagement. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '88111201', '88111201-Bodyweight-Standing-Alternate-Chest-Fly-(female)_C.mp4', 'female', FALSE, '2025-12-03 23:26:31.475486+00', '1. Stand tall with your feet firmly planted. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Alternate between sides/arms/legs with each repetition. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'chest_fly', 'Standing Chest Fly - Alternating', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f4ca5dfc-c7ad-4134-8446-2204fc240fd1', 'Side Lying External Rotation On A Bench (Dumbbell)', 'Shoulders', 'Dumbbells, Flat Bench', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Target your rotator cuff with the Dumbbell Side Lying External Rotation (on A Bench), an effective shoulder rotation exercise. The lying position provides back support and helps isolate the target muscles. Using dumbbells requires more stabilization than barbell variations. Shoulder development enhances both performance and upper body aesthetics.', '58171201', '58171201-Dumbbell-Side-Lying-External-Rotation-(on-a-bench).mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Side Lying External Rotation. 2. Lie on your side with your body aligned. 3. Rotate your torso through the movement pattern for Dumbbell Side Lying External Rotation. 4. Control the rotation in both directions—avoid using momentum. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 44, 7, 8, TRUE, TRUE, 'external_rotation', 'Side Lying External Rotation', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('f4d844cc-2201-4705-b354-1bcf2963e45f', 'Lying Leg Circle Hip Raise', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Lying Leg Circle Hip Raise, focusing on your abs. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '72541201', '72541201-Lying-Leg-Circle-Hip-Raise-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:27.145158+00', '1. Lie down in the appropriate position for Lying Leg Circle Hip Raise. 2. Set up in the starting position for Lying Leg Circle Hip Raise. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_exercise', 'Lying Leg Circle Hip Raise', 'squat, leg_curl, calf_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f4d85855-3483-4d87-b8be-6f4dc19f9bbc', 'Low Lunge To Hamstring Stretch Advanced (Gymnastic Rings)', 'Legs', 'Gymnastic Rings', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Low Lunge To Hamstring Stretch (advanced) provides a deep stretch for your hamstrings, ideal for recovery and mobility work. Your lower back work as secondary movers, adding to the training stimulus. Include this in your routine for better mobility and reduced muscle tension.', '88681201', '88681201-Low-Lunge-to-Hamstring-Stretch-(advanced)-(female).mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Move into the stretch position for Low Lunge To Hamstring Stretch. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 48, 2, 6, FALSE, TRUE, 'hamstring_stretch', 'Low Lunge To Hamstring Stretch', 'squat, split_squat, step_up, leg_press', FALSE, 'gymnastic_rings', TRUE, 1, 30, 2, 68, 85, 85, 70),
('f4dbb786-b1d4-461c-8587-578c204dcf74', 'Goblet Pulse Squat (Kettlebell)', 'Legs', 'Kettlebell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Kettlebell Goblet Pulse Squat is a squatting exercise that primarily loads your quadriceps. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Kettlebells are excellent for building functional, real-world strength. Strong legs are the foundation for athletic performance and functional fitness.', '80011201', '80011201-Kettlebell-Goblet-Pulse-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Select an appropriately weighted kettlebell for Kettlebell Goblet Pulse Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. At the bottom or top, pulse up and down in small movements before completing the rep. 6. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'goblet_squat', 'Goblet Pulse Squat', 'squat, front_squat, lunge', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('f4e2e429-233b-4840-8322-63625fdd4cd2', 'Hanging Hollow Hold (Pull-Up Bar)', 'Core', 'Pull-Up Bar', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Hanging Hollow Hold, focusing on your abs. Secondary activation of your hip flexors, grip provides additional muscle engagement. Hanging adds a grip and core stability component to the exercise. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '65471201', '65471201-Hanging-Hollow-Hold-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Grip the bar and hang with arms fully extended, engaging your shoulders. 2. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'hollow_hold', 'Hanging Hollow Hold', 'squat, bench_press, deadlift', FALSE, 'pull_up_bar', TRUE, 3, 90, 4, 70, 88, 95, 65),
('f4f00ac1-9648-4dc4-a13b-c221351eeebc', 'Seated Twist On Floor (Cable)', 'Core', 'Cables', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Cable Seated Twist On Floor targets your obliques through a twisting motion, building rotational core strength. You''ll also feel your abs working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. The cable setup allows you to adjust the angle of resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '24341201', '24341201-Cable-Seated-Twist-on-Floor-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Seated Twist On Floor. 2. Position yourself on the floor for Cable Seated Twist On Floor. 3. Sit on the floor with your legs positioned as required. 4. Rotate your torso through the movement pattern for Cable Seated Twist On Floor. 5. Control the rotation in both directions—avoid using momentum. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 57, 5, 7, FALSE, TRUE, 'russian_twist', 'Seated Twist On Floor', 'plank, crunch, leg_raise', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('f4f76449-6baf-4ecd-ba6d-76c972686b45', 'Step Up (Barbell)', 'Legs', 'Barbell, Step Platform', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Barbell Step Up is a stepping exercise that primarily loads your quadriceps. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Using a barbell provides stability for progressive overload. Lower body strength improves everything from walking to heavy compound lifts.', '1141201', '01141201-Barbell-Step-up_Hips-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Grip a barbell with hands at the appropriate width for Barbell Step Up. 2. Set up a box or step platform at the appropriate height. 3. Step one foot onto the elevated surface. 4. Drive through that foot to lift your body up onto the platform. 5. Step back down with control and repeat. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'step_up', 'Step Up', 'lunge, split_squat, squat', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('f5089273-b2a7-41f1-810c-dfc1cec0b749', 'Assisted Shoulder Abduction Side Step (TRX)', 'Legs', 'TRX', '{"Glutes","Hips"}'::text[], '{"Hamstrings"}'::text[], 'Elevate your training with this stepping exercise that develops speed, power, and coordination. You''ll also feel your quads working to support the movement. The TRX allows you to adjust difficulty by changing your body angle. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '101591201', '101591201-Suspender-Assisted-Shoulder-Abduction-Side-Step-(.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Assisted Shoulder Abduction Side Step (. 2. Set up a box or step platform at the appropriate height. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'hip_abduction', 'Suspender Assisted Shoulder Abduction Side Step (', 'lateral_raise, shoulder_press, front_raise', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('f508c777-4c48-4751-8deb-8ac85d9e5f98', 'Crunch (hands Overhead)', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Crunch (hands Overhead), focusing on your abs. You''ll also feel your hip flexors working to support the movement. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '2671201', '02671201-Crunch-(hands-overhead)_waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f50ad69e-5c7c-4ce8-8809-6af3770b2834', 'Kneeling Low Fly (Dumbbell)', 'Chest', 'Dumbbells, Flat Bench', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Target your chest with the Dumbbell Kneeling Low Fly, an effective flying movement for upper body strength. Secondary activation of your front delts provides additional muscle engagement. The kneeling position adds a core stability challenge. The dumbbell variation provides freedom of movement and greater range of motion. A well-developed chest contributes to upper body strength and aesthetics.', '104601201', '104601201-Dumbbell-Kneeling-Low-Fly-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Kneeling Low Fly. 2. Kneel on the floor (use a pad for comfort if needed). 3. With a slight bend in your elbows, move the weight in a wide arc. 4. Squeeze your chest muscles at the center/top of the movement. 5. Return with control, feeling the stretch at the bottom. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'chest_fly', 'Kneeling Low Fly', 'bench_press, incline_press, push_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('f52bc652-c0b3-4847-a508-7556ed176118', 'Pull Up (TRX)', 'Back', 'TRX', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this pulling movement. Secondary activation of your biceps, upper back provides additional muscle engagement. The TRX allows you to adjust difficulty by changing your body angle. A strong back improves posture, prevents injury, and balances pressing movements.', '10881201', '10881201-Suspender-Pull-up-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Pull Up. 2. Pull yourself up by driving your elbows down and back. 3. Continue until your chin clears the bar, then lower with control to a full hang. 4. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'pull_up', 'Suspender Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('f53b0daf-02a8-4c2a-868f-2612ad55d087', 'Lying Single Arm Triceps Stretch (Stick)', 'Arms', 'Bodyweight', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Target your triceps with this stretching stretch that helps restore range of motion. Your shoulders work as secondary movers, adding to the training stimulus. Performing this lying down removes momentum for stricter form. Flexibility work like this enhances performance and prevents stiffness.', '107401201', '107401201-Stick-Lying-Single-Arm-Triceps-Stretch-(male)_Str.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Lie down in the appropriate position for Stick Lying Single Arm Triceps Stretch. 2. Move into the stretch position for Stick Lying Single Arm Triceps Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 5. Switch sides and repeat for equal time. 6. Complete all reps on one side, then switch to the other side.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Lying', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 35, 2, 6, FALSE, TRUE, 'stretch_general', 'Stick Lying Single Arm Triceps Stretch', 'bicep_curl, dip', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('f53ce09c-192e-41ec-8668-b07af1b9e772', 'Down Dog Knee To Nose', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Use this stretch to open up your full body area and enhance overall flexibility. Regular stretching improves flexibility, reduces injury risk, and aids recovery. A staple exercise that belongs in most training programs.', '62891201', '62891201-Down-Dog-Knee-to-Nose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:32.624497+00', '1. Move into the stretch position for Down Dog Knee To Nose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'knee_stretch', 'Down Dog Knee To Nose', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f540ca05-5585-46a2-8883-896b7bdc5f0a', 'Standing Front Heel Tap Triceps Kickback', 'Arms', 'Bodyweight', '{"Triceps"}'::text[], '{"Rear Delts"}'::text[], 'Build stronger glutes with this kicking movement focused on hip extension. The hamstrings assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '97891201', '97891201-Standing-Front-Heel-Tap-Triceps-Kickback-(female)_.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Begin in a standing position with good posture. 2. Keep your upper arm stationary and extend your forearm back. 3. Squeeze at full extension, then return with control. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Standing Front Heel Tap Triceps Kickback', 'tricep_pushdown, tricep_extension', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f54e63eb-d1a5-4c90-8f97-18cef889d83a', 'Assisted Straight Arms Lying Stretch_chest', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Use this stretch to open up your chest area and enhance overall flexibility. Performing this lying down removes momentum for stricter form. Include this in your routine for better mobility and reduced muscle tension.', '17891201', '17891201-Assisted-Straight-Arms-Lying-Stretch_Chest_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. Lie down in the appropriate position for Assisted Straight Arms Lying Stretch_chest. 2. Move into the stretch position for Assisted Straight Arms Lying Stretch_chest. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Lying', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Assisted Straight Arms Lying Stretch_chest', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('f5648366-4878-4a1a-a0f0-13812a19b403', 'Standing Chest Cross Stretch', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'A challenging plyometric exercise, the Standing Chest Cross Stretch builds reactive power and improves conditioning. You''ll also feel your shoulders, core working to support the movement. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '97071201', '97071201-Standing-Chest-Cross-Stretch-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Chest Cross Stretch. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'stretch_general', 'Standing Chest Cross Stretch', 'stretch_shoulder, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('f5692890-7f2a-41b0-b09e-e4600306badd', 'Standing Hip Stretch', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'The Standing Hip Stretch is a flexibility exercise that targets your hips, helping to release tension and improve range of motion. You''ll also feel your glutes working to support the movement. The standing position engages your core for stability. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '85061201', '85061201-Standing-Hip-Stretch-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Stand with feet about shoulder-width apart. 2. Move into the stretch position for Standing Hip Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'hip_stretch', 'Standing Hip Stretch', 'stretch_hamstring, stretch_glute, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('f56b9849-c51f-42a0-bac2-e7f19591259b', 'Standing Angel (Wall Supported)', 'Shoulders', 'Wall', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This movement exercise works your delts for improved shoulder strength and aesthetics. The standing position engages your core for stability. Shoulder development enhances both performance and upper body aesthetics.', '84351201', '84351201-Standing-Angel-Wall-Supported-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Position yourself at the appropriate distance from a wall. 2. Stand tall with your feet firmly planted. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 44, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Angel Wall Supported', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f5706a53-ff1e-4dcc-a4db-49523bc22418', 'Side Bridge Hip Abduction', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger glutes with this bridging movement focused on hip extension. Secondary activation of your glutes provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '7041201', '07041201-Side-Bridge-Hip-Abduction-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Complete all reps with control before resting. Maintain a neutral spine throughout. An effective movement for your legs routine.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_abduction', 'Side Bridge Hip Abduction', 'hip_thrust, romanian_deadlift, leg_curl', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f5759005-8808-4797-8cb7-74cd843a3a4c', 'High Low Lunge Split Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '98801201', '98801201-High-Low-Lunge-Split-Squat-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Focus on maintaining proper breathing throughout. This exercise is excellent for quads development.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'split_squat', 'High Low Lunge Split Squat', 'lunge, bulgarian_split_squat, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f59b0285-2cc5-44ef-b1cf-b641c6ca5fe8', 'Side Clamp', 'Legs', 'Bodyweight', '{"Glutes","Hips"}'::text[], '{"Hamstrings"}'::text[], 'The Side Clamp is a lower body movement exercise that targets your glute med/abductors. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '56891201', '56891201-Side-Clamp-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Set up in the starting position for Side Clamp. 2. Execute the movement with proper form, focusing on your glute med/abductors. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_abduction', 'Side Clamp', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f5a222f3-bade-485e-a09f-29a44ee106b9', 'Weighted Hanging Leg Hip Raise (Pull-Up Bar)', 'Core', 'Pull-Up Bar', '{"Lower Abs"}'::text[], '{"Hip Flexors","Forearms"}'::text[], 'Strengthen your midsection with this raising movement that works your abs. You''ll also feel your hip flexors, grip working to support the movement. The hanging position challenges your grip while targeting the primary muscles. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '8661201', '08661201-Weighted-Hanging-leg-hip-raise_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Grip the bar and hang with arms fully extended, engaging your shoulders. 2. Set up in the starting position for Weighted Hanging Leg Hip Raise. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Weighted Hanging Leg Hip Raise', 'crunch, plank, v_up', FALSE, 'pull_up_bar', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f5a78bb1-beaa-4efc-9fc3-e93bc5d7b277', 'Ring Russian Dip (Gymnastic Rings)', 'Chest', 'Gymnastic Rings', '{"Lower Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build stronger triceps with this dipping exercise for bigger arms. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. Arm strength supports grip, pulling, and pushing in compound movements.', '75161201', '75161201-Ring-Russian-Dip-(male)_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Lower your body by bending your elbows to about 90 degrees. 2. Push back up until your arms are fully extended. 3. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement. Perfect for targeting your triceps.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'dip', 'Ring Russian Dip', 'bench_press, tricep_pushdown, push_up', TRUE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('f5b1c037-13d9-4f2c-ba14-958f929787c4', 'Seated Punch (Chair)', 'Chest', 'Chair', '{"Chest"}'::text[], '{"Shoulders"}'::text[], 'This movement exercise focuses on your pectorals for improved chest strength and development. The shoulders assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. A well-developed chest contributes to upper body strength and aesthetics.', '90931201', '90931201-Sitting-Punch-on-a-Chair-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:37.877283+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction. This exercise is excellent for chest development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'boxing', 'Seated Punch On A Chair', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f5b289a7-026c-453a-b83e-44f416863591', 'Standing Clasp Hands Shoulders Forward Swing', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Develop functional strength with the Standing Clasp Hands Shoulders Forward Swing, a comprehensive swinging exercise. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Full body exercises are time-efficient and build functional, real-world strength.', '97221201', '97221201-Standing-Clasp-Hands-Shoulders-Forward-Swing-(male.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Stand tall with your feet firmly planted. 2. Hinge at your hips, letting the weight swing back between your legs. 3. Explosively drive hips forward, propelling the weight forward/up. 4. Let gravity bring it back as you hinge for the next rep. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Standing Clasp Hands Shoulders Forward Swing', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f5b894ee-b3b9-458f-b3bb-26ef0aa17ac8', 'Single Arm Seated Delt Row (Band)', 'Back', 'Resistance Band, Anchor Point', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Band One Arm Seated Delt Row is a rowing exercise that targets your delts for shoulder development. Secondary activation of your biceps, rear delts provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. Resistance bands provide accommodating resistance that increases through the range of motion. Shoulder development enhances both performance and upper body aesthetics.', '100911201', '100911201-Band-One-Arm-Seated-Delt-Row-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band One Arm Seated Delt Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps on one side, then switch to the other side. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Single Arm Seated Delt Row', 'bent_over_row, lat_pulldown, bicep_curl', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('f5d12984-1770-4a1c-b8af-c2f8839a3801', 'Tilt And Extend', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Tilt And Extend, focusing on your abs. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '97191201', '97191201-Tilt-and-Extend-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Set up in the starting position for Tilt And Extend. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Tilt And Extend', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f5d5a928-a9d4-48e9-b7e1-d5436a95bec0', 'Side Plank Side Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders"}'::text[], 'This crunching movement focuses on your obliques for a complete core workout. You''ll also feel your abs working to support the movement. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '72141201', '72141201-Side-Plank-Side-Crunch-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Complete all reps with control before resting. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'side_plank', 'Side Plank Side Crunch', 'plank, leg_raise, russian_twist, sit_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f5de836b-7e7b-4fbc-a7b7-ff99d8ec0922', 'Side Lunge Stretch (advanced)', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Inner Thighs"}'::text[], 'Use this stretch to open up your quads area and enhance overall flexibility. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Include this in your routine for better mobility and reduced muscle tension. Focus on controlled form throughout each repetition.', '88711201', '88711201-Side-Lunge-Stretch-(VERSION-2)-(advanced)-(female).mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Step to the side, bending that knee while keeping the other leg straight. 2. Push through your front/working leg to return to the starting position. 3. Move into the stretch position for Side Lunge Stretch. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 6. Switch sides and repeat for equal time. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 60, 2, 6, FALSE, TRUE, 'hip_stretch', 'Side Lunge Stretch', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('f5e1265b-c4fe-465c-a536-690f4549975c', 'Forward And Top Wall Push (Wall)', 'Chest', 'Wall', '{"Chest"}'::text[], '{}'::text[], 'Build a stronger chest with this pushing movement that develops pressing power. A well-developed chest contributes to upper body strength and aesthetics.', '76611201', '76611201-Forward-and-Top-Wall-Push-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Position yourself at the appropriate distance from a wall. 2. Set up in the starting position for Forward And Top Wall Push. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'general_exercise', 'Forward And Top Wall Push', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f5e4bbc9-2f4b-4566-a2b3-6dd234da08b1', 'Slopes Towards Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Include this in your routine for better mobility and reduced muscle tension. Aim for full range of motion on every rep. Consistency with this movement will yield noticeable results.', '43121201', '43121201-Slopes-Towards-Stretch-(male)_Back.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Move into the stretch position for Slopes Towards Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'back_stretch', 'Slopes Towards Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('f6041c67-2ba5-45f3-9359-d9e54c875322', 'Standing Y Up', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this movement movement focusing on your delts. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Strong shoulders improve overhead strength and support nearly all upper body movements.', '81401201', '81401201-Standing-Y-Up-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Y Up. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Y Up', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f6238b2b-1223-44f2-a5a0-9cf7711d775f', 'Lying Single Leg Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lying Single Leg Raise is a lower body raising exercise that targets your abs. You''ll also feel your hip flexors working to support the movement. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '32671201', '32671201-Lying-Single-Leg-Raise-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying Single Leg Raise. 2. Keeping legs mostly straight, raise them toward the ceiling. 3. Lower with control, stopping just before touching down. 4. Complete all reps on one side, then switch to the other side. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'leg_raise', 'Lying Single Leg Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f64e045b-1bce-41f0-844e-882ce1433dcd', 'Seated Tibialis Anterior Press', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger calves with this targeted pressing exercise. Being seated provides stability, allowing you to focus on the working muscles. Strong legs are the foundation for athletic performance and functional fitness.', '67591201', '67591201-Seated-Tibialis-Anterior-Press-(female)_Calves_.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Execute the pressing motion for Seated Tibialis Anterior Press, extending through the target muscles. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Tibialis Anterior Press', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f654ed25-c89a-4fb1-91f9-c625c407492c', 'Standing Crunch Rope (Cable)', 'Core', 'Cables', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Cable Standing Crunch (rope Attachment), focusing on your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. Cable resistance creates smooth, continuous muscle engagement. Building core stability helps with everything from heavy deadlifts to daily activities.', '26741201', '26741201-Cable-Standing-Crunch-(with-rope-attachment)-(female)_waist.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing Crunch. 2. Stand tall with your feet firmly planted. 3. Curl your shoulders off the floor by contracting your abs. 4. Don''t pull on your neck—focus on the abdominal contraction. 5. Lower with control, maintaining some tension. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 74, 5, 7, FALSE, TRUE, 'crunch', 'Standing Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('f662363e-5a22-4573-8c9b-2788de12e4d7', 'Seated Shoulder Stretch (Chair)', 'Shoulders', 'Chair', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Use this stretch to open up your shoulders area and enhance overall flexibility. Your upper back work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. Flexibility work like this enhances performance and prevents stiffness.', '104661201', '104661201-Seated-Shoulder-Stretch-on-a-Chair-(male)_Stretch.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Move into the stretch position for Seated Shoulder Stretch On A Chair. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 27, 2, 6, FALSE, TRUE, 'shoulder_stretch', 'Seated Shoulder Stretch On A Chair', 'stretch_chest, stretch_tricep, stretch_lat', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('f6627a26-5a7e-4242-9fc3-fe327c67ca8e', 'Power Sled Push (Sled)', 'Legs', 'Sled', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Power Sled Push is a pushing exercise that primarily loads your quadriceps. Your glutes, calves work as secondary movers, adding to the training stimulus. Leg training boosts metabolism and builds functional, real-world strength.', '25241201', '25241201-Power-Sled-Push-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Perform the concentric (lifting) phase explosively with maximum effort. 2. Set up in the starting position for Power Sled Push. 3. Execute the movement with proper form, focusing on your quads. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Power Sled Push', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f663cf93-0f57-46de-805d-b320ac3c04cc', 'Kneeling Rear Kick (Smith Machine)', 'Legs', 'Smith Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger glutes with this kicking movement focused on hip extension. Your hamstrings work as secondary movers, adding to the training stimulus. The kneeling position adds a core stability challenge. The fixed path allows you to focus purely on muscular effort. Leg training boosts metabolism and builds functional, real-world strength.', '11831201', '11831201-Smith-kneeling-rear-kick_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Kneeling Rear Kick. 2. Kneel on the floor (use a pad for comfort if needed). 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'general_exercise', 'Smith Kneeling Rear Kick', 'Kneeling Rear Kick', FALSE, 'smith_machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('f6667a07-ca9f-4961-a1dc-98cf6baa1732', 'Standing Arm Crossover Behind The Back', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Build a stronger back with this movement movement targeting your chest. You''ll also feel your front delts working to support the movement. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. A strong back improves posture, prevents injury, and balances pressing movements.', '80541201', '80541201-Standing-Arm-Crossover-Behind-The-Back-(female)_Ba.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Arm Crossover Behind The Back. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'chest_fly', 'Standing Arm Crossover Behind The Back', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f672928d-8ac3-424d-a5f5-cb642c26e103', 'Hack Squat (Dumbbell, Machine)', 'Legs', 'Hack Squat Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. You''ll also feel your glutes working to support the movement. Dumbbells allow each arm to work independently, helping correct imbalances. Leg training boosts metabolism and builds functional, real-world strength.', '75661201', '75661201-Dumbbell-Hack-Squat_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Hack Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'hack_squat', 'Hack Squat', 'leg_press, squat, leg_extension', FALSE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('f6766f5b-a790-43b8-985e-2264e68348f6', 'Chest Press - Inner (Machine)', 'Chest', 'Machine', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Machine Inner Chest Press, an effective pressing movement for upper body strength. Secondary activation of your triceps, front delts provides additional muscle engagement. Machine exercises are great for isolating muscles and training to failure safely. A well-developed chest contributes to upper body strength and aesthetics.', '13011201', '13011201-Machine-Inner-Chest-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Machine Inner Chest Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'bench_press', 'Inner Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('f67744f0-2f42-49f4-8e0d-26463cba655e', 'Step Up With Knee Drive (Step Platform)', 'Legs', 'Step Platform', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic stepping movement gets your heart rate up while developing explosive strength. You''ll also feel your glutes, hamstrings working to support the movement. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '87071201', '87071201-Step-Up-with-Knee-Drive-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Set up a box or step platform at the appropriate height. 2. Step one foot onto the elevated surface. 3. Drive through that foot to lift your body up onto the platform. 4. Step back down with control and repeat. 5. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'knee_drive', 'Step Up With Knee Drive', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f681d9c8-b2a3-4ee9-9653-22977ff6f990', 'Mountain Climber Kickout', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors","Shoulders"}'::text[], 'The Mountain Climber Kickout is an explosive exercise that combines cardiovascular training with dynamic kicking movements. Secondary activation of your hip flexors, shoulders provides additional muscle engagement. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '71511201', '71511201-Mountain-Climber-Kickout-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. From plank position, drive one knee toward your chest. 2. Quickly switch legs, bringing the other knee forward. 3. Continue alternating at a quick pace while maintaining plank form. 4. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'mountain_climber', 'Mountain Climber Kickout', 'burpee, plank, high_knees', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('f68e7482-c62e-43aa-8716-7efddcf0f842', 'Front And Back Arms Rotation', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'The Front And Back Arms Rotation is a rotation exercise that targets your front delts for shoulder development. No equipment needed—your body provides all the resistance. Strong shoulders improve overhead strength and support nearly all upper body movements.', '55691201', '55691201-Front-and-Back-Arms-Rotation-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Rotate your torso through the movement pattern for Front And Back Arms Rotation. 2. Control the rotation in both directions—avoid using momentum. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Front And Back Arms Rotation', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f696ae8c-b3fc-4150-b136-ebfe4a964d54', 'Tuck Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Tuck Crunch is a core crunching exercise that primarily targets your abs. Your hip flexors work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '8711201', '08711201-Tuck-Crunch_waist.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Complete all reps with control before resting. Exhale during the exertion phase of the movement. A solid choice for core day.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Tuck Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f6b1bdd1-40ad-4f06-8088-d17ec374ad1c', 'Cross Body Hammer Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Elevate your training with this curling exercise that develops speed, power, and coordination. You''ll also feel your shoulders, core working to support the movement. The dumbbell variation provides freedom of movement and greater range of motion. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '2981201', '02981201-Dumbbell-Cross-Body-Hammer-Curl_Forearms.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Cross Body Hammer Curl. 2. Use a hammer/neutral grip with palms facing each other throughout. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'hammer_curl', 'Cross Body Hammer Curl', 'bicep_curl, preacher_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('f6b44a6c-282d-4d61-9b1e-7910dade008d', 'Standing Bicep Curl (Band)', 'Arms', 'Resistance Band', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. Secondary activation of your forearms provides additional muscle engagement. The standing position engages your core for stability. Bands are joint-friendly and portable, perfect for any training environment. Arm strength supports grip, pulling, and pushing in compound movements.', '70671201', '70671201-Band-Standing-Biceps-Curl-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Standing Biceps Curl. 2. Stand tall with your feet firmly planted. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 87, 5, 7, FALSE, TRUE, 'bicep_curl', 'Standing Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('f6be15d7-89f2-4ff3-92bf-869c3e0e4e37', 'Preacher Curl Wrists (Preacher Bench)', 'Arms', 'Preacher Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Preacher Curl Wrists is a curling exercise that isolates your biceps. You''ll also feel your forearms working to support the movement. A versatile bodyweight movement perfect for home or gym training. Arm strength supports grip, pulling, and pushing in compound movements.', '23481201', '23481201-Preacher-Curl---Wrists-(WRONG-RIGHT)_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Keep your elbows in a fixed position throughout the movement. 2. Curl the weight up by contracting your biceps, squeezing at the top. 3. Lower with control, resisting the weight on the way down. 4. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'preacher_curl', 'Preacher Curl Wrists', 'tricep_pushdown, tricep_extension, bicep_curl, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f6c499c9-fb59-4d26-9f37-cbbafdfbc6cb', 'Jack Step', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Jack Step is an explosive exercise that combines cardiovascular training with dynamic stepping movements. You''ll also feel your quads working to support the movement. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '44381201', '44381201-Jack-Step-(male)_Plyometrics.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Jack Step. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'general_exercise', 'Jack Step', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('f6e02fc4-f179-4163-92e0-a92e9419ada9', 'Seated Knee Extension (Resistance Band, Chair)', 'Legs', 'Resistance Band, Chair', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this extension movement that develops leg drive and power. The seated position helps isolate the target muscles by removing momentum. Bands are joint-friendly and portable, perfect for any training environment. Leg training boosts metabolism and builds functional, real-world strength.', '92741201', '92741201-Resistance-Band-Sitting-Knee-Extension-on-a-Chair-.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Secure the resistance band appropriately for Resistance Band Seated Knee Extension On A Chair. 2. Position yourself with a sturdy chair for support or as part of the movement. 3. Sit with your back supported, core engaged, feet flat on the floor. 4. Extend through the target joint(s) for Resistance Band Seated Knee Extension On A Chair. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'leg_extension', 'Seated Knee Extension On A Chair', 'squat, leg_press, lunge', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('f6ecbaf3-a5a7-4d7c-a8b8-d85ee50c1d38', 'Reverse Flutter Kicks (Bench)', 'Core', 'Bodyweight, Flat Bench', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Flutter Kicks is a lower body kicking exercise that targets your abs. Secondary activation of your hip flexors provides additional muscle engagement. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '57341201', '57341201-Flutter-Kicks-(version-2)-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Set up in the starting position for Flutter Kicks. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_raise', 'Flutter Kicks', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f70d62d5-cd45-483b-9c74-0864237d049c', 'PVC Hip Hinge', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Develop your posterior chain with this movement movement that emphasizes the glutes. Strong legs are the foundation for athletic performance and functional fitness.', '46051201', '46051201-PVC-Hip-Hinge_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Set up in the starting position for PVC Hip Hinge. 2. Execute the movement with proper form, focusing on your glutes. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'glute_exercise', 'PVC Hip Hinge', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f71c0a69-6e03-4805-9b43-811bfa260efc', '45 Leg Wide Press (Sled)', 'Legs', 'Sled', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This pressing movement emphasizes your quadriceps for stronger, more powerful legs. Leg training boosts metabolism and builds functional, real-world strength.', '7401201', '07401201-Sled-45-Leg-Wide-Press_Thighs-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Use a wide grip (wider than shoulder-width) for this variation. 2. Execute the pressing motion for Sled 45 Leg Wide Press, extending through the target muscles. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'leg_exercise', 'Sled 45 Leg Wide Press', 'squat, leg_extension, leg_curl, hack_squat, lunge', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f72d0053-9bbb-426d-8420-3983b41fd156', 'Single Leg Deadlift (TRX)', 'Back', 'TRX', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. Your glutes, lower back work as secondary movers, adding to the training stimulus. The TRX allows you to adjust difficulty by changing your body angle. Lower body strength improves everything from walking to heavy compound lifts.', '11551201', '11551201-Suspender-Single-Leg-Deadlift-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Single Leg Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'deadlift', 'Suspender Single Leg Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('f730fd0f-2f62-464b-bdec-0461d17d5b50', 'Standing Curl Straight Bar - Reverse Grip (Cable)', 'Arms', 'Cables', '{"Forearms"}'::text[], '{"Biceps"}'::text[], 'The Cable Standing Reverse Grip Curl (straight Bar) is an arm curling exercise targeting your upper back. The biceps, lats assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. Cable resistance creates smooth, continuous muscle engagement. Arm strength supports grip, pulling, and pushing in compound movements.', '29541201', '29541201-Cable-Standing-Reverse-Grip-Curl-(Straight-bar)_Fo.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing Reverse Grip Curl. 2. Stand with feet about shoulder-width apart. 3. Use a reverse grip (opposite of the standard grip for this exercise). 4. Keep your elbows in a fixed position throughout the movement. 5. Curl the weight up by contracting your biceps, squeezing at the top. 6. Lower with control, resisting the weight on the way down. 7. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 74, 5, 7, FALSE, TRUE, 'bicep_curl', 'Standing Curl - Reverse Grip', 'Standing Curl - Reverse Grip', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('f7317a19-50da-4100-8d41-b3d5d15322de', 'High Row (Plate Loaded Machine)', 'Back', 'Row Machine', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. Secondary activation of your biceps, rear delts provides additional muscle engagement. Machine exercises are great for isolating muscles and training to failure safely. Back development is crucial for pulling strength and overall upper body function.', '31001201', '31001201-Lever-High-Row-(plate-loaded)-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever High Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 78, 7, 9, TRUE, FALSE, 'cable_row', 'Lever High Row', 'squat, bench_press, deadlift', TRUE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('f73876cc-dcaf-467f-9306-14a476c2f0b4', 'Seated Upright Squeeze Press (Dumbbell) - Alternating', 'Chest', 'Dumbbells, Flat Bench', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Dumbbell Seated Upright Alternate Squeeze Press, an effective pressing movement for upper body strength. The seated position helps isolate the target muscles by removing momentum. Using dumbbells requires more stabilization than barbell variations. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '39461201', '39461201-Dumbbell-Seated-Upright-Alternate-Squeeze-Press_Ch.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Upright Alternate Squeeze Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Alternate between sides/arms/legs with each repetition. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 84, 7, 8, TRUE, TRUE, 'squeeze_press', 'Seated Upright Squeeze Press - Alternating', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('f73b7504-6a1a-4d6f-8df7-882ae27bdef2', 'Bench Front Squat (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Core"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Using a barbell provides stability for progressive overload. Leg training boosts metabolism and builds functional, real-world strength. Can be modified for beginners or progressed for advanced athletes.', '241201', '00241201-Barbell-Bench-Front-Squat_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Load a barbell and set it on a bench rack at the appropriate height. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled.', 'Squat', 'Push', 'Compound', 'Bilateral', NULL, 4, NULL, 10, 10, NULL, 4, 'Standing', NULL, 'Overhand (front Rack)', 'Standard', 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'front_squat', 'Bench Front Squat', 'squat, leg_press, leg_extension, goblet_squat', TRUE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('f75132dd-8583-4539-9280-35ec8b62846c', 'Single Arm Row With Chest Supported (Dumbbell)', 'Back', 'Dumbbells, Flat Bench', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Dumbbell Single Arm Row With Chest Supported is a rowing exercise that builds thickness in your upper back. Secondary activation of your biceps, rear delts provides additional muscle engagement. Using dumbbells requires more stabilization than barbell variations. Back development is crucial for pulling strength and overall upper body function.', '96991201', '96991201-Dumbbell-Single-Arm-Row-with-Chest-Supported_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 77, 7, 9, TRUE, FALSE, 'dumbbell_row', 'Single Arm Row With Chest Supported', 'bent_over_row, lat_pulldown, bicep_curl', TRUE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('f75e1f59-4a82-455a-b36e-e8ce610a54a1', 'Lying Obliques Scissors', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Lying Obliques Scissors is a lower body movement exercise that targets your obliques. You''ll also feel your abs working to support the movement. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '58471201', '58471201-Lying-Obliques-Scissors-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Lie down in the appropriate position for Lying Obliques Scissors. 2. Set up in the starting position for Lying Obliques Scissors. 3. Execute the movement with proper form, focusing on your obliques. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'core_exercise', 'Lying Obliques Scissors', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f76f4d6c-ad20-4388-a276-b56a8de19455', 'Seated Single Arm Wrist Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Forearms"}'::text[], '{}'::text[], 'The Dumbbell One Arm Wrist Curl strengthens your forearms and grip through a curling motion. You''ll also feel your forearms working to support the movement. Using dumbbells requires more stabilization than barbell variations. Arm strength supports grip, pulling, and pushing in compound movements.', '3641201', '03641201-Dumbbell-One-arm-Wrist-Curl_Forearm.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions. Keep your shoulders relaxed and away from your ears.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'wrist_curl', 'Single Arm Wrist Curl', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('f771d48d-c5f1-4109-aa39-fd0983ed1ec6', 'Side Camel', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Hip Flexors","Abs"}'::text[], 'This stretch specifically works on your chest, promoting flexibility and reducing muscle tightness. Your hip flexors, abs work as secondary movers, adding to the training stimulus. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '87361201', '87361201-Side-Camel-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Move into the stretch position for Side Camel. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Switch sides and repeat for equal time. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Side Camel', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f77b90a7-80dd-4a0d-9883-960d92f14d85', 'Stability Ball Rollout On Knees (Stability Ball)', 'Core', 'Stability Ball', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Stability Ball Rollout On Knees is a lower body movement exercise that targets your abs. You''ll also feel your lats, shoulders working to support the movement. Using a ball requires constant core engagement to maintain balance. Lower body strength improves everything from walking to heavy compound lifts.', '70191201', '70191201-Stability-Ball-Rollout-on-Knees-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Position the stability ball as needed for Stability Ball Rollout On Knees. 2. Set up in the starting position for Stability Ball Rollout On Knees. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'ab_rollout', 'Stability Ball Rollout On Knees', 'plank, crunch, dead_bug', FALSE, 'stability_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f7821751-e255-4e5d-9da7-931506bbffbb', 'Kneeling Scapular Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger back with this pushing movement targeting your chest. You''ll also feel your triceps, front delts working to support the movement. Kneeling helps eliminate lower body momentum from the movement. No equipment needed—your body provides all the resistance. Back development is crucial for pulling strength and overall upper body function.', '97601201', '97601201-Kneeling-Scapular-Push-Up-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Complete all reps with control before resting. Keep your core engaged for stability. Perfect for targeting your chest.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Kneeling Scapular Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f78ea794-0234-4fec-b032-a60c1890d8b1', 'Narrow Squat From Deficit (Step Platform)', 'Legs', 'Step Platform', '{"Quads","Glutes"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target the front of your thighs with this rowing exercise for quad development. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '70981201', '70981201-Narrow-Squat-from-Deficit-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:35.532804+00', '1. Use a close/narrow grip (hands closer than shoulder-width). 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps with control before resting. Focus on maintaining proper breathing throughout. A solid choice for legs day.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Narrow Squat From Deficit', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f798aaf8-2c22-4953-928c-f3067c384a8e', 'Landmine Half Kneeling Shoulders Press (Landmine)', 'Shoulders', 'Landmine Attachment, Barbell', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Build stronger shoulders with this pressing movement focusing on your delts. The kneeling position adds a core stability challenge. Shoulder development enhances both performance and upper body aesthetics.', '96951201', '96951201-Landmine-Half-Kneeling-Shoulders-Press_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Get into a half-kneeling position (one knee down, opposite foot forward). 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Landmine Half Kneeling Shoulders Press', 'lateral_raise, front_raise, rear_delt_fly, upright_row', TRUE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('f79e255e-17cb-41c7-8720-3258129c064f', 'Push Up M', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Push Up M is a pushing exercise that targets your chest muscles. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '6621201', '06621201-Push-up-m_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Push Up M', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f7af8a93-1b65-4aac-b4d8-513fe34c74c8', 'Feet And Ankles Side To Side Stretch', 'Legs', 'Bodyweight', '{"Glutes","Hips"}'::text[], '{"Hamstrings"}'::text[], 'This stretching movement focuses on your gastrocnemius and soleus. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '32451201', '32451201-Feet-and-Ankles-Side-to-Side-Stretch-(female)_Calves.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Set up in the starting position for Feet And Ankles Side To Side Stretch. 2. Execute the movement with proper form, focusing on your calves. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'lat_stretch', 'Feet And Ankles Side To Side Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('f7bbd06d-c4e4-48fe-9a3a-065fe845cdd0', 'Lying Leg Abduction', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this movement movement focusing on your glute med/abductors. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '58721201', '58721201-Lying-Leg-Abduction-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie down in the appropriate position for Lying Leg Abduction. 2. Set up in the starting position for Lying Leg Abduction. 3. Execute the movement with proper form, focusing on your glute med/abductors. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_abduction', 'Lying Leg Abduction', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f7bf1c6c-5c61-428e-9426-a28c94745194', 'Arm Bar (Kettlebell)', 'Core', 'Kettlebell', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Kettlebell Arm Bar is a core movement exercise that primarily targets your abs. The kettlebell''s offset center of mass increases the stability challenge. A strong core improves posture, protects your spine, and enhances all other lifts.', '74651201', '74651201-Kettlebell-Arm-Bar-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Select an appropriately weighted kettlebell for Kettlebell Arm Bar. 2. Set up in the starting position for Kettlebell Arm Bar. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'arm_exercise', 'Arm Bar', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('f7bfabc0-ae01-4ebf-b20f-ee9bd8c483a3', 'Single Leg Stretch (Bent Knee)', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Flexibility work like this enhances performance and prevents stiffness. Works well as both a primary exercise or accessory movement.', '28721201', '28721201-Single-Leg-Stretch-(bent-knee)-(female)_Pilates.mp4', 'female', FALSE, '2025-12-03 23:26:37.429219+00', '1. Move into the stretch position for Single Leg Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Switch sides and repeat for equal time. 5. Complete all reps on one side, then switch to the other side. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 35, 2, 6, FALSE, TRUE, 'stretch_general', 'Single Leg Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('f7c92e60-108d-49cc-832a-0567cff02cd3', 'Standing Calf Raise', 'Legs', 'Bodyweight', '{"Calves"}'::text[], '{}'::text[], 'Build stronger calves with this targeted raising exercise. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '30181201', '30181201-Standing-Calf-Raise-(female)_Calves_.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Stand tall with your feet firmly planted. 2. Lower your heels below the platform to get a full stretch. 3. Rise up onto your toes as high as possible, squeezing your calves. 4. Lower with control and repeat. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'calf_raise', 'Standing Calf Raise', 'calf_raise, seated_calf_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f7cedf75-3a85-4167-b1dd-f1d9a34fce1e', 'Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. You''ll also feel your glutes, hamstrings working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '11971201', '11971201-Bodyweight-Squat-(male)_Thighs-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f7d1cc5b-c759-4c90-bff2-f2ac4a5ef867', 'Oblique Crunch Opposite Elbow To Knee', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{}'::text[], 'Build rotational power and define your waistline with the Oblique Crunch Opposite Elbow To Knee. You''ll also feel your abs working to support the movement. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '105461201', '105461201-Oblique-Crunch-Opposite-Elbow-to-Knee-(male)_Wais.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Complete all reps with control before resting. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Oblique Crunch Opposite Elbow To Knee', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f7d802be-4f13-4554-a0e1-e7cc854ef33a', 'Seated Knee Raise Hold (Chair)', 'Core', 'Chair', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Seated Knee Raise Hold On A Chair is a flexibility exercise that targets your abs, helping to release tension and improve range of motion. You''ll also feel your hip flexors working to support the movement. The seated position helps isolate the target muscles by removing momentum. Flexibility work like this enhances performance and prevents stiffness.', '77941201', '77941201-Sitting-Knee-Raise-Hold-on-a-chair-(female)_Stretc.mp4', 'female', FALSE, '2025-12-03 23:26:37.756436+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Raise the weight in the prescribed direction for Seated Knee Raise Hold On A Chair. 4. Lower with control, maintaining tension throughout. 5. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'leg_raise', 'Seated Knee Raise Hold On A Chair', 'crunch, plank, v_up', FALSE, 'bodyweight', TRUE, 3, 60, 2, 70, 88, 95, 65),
('f7dd52c8-1de9-49b5-83a6-4b76454a4080', 'Squat Side Walk', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. You''ll also feel your glutes, hamstrings working to support the movement. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '96331201', '96331201-Squat-Side-Walk-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled. This variation specifically emphasizes the quads. Variation: Squat Side Walk.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Squat Side Walk', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f7e90ad8-2ceb-45b4-9be0-57461b58b663', 'Prayer Push Hold', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'Target your chest with the Prayer Push Hold, an effective pushing movement for upper body strength. This bodyweight exercise requires no equipment and can be done anywhere. A well-developed chest contributes to upper body strength and aesthetics.', '73661201', '73661201-Prayer-Push-Hold-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Hold the position for the prescribed time, maintaining tension. 2. Set up in the starting position for Prayer Push Hold. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 30, 7, 8, TRUE, TRUE, 'boxing', 'Prayer Push Hold', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f7e98461-5510-4350-b12d-ff5710419453', 'Static Lunge (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this lunging exercise for quad development. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Using dumbbells requires more stabilization than barbell variations. Leg training boosts metabolism and builds functional, real-world strength.', '42901201', '42901201-Dumbbell-Static-Lunge_Thighs.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Static Lunge. 2. Step forward into a lunge until both knees are at about 90 degrees. 3. Push through your front/working leg to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'lunge', 'Static Lunge', 'split_squat, step_up, squat', TRUE, 'dumbbell', TRUE, 3, 90, 4, 92, 90, 92, 90),
('f7ea747d-bc23-42bb-ae08-4a40ca070ebf', 'Hang Clean Below The Knees (Barbell)', 'Full Body', 'Barbell', '{"Full Body"}'::text[], '{"Quads","Glutes","Traps"}'::text[], 'This full-body movement exercise challenges multiple muscle groups simultaneously. The quads, glutes, traps assist throughout the movement, making this a well-rounded exercise. Barbells enable bilateral loading for building raw strength. Compound movements like this develop coordination, power, and overall fitness.', '15211201', '15211201-Barbell-Hang-Clean-Below-the-Knees_Weightlifts_.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Grip a barbell with hands at the appropriate width for Barbell Hang Clean Below The Knees. 2. Explosively pull the weight upward from the starting position. 3. Pull yourself under the weight and catch it at shoulder level. 4. Stand to complete the lift, then lower with control. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 9, NULL, TRUE, NULL, 'Strength', 62, 7, 9, TRUE, FALSE, 'clean', 'Hang Clean Below The Knees', 'power_clean, clean, front_squat', FALSE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('f7fcf628-dc15-4a2c-bc27-4702c5e4112e', 'Assisted Single Arm Pull Up (Resistance Band, Gymnastic Rings)', 'Back', 'Resistance Band, Gymnastic Rings', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this pulling movement. Your biceps, upper back work as secondary movers, adding to the training stimulus. The band creates increasing tension as it stretches, challenging the lockout. Back development is crucial for pulling strength and overall upper body function.', '106611201', '106611201-Ring-Resistance-Band-Assisted-Single-Arm-Pull-up-.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Secure the resistance band appropriately for Ring Resistance Band Assisted Single Arm Pull Up. 2. Pull yourself up by driving your elbows down and back. 3. Continue until your chin clears the bar, then lower with control to a full hang. 4. Complete all reps on one side, then switch to the other side. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'pull_up', 'Ring Resistance Assisted Single Arm Pull Up', 'Ring Resistance Assisted Single Arm Pull Up', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('f8042434-1426-4a15-88ef-8bd8670296fc', 'Lateral Walk', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build leg strength with this stepping movement focusing on your full body. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '93561201', '93561201-Bodyweight-Lateral-Walk-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:28.851102+00', '1. Set up in the starting position for Bodyweight Lateral Walk. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'walking', 'Lateral Walk', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f805cfce-a70e-447c-92a5-1f0260a03bdc', 'Suitcase Deadlift (Kettlebell)', 'Back', 'Kettlebell', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'The Kettlebell Suitcase Deadlift is a lower body hip hinge exercise that targets your hamstrings/glutes. Secondary activation of your glutes, lower back provides additional muscle engagement. The kettlebell''s offset center of mass increases the stability challenge. Leg training boosts metabolism and builds functional, real-world strength.', '41331201', '41331201-Kettlebell-Suitcase-Deadlift-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Select an appropriately weighted kettlebell for Kettlebell Suitcase Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 93, 7, 8, TRUE, TRUE, 'deadlift', 'Suitcase Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('f807dcf0-c867-4bd3-bab5-a7b9ebe21799', 'Standing Biceps Curl Door Frame (Door Frame)', 'Arms', 'Door Frame', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Your forearms work as secondary movers, adding to the training stimulus. The standing position engages your core for stability. Arm strength supports grip, pulling, and pushing in compound movements.', '79861201', '79861201-Standing-Biceps-Curl-Door-Frame-(male)_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Begin in a standing position with good posture. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'bicep_curl', 'Standing Biceps Curl Door Frame', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f8316cf7-35bb-4512-b722-c8dcf84fe3c4', 'Full Squat with Overhead Press', 'Legs', 'Bodyweight', '{"Quads","Glutes"}'::text[], '{"Side Delts","Triceps"}'::text[], 'This pressing exercise works your delts for improved shoulder strength and aesthetics. The triceps assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Shoulder development enhances both performance and upper body aesthetics.', '88141201', '88141201-Bodyweight-Full-Squat-with-Overhead-Press-(VERSION.mp4', 'female', FALSE, '2025-12-03 23:26:31.347577+00', '1. Start with the weight at shoulder level. 2. Press directly overhead until your arms are fully extended. 3. Lower back to shoulder level with control. 4. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'shoulder_press', 'Full Squat With Overhead Press', 'lateral_raise, front_raise, rear_delt', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f836822b-c635-45a7-a9ff-8447136adff3', 'Shrug (Smith Machine)', 'Back', 'Smith Machine', '{Trapezius}'::text[], '{"Upper Back"}'::text[], 'The Smith Shrug is a shrugging exercise that develops back strength and muscle. The machine guides your movement path for safer, more controlled repetitions. A strong back improves posture, prevents injury, and balances pressing movements.', '7671201', '07671201-Smith-Shrug_Back.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Shrug. 2. Shrug your shoulders straight up toward your ears. 3. Hold briefly at the top, then lower with control. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'shrug', 'Smith Shrug', 'Shrug', FALSE, 'barbell', FALSE, 3, 60, 2, 80, 75, 20, 88),
('f841630b-e7a2-4249-8426-db7603e98391', 'Bicep Curl 45 Degrees (Band)', 'Arms', 'Resistance Band', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Band 45 Degrees Biceps Curl is a curling exercise that isolates your biceps. Secondary activation of your forearms provides additional muscle engagement. Bands are joint-friendly and portable, perfect for any training environment. Arm strength supports grip, pulling, and pushing in compound movements.', '70431201', '70431201-Band-45-degrees-Biceps-Curl-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Secure the resistance band appropriately for Band 45 Degrees Biceps Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'bicep_curl', '45 Degrees Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('f841d863-cb27-4642-9df7-e35435543431', 'Side Lying Heel And Knee Taps', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Side Lying Heel And Knee Taps is a lower body movement exercise that targets your full body. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '65321201', '65321201-Side-Lying-Heel-and-Knee-Taps-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Lie on your side with your body aligned. 2. Set up in the starting position for Side Lying Heel And Knee Taps. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Side Lying Heel And Knee Taps', 'crunch, bicycle_crunch, russian_twist', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f84443a5-27f1-4c3a-aadc-c63bc97e81d0', 'Circle Draw - Underhand', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This movement exercise works your delts for improved shoulder strength and aesthetics. This bodyweight exercise requires no equipment and can be done anywhere. Shoulder development enhances both performance and upper body aesthetics.', '101231201', '101231201-Underhand-Circle-Draw-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Use an underhand (supinated) grip with palms facing up/toward you. 2. Set up in the starting position for Underhand Circle Draw. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Underhand Circle Draw', 'Circle Draw - Underhand', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f870b09f-191a-4a56-8150-fe597f034bc8', 'Front Plank With Twist', 'Core', 'Bodyweight', '{"Core","Abs"}'::text[], '{}'::text[], 'Work your side abdominals with this stabilization exercise that strengthens your obliques. You''ll also feel your shoulders, lower back working to support the movement. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '4641201', '04641201-Front-Plank-with-Twist_waist.mp4', 'male', FALSE, '2025-12-03 23:26:24.577164+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout. Works well for obliques activation.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'plank', 'Front Plank With Twist', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 60, 2, 70, 88, 95, 65),
('f89089ad-4d91-4c42-ae23-e6dee82f500b', 'Seated Good Morning (Barbell)', 'Back', 'Barbell, Flat Bench', '{"Lower Back"}'::text[], '{"Hamstrings","Glutes"}'::text[], 'Strengthen the back of your thighs with this movement exercise. Your glutes, lower back work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. Barbells enable bilateral loading for building raw strength. Leg training boosts metabolism and builds functional, real-world strength.', '26021201', '26021201-Barbell-Seated-Good-Morning-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Grip a barbell with hands at the appropriate width for Barbell Seated Good Morning. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', 'Pull', 'Pull', 'Compound', 'Bilateral', NULL, 3, NULL, 7, 8, NULL, 5, 'Seated', NULL, 'Overhand', 'Standard', 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 64, 7, 8, TRUE, TRUE, 'back_extension', 'Seated Good Morning', 'romanian_deadlift, back_extension, hip_thrust', TRUE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('f89986f2-8bf8-4371-9387-56fddf1edca2', 'Donkey Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'This stretch specifically works on your abs, promoting flexibility and reducing muscle tightness. Your shoulders, lower back work as secondary movers, adding to the training stimulus. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '92831201', '92831201-Donkey-Plank-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:32.624497+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Donkey Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('f8ba0fad-3230-4a44-8d95-66abc5f273a9', 'Knee Hug Glute Stretch', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Front Delts","Lower Chest","Triceps"}'::text[], 'The Knee Hug Glute Stretch is a hip-dominant stretching exercise that targets your glutes. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '66731201', '66731201-Knee-Hug-Glute-Stretch-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:24.831811+00', '1. Set up in the starting position for Knee Hug Glute Stretch. 2. Execute the movement with proper form, focusing on your glutes. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'glute_stretch', 'Knee Hug Glute Stretch', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('f8c0fdef-44d1-4ff2-9378-dcf6551369ce', 'Decline Chest Fly (Dumbbell)', 'Chest', 'Dumbbells, Decline Bench', '{"Chest","Lower Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'This flying exercise focuses on your pectorals for improved chest strength and development. Secondary activation of your front delts provides additional muscle engagement. The decline position targets the lower portion of the muscles more intensely. Dumbbells allow each arm to work independently, helping correct imbalances. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '3021201', '03021201-Dumbbell-Decline-Fly_Chest-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Decline Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps with control before resting.', 'Fly', 'Pull', 'Compound', 'Bilateral', NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'chest_fly', 'Decline Fly', 'bench_press, incline_press, push_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('f8c78b1f-cb01-465f-9fe9-3eba1506435b', 'Lying Bent Knee Raise And Extend', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This raising exercise engages your abs for improved core stability and strength. You''ll also feel your hip flexors working to support the movement. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention. Quality repetitions are more important than quantity.', '73941201', '73941201-Lying-Bent-Knee-Raise-and-Extend-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Bent Knee Raise And Extend. 2. Raise the weight in the prescribed direction for Lying Bent Knee Raise And Extend. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Lying Bent Knee Raise And Extend', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f8e01605-9477-4fde-996a-0854767c8f17', 'Twist Up (TRX)', 'Core', 'TRX', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Suspender Twist Up targets your obliques through a twisting motion, building rotational core strength. The abs assist throughout the movement, making this a well-rounded exercise. Suspension training adds instability, increasing core activation throughout. Building core stability helps with everything from heavy deadlifts to daily activities.', '11521201', '11521201-Suspender-Twist-Up-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.623429+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Twist Up. 2. Rotate your torso through the movement pattern for Suspender Twist Up. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 40, 5, 7, FALSE, TRUE, 'russian_twist', 'Suspender Twist Up', 'squat, bench_press, deadlift', FALSE, 'trx', FALSE, 3, 60, 2, 68, 85, 85, 70),
('f8e0bf15-0658-4565-861c-2692f91daab0', 'Hip Adduction (Band)', 'Legs', 'Resistance Band', '{"Inner Thighs"}'::text[], '{}'::text[], 'Build leg strength with this movement movement focusing on your adductors. The band creates increasing tension as it stretches, challenging the lockout. Lower body strength improves everything from walking to heavy compound lifts.', '9001201', '09001201-Band-hip-adduction-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Secure the resistance band appropriately for Band Hip Adduction. 2. Set up in the starting position for Band Hip Adduction. 3. Execute the movement with proper form, focusing on your adductors. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'hip_adduction', 'Hip Adduction', 'hip_abduction, squat, lunge', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('f8f39ac6-e1e0-4182-985f-5bc8baeba9a1', 'Zercher Carry (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this movement movement that develops leg drive and power. Secondary activation of your core, glutes provides additional muscle engagement. The barbell allows you to handle heavier loads for maximum strength gains. Lower body strength improves everything from walking to heavy compound lifts.', '29151201', '29151201-Barbell-Zercher-Carry_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Grip a barbell with hands at the appropriate width for Barbell Zercher Carry. 2. Set up in the starting position for Barbell Zercher Carry. 3. Execute the movement with proper form, focusing on your quads. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'general_exercise', 'Zercher Carry', 'squat, bench_press, deadlift', FALSE, 'barbell', TRUE, 3, 90, 4, 95, 80, 65, 95),
('f9029f82-2fdf-4cfb-abfa-d4d416e2764d', 'Prone Incline Curl (Band)', 'Arms', 'Resistance Band, Incline Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Secondary activation of your forearms provides additional muscle engagement. Performing this lying down removes momentum for stricter form. The band creates increasing tension as it stretches, challenging the lockout. Dedicated arm training builds both strength and muscular definition.', '68631201', '68631201-Band-Prone-Incline-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Secure the resistance band appropriately for Band Prone Incline Curl. 2. Lie face down (prone position) for Band Prone Incline Curl. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 88, 5, 7, FALSE, TRUE, 'incline_curl', 'Prone Incline Curl', 'bicep_curl, hammer_curl, preacher_curl', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('f9084dff-3324-44e3-af11-a41cc93b56b2', 'Warm Up Shoulder Stretch (Band)', 'Shoulders', 'Resistance Band', '{"Shoulders"}'::text[], '{}'::text[], 'This stretching exercise focuses on your pectorals for improved chest strength and development. The band creates increasing tension as it stretches, challenging the lockout. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '18461201', '18461201-Band-Warm-up-Shoulder-Stretch-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Secure the resistance band appropriately for Band Warm Up Shoulder Stretch. 2. Set up in the starting position for Band Warm Up Shoulder Stretch. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, 'Pull', 'Isolation', 'Unilateral', NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, 'Neutral', 'Standard', 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 45, 2, 6, FALSE, TRUE, 'shoulder_stretch', 'Warm Up Shoulder Stretch', 'stretch_chest, stretch_tricep, stretch_lat', FALSE, 'band', TRUE, 1, 30, 2, 60, 85, 90, 50),
('f90d4b9c-b11f-4bf4-8fbe-ad34a4b04ade', 'Double Side Step Walk', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic stepping movement gets your heart rate up while developing explosive strength. Your quads work as secondary movers, adding to the training stimulus. Great for improving athletic performance, burning calories, and building conditioning. Start with lighter weight to master the movement pattern.', '96431201', '96431201-Double-Side-Step-Walk-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.577164+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Double Side Step Walk. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'walking', 'Double Side Step Walk', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f9276dae-1a43-4546-b82b-296ca0944100', 'Lying Prone W Raise', 'Shoulders', 'Bodyweight', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'The Lying Prone W Raise is a raising exercise that targets your rear delts for shoulder development. The upper back assist throughout the movement, making this a well-rounded exercise. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Shoulder development enhances both performance and upper body aesthetics.', '87181201', '87181201-Lyine-Prone-W-Raise-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Lie face down with your body in a straight line. 2. Raise the weight in the prescribed direction for Lying Prone W Raise. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'general_exercise', 'Lying Prone W Raise', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f928d6af-9a52-40b1-9223-7215b86cb9fa', 'Prone Full Can Exercise (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Target your delts with the Dumbbell Prone Full Can Exercise, an effective shoulder movement exercise. The lying position provides back support and helps isolate the target muscles. The dumbbell variation provides freedom of movement and greater range of motion. Shoulder development enhances both performance and upper body aesthetics.', '58201201', '58201201-Dumbbell-Prone-Full-Can-Exercise-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Prone Full Can Exercise. 2. Lie face down (prone position) for Dumbbell Prone Full Can Exercise. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'general_exercise', 'Prone Full Can Exercise', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('f92adeed-8409-45af-b731-221a77533c04', 'Roll Pull & Bend (stabilitity Ball)', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Roll Pull & Bend (stabilitity Ball), focusing on your core. The lats assist throughout the movement, making this a well-rounded exercise. The stability ball adds an instability challenge that activates more stabilizer muscles. A strong core improves posture, protects your spine, and enhances all other lifts.', '93281201', '93281201-Roll-Pull-and-Bend-on-Stabilitity-Ball-(female)_Wa.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Set up in the starting position for Roll Pull & Bend. 2. Execute the movement with proper form, focusing on your core. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Roll Pull & Bend', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f940b2a8-bb04-41ce-a3da-92a3b3ba004d', 'Prayer Push', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Prayer Push is a pushing exercise that targets your delts for shoulder development. This bodyweight exercise requires no equipment and can be done anywhere. Shoulder development enhances both performance and upper body aesthetics.', '76281201', '76281201-Prayer-Push-(VERSION-2)-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Set up in the starting position for Prayer Push. 2. Execute the movement with proper form, focusing on your delts. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'boxing', 'Prayer Push', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f9540133-2404-4721-9e54-fca1e1f91b7b', 'Pulsing Adduction And Abduction', 'Legs', 'Bodyweight', '{"Inner Thighs"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this movement movement focusing on your adductors. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '55741201', '55741201-Pulsing-Adduction-and-Abduction-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Set up in the starting position for Pulsing Adduction And Abduction. 2. Execute the movement with proper form, focusing on your adductors. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_adduction', 'Pulsing Adduction And Abduction', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f96ec703-c1db-473d-9b34-0fbe3b132763', 'Z Press (Kettlebell)', 'Shoulders', 'Kettlebell', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'This pressing exercise works your delts for improved shoulder strength and aesthetics. The kettlebell''s offset center of mass increases the stability challenge. Strong shoulders improve overhead strength and support nearly all upper body movements. This is a great exercise for all fitness levels with proper scaling.', '97031201', '97031201-Kettlebell-Z-Press_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Select an appropriately weighted kettlebell for Kettlebell Z Press. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'shoulder_press', 'Z Press', 'lateral_raise, front_raise, rear_delt', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('f9ab9cec-6bf6-4d2a-80f6-786385e612cd', 'Seated Incline Chest Press (Chair)', 'Chest', 'Chair', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'The Seated Incline Chest Press On A Chair is a pressing exercise that targets your chest muscles. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. A well-developed chest contributes to upper body strength and aesthetics.', '86221201', '86221201-Seated-Incline-Chest-Press-on-a-Chair-(male)_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Complete all reps with control before resting. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'incline_press', 'Seated Incline Chest Press On A Chair', 'bench_press, shoulder_press, chest_fly', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f9b33842-54e6-40bc-8bb1-4bdd5c90dd39', 'Kneeling Hip Flexor Stretch', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'This stretch specifically works on your hip flexors, promoting flexibility and reducing muscle tightness. Kneeling helps eliminate lower body momentum from the movement. Include this in your routine for better mobility and reduced muscle tension. Can be modified for beginners or progressed for advanced athletes.', '72531201', '72531201-Kneeling-Hip-Flexor-Stretch-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Move into the stretch position for Kneeling Hip Flexor Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'hip_stretch', 'Kneeling Hip Flexor Stretch', 'stretch_hamstring, stretch_glute, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('f9b99f86-3ded-4a46-b107-f378bd8cfb55', 'Roll Chest Opener Lying On Floor', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'Build a stronger chest with this movement movement that develops pressing power. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '54151201', '54151201-Roll-Chest-Opener-Lying-on-Floor-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Position yourself on the floor for Roll Chest Opener Lying On Floor. 2. Lie down in the appropriate position for Roll Chest Opener Lying On Floor. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'chest_stretch', 'Roll Chest Opener Lying On Floor', 'bench_press, chest_fly, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f9c1f468-f427-4d13-9a5c-4813740a2b66', 'Cobra Lookback', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This stretch specifically works on your abs, promoting flexibility and reducing muscle tightness. You''ll also feel your lower back working to support the movement. Flexibility work like this enhances performance and prevents stiffness.', '81581201', '81581201-Cobra-Lookback-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Move into the stretch position for Cobra Lookback. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'back_stretch', 'Cobra Lookback', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('f9c796b2-71f2-46f8-8c65-2249a7df6de3', 'Kneeling Single Arm Pulldown (Band)', 'Back', 'Resistance Band, Anchor Point', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this pulling movement. You''ll also feel your biceps, upper back working to support the movement. Kneeling helps eliminate lower body momentum from the movement. Resistance bands provide accommodating resistance that increases through the range of motion. Back development is crucial for pulling strength and overall upper body function.', '38421201', '38421201-Band-Kneeling-One-Arm-Pulldown-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Kneeling One Arm Pulldown. 2. Kneel on the floor (use a pad for comfort if needed). 3. Pull the bar/handle down toward your upper chest. 4. Drive your elbows down and back, squeezing your lats. 5. Control the weight back up without letting it yank your arms. 6. Complete all reps on one side, then switch to the other side. 7. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Kneeling Single Arm Pulldown', 'pull_up, bent_over_row, cable_row, face_pull', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('f9c82fbf-3f03-440d-be00-c897c0b9956d', 'Incline Chest Fly (Band)', 'Chest', 'Resistance Band, Incline Bench', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'The Band Incline Chest Fly is a flying exercise that targets your chest muscles. Secondary activation of your front delts provides additional muscle engagement. Using an incline changes the angle of resistance for varied muscle recruitment. The band creates increasing tension as it stretches, challenging the lockout. A well-developed chest contributes to upper body strength and aesthetics.', '57401201', '57401201-Band-Incline-Chest-Fly_Chest-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Secure the resistance band appropriately for Band Incline Chest Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 88, 5, 7, FALSE, TRUE, 'incline_press', 'Incline Chest Fly', 'bench_press, shoulder_press, chest_fly', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('f9cf0852-8c0e-4764-91e0-a3aa5faee8a7', 'Frog Crunch - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This crunching exercise engages your abs for improved core stability and strength. The hip flexors assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention. Progress gradually by increasing resistance over time.', '74961201', '74961201-Alternate-Frog-Crunch-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Alternate between sides/arms/legs with each repetition. 5. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Frog Crunch - Alternating', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('f9dc7cae-43c0-4f68-a1e2-5da142a392dc', 'Lying Single Arm Triceps Stretch', 'Arms', 'Bodyweight', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Lying Single Arm Triceps Stretch is a flexibility exercise that targets your triceps, helping to release tension and improve range of motion. You''ll also feel your shoulders working to support the movement. The lying position provides back support and helps isolate the target muscles. Include this in your routine for better mobility and reduced muscle tension.', '107391201', '107391201-Lying-Single-Arm-Triceps-Stretch-(male)_Stretchin.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Lie down in the appropriate position for Lying Single Arm Triceps Stretch. 2. Move into the stretch position for Lying Single Arm Triceps Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 5. Switch sides and repeat for equal time. 6. Complete all reps on one side, then switch to the other side.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Lying', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 35, 2, 6, FALSE, TRUE, 'stretch_general', 'Lying Single Arm Triceps Stretch', 'bicep_curl, dip', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('f9dd76ed-3cee-48b9-b897-4f1101239914', 'Seated Shoulder Waves', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Seated Shoulder Waves is a movement exercise that targets your delts for shoulder development. Being seated provides stability, allowing you to focus on the working muscles. Strong shoulders improve overhead strength and support nearly all upper body movements.', '89361201', '89361201-Seated-Shoulder-Waves-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Seated Shoulder Waves. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Seated Shoulder Waves', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f9dda57b-79c8-422e-b626-c29253c82154', 'Lying Straight Leg Lift - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lying Alternate Straight Leg Lift is a lower body movement exercise that targets your core. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '77361201', '77361201-Lying-Alternate-Straight-Leg-Lift-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie down in the appropriate position for Lying Alternate Straight Leg Lift. 2. Alternate between sides/arms/legs with each repetition. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'romanian_deadlift', 'Lying Straight Leg Lift - Alternating', 'deadlift, leg_curl, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f9e39655-c139-4613-bc81-4651241e1382', 'Curtsey Lunge (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This lunging movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Using dumbbells requires more stabilization than barbell variations. Leg training boosts metabolism and builds functional, real-world strength.', '86641201', '86641201-Dumbbell-Curtsey-Lunge-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Curtsey Lunge. 2. Step forward into a lunge until both knees are at about 90 degrees. 3. Push through your front/working leg to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'lunge', 'Curtsey Lunge', 'split_squat, step_up, squat', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('f9e42476-5c27-4f4e-ad00-d8f6ea6540db', 'Push Up (Against Wall)', 'Chest', 'Wall', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Push Up (wall), an effective pushing movement for upper body strength. Secondary activation of your triceps, front delts provides additional muscle engagement. A well-developed chest contributes to upper body strength and aesthetics.', '6591201', '06591201-Push-up-(wall)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Position yourself at the appropriate distance from a wall. 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Complete all reps with control before resting. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'push_up', 'Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f9eee08a-9b21-439d-a5f3-db66d1672073', 'Side Lying 90 Degrees Hip Clam And Kick', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Side Lying 90 Degrees Hip Clam And Kick is a lower body kicking exercise that targets your core. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '63131201', '63131201-Side-Lying-90-Degrees-Hip-Clam-and-Kick-(female)_H.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Lie on your side with your body aligned. 2. Set up in the starting position for Side Lying 90 Degrees Hip Clam And Kick. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_abduction', 'Side Lying 90 Degrees Hip Clam And Kick', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('f9f14f97-6018-4cdd-ae4f-52ea0dec4c81', 'Rounded Back Extension', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this extension movement focusing on your lower back. You''ll also feel your glutes working to support the movement. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '54711201', '54711201-Rounded-Back-Extension_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Raise your torso by extending at the lower back/hips. 2. Lower with control, maintaining tension. 3. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'back_extension', 'Rounded Back Extension', 'good_morning, bird_dog, superman', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('fa053d0e-df55-4d0c-818b-da7c5fd24a70', 'Single Leg Deadlift (Smith Machine)', 'Back', 'Smith Machine', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'The Smith Single Leg Deadlift is a lower body hip hinge exercise that targets your hamstrings/glutes. You''ll also feel your glutes, lower back working to support the movement. The machine guides your movement path for safer, more controlled repetitions. Lower body strength improves everything from walking to heavy compound lifts.', '66051201', '66051201-Smith-Single-Leg-Deadlift_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Single Leg Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, FALSE, NULL, 'Strength', 88, 7, 9, TRUE, FALSE, 'deadlift', 'Smith Single Leg Deadlift', 'Single Leg Deadlift', FALSE, 'smith_machine', FALSE, 4, 120, 6, 80, 75, 20, 88),
('fa0fe6d2-516d-46af-ba46-d6393a01da7d', 'Side Walk Squat (Resistance Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Resistance bands provide accommodating resistance that increases through the range of motion. Leg training boosts metabolism and builds functional, real-world strength. Excellent for pre-exhausting the target muscle before compound lifts.', '67441201', '67441201-Resistance-Band-Side-Walk-Squat-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Side Walk Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 90, 7, 8, TRUE, TRUE, 'squat', 'Side Walk Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('fa1b82da-abf8-4fb4-941c-8c7ec056a09c', 'Pendulum Leg Plus', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'A challenging plyometric exercise, the Pendulum Leg Plus builds reactive power and improves conditioning. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '57911201', '57911201-Pendulum-Leg-Plus-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Set up in the starting position for Pendulum Leg Plus. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Pendulum Leg Plus', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fa28b753-d5ac-4dfe-9954-e770168eb041', '3/4 Sit Up', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The 3/4 Sit Up is a core movement exercise that primarily targets your abs. Secondary activation of your hip flexors provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '11201', '00011201-3-4-Sit-up_Waist-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Set up in the starting position for 3 4 Sit Up. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum.', 'Trunk Flexion', 'Pull', 'Compound', 'Bilateral', NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', '3/4 Sit Up', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('fa35ced1-2a1f-4aee-b6be-4c13f7dbf7f8', 'Standing Single Arm Curl Over Incline Benc (Kettlebell)', 'Arms', 'Kettlebell, Incline Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Kettlebell Standing One Arm Curl Over Incline Benc is a curling exercise that isolates your biceps. Secondary activation of your forearms provides additional muscle engagement. Performing this standing challenges your balance and core engagement. Kettlebells are excellent for building functional, real-world strength. Dedicated arm training builds both strength and muscular definition.', '68371201', '68371201-Kettlebell-Standing-One-Arm-Curl-Over-Incline-Benc.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Select an appropriately weighted kettlebell for Kettlebell Standing One Arm Curl Over Incline Benc. 2. Stand with feet about shoulder-width apart. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps on one side, then switch to the other side. 7. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 4, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 68, 5, 7, FALSE, TRUE, 'bicep_curl', 'Standing Single Arm Curl Over Incline Benc', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78),
('fa37e005-fe06-4343-8e2b-755aab1b1439', 'Standing Single Arm Lateral Raise (Resistance Band)', 'Shoulders', 'Resistance Band', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'The Resistance Band Standing Single Arm Lateral Raise is a raising exercise that targets your lateral delts for shoulder development. The standing position engages your core for stability. Resistance bands provide accommodating resistance that increases through the range of motion. Strong shoulders improve overhead strength and support nearly all upper body movements.', '83621201', '83621201-Resistance-Band-Standing-Single-Arm-Lateral-Raise-.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Secure the resistance band appropriately for Resistance Band Standing Single Arm Lateral Raise. 2. Stand with feet about shoulder-width apart. 3. Raise your arms out to the sides until parallel to the floor. 4. Lower with control, maintaining tension throughout. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'lateral_raise', 'Standing Single Arm Lateral Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('fa3ad32c-a79a-4659-ad39-372fce9a865c', 'Clamshell Sit (Against Wall)', 'Legs', 'Wall', '{"Glutes"}'::text[], '{"Hip Abductors"}'::text[], 'The Clamshell Sit Against Wall is a lower body movement exercise that targets your glute med/abductors. Your hip abductors work as secondary movers, adding to the training stimulus. Strong legs are the foundation for athletic performance and functional fitness.', '87691201', '87691201-Clamshell-Sit-agains-Wall-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Position yourself at the appropriate distance from a wall. 2. Set up in the starting position for Clamshell Sit Against Wall. 3. Execute the movement with proper form, focusing on your glute med/abductors. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'hip_abduction', 'Clamshell Sit Against Wall', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fa3d61d5-e792-4f85-8ba5-6fe82f9fa7ed', 'Incline Fly On Stability Ball (Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Cable Incline Fly (on Stability Ball) is a flying exercise that targets your chest muscles. Your front delts work as secondary movers, adding to the training stimulus. The incline angle shifts emphasis toward the upper portion of the target muscles. The cable setup allows you to adjust the angle of resistance. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '1701201', '01701201-Cable-Incline-Fly-(on-stability-ball)_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Adjust the cable machine to the correct height and attachment for Cable Incline Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps with control before resting. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 67, 5, 7, FALSE, TRUE, 'chest_fly', 'Incline Fly', 'bench_press, incline_press, push_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('fa61ae1c-915b-433c-a419-9171f34ff245', 'Good Morning (Barbell)', 'Back', 'Barbell', '{"Lower Back"}'::text[], '{"Hamstrings","Glutes"}'::text[], 'Strengthen the back of your thighs with this movement exercise. Your glutes, lower back work as secondary movers, adding to the training stimulus. The barbell allows you to handle heavier loads for maximum strength gains. Strong legs are the foundation for athletic performance and functional fitness.', '22151201', '22151201-Barbell-Good-Morning-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Grip a barbell with hands at the appropriate width for Barbell Good Morning. 2. Set up in the starting position for Barbell Good Morning. 3. Execute the movement with proper form, focusing on your hamstrings. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set. A solid choice for legs day.', 'Hip Hinge', 'Pull', 'Compound', 'Bilateral', NULL, 3, NULL, 7, 8, NULL, 5, 'Standing', NULL, 'Overhand (Pronated), On Bar', 'Standard', 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'back_extension', 'Good Morning', 'romanian_deadlift, back_extension, hip_thrust', TRUE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('fa6fdd4e-2ce2-41bf-8a28-9b832adcc180', 'Standing Hip Frontal Rotation Wipe Arms', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'The Standing Hip Frontal Rotation Wipe Arms is an explosive exercise that combines cardiovascular training with dynamic rotation movements. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '88361201', '88361201-Standing-Hip-Frontal-Rotation-Wipe-Arms-(female)_P.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Begin in a standing position with good posture. 2. Rotate your torso through the movement pattern for Standing Hip Frontal Rotation Wipe Arms. 3. Control the rotation in both directions—avoid using momentum. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'glute_exercise', 'Standing Hip Frontal Rotation Wipe Arms', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fa74bcb5-9f18-4cf3-a7ac-00ad2a298db8', 'Bent Over Rear Lateral Raise (Band)', 'Shoulders', 'Resistance Band', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'The Band Bent Over Rear Lateral Raise (version is a raising exercise that targets your lateral delts for shoulder development. Bending over allows gravity to provide resistance in a different plane. Bands are joint-friendly and portable, perfect for any training environment. Strong shoulders improve overhead strength and support nearly all upper body movements.', '64861201', '64861201-Band-Bent-over-Rear-Lateral-Raise-(male)-(VERSION-.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Secure the resistance band appropriately for Band Bent Over Rear Lateral Raise (version. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Raise your arms out to the sides until parallel to the floor. 4. Lower with control, maintaining tension throughout. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'lateral_raise', 'Bent Over Rear Lateral Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('fa74d694-61d2-4c13-91f9-735bf0c4085d', 'Shoulder Tap', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities. A staple exercise that belongs in most training programs.', '46601201', '46601201-Shoulder-Tap-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Set up in the starting position for Shoulder Tap. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Shoulder Tap', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fa7db74b-e202-4218-817e-ccca03f6639b', 'Superman Row', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Upper Back"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. Your glutes work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. A strong back improves posture, prevents injury, and balances pressing movements.', '49391201', '49391201-Superman-Row-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'back_extension', 'Superman Row', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fa8d0c69-4f50-458a-8f49-90c87bd63b5b', 'Elevated Heel Front Squat (Step Platform)', 'Legs', 'Step Platform', '{"Quads"}'::text[], '{"Glutes","Core"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Secondary activation of your glutes, hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts. Start with lighter weight to master the movement pattern.', '96911201', '96911201-Bodyweight-Elevated-Heel-Front-Squat_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:22.644637+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Focus on the mind-muscle connection.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'front_squat', 'Elevated Heel Front Squat', 'squat, leg_press, leg_extension, goblet_squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fa91faa4-16f8-48f3-a284-b9ba6e9a3ff4', 'Seated Serratus Push (Resistance Band, Chair)', 'Full Body', 'Resistance Band, Chair', '{"Chest"}'::text[], '{"Shoulders"}'::text[], 'The Resistance Band Seated Serratus Push On A Chair is a compound pushing exercise that engages your entire body. You''ll also feel your shoulders working to support the movement. The seated position helps isolate the target muscles by removing momentum. Bands are joint-friendly and portable, perfect for any training environment. Compound movements like this develop coordination, power, and overall fitness.', '92041201', '92041201-Resistance-Band-Sitting-Serratus-Push-on-a-Chair-(.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Secure the resistance band appropriately for Resistance Band Seated Serratus Push On A Chair. 2. Position yourself with a sturdy chair for support or as part of the movement. 3. Sit with your back supported, core engaged, feet flat on the floor. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'serratus', 'Seated Serratus Push On A Chair', 'squat, bench_press, deadlift', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('fa957647-7643-4531-8646-996bd01ba483', 'Seated Wrist Curl - Neutral Grip (Plate)', 'Arms', 'Weight Plate', '{"Forearms"}'::text[], '{}'::text[], 'The Weighted Plate Seated Neutral Grip Wrist Curl strengthens your forearms and grip through a curling motion. Your forearms work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. Arm strength supports grip, pulling, and pushing in compound movements.', '104591201', '104591201-Weighted-Plate-Seated-Neutral-grip-Wrist-Curl-(ma.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Use a neutral grip with palms facing each other. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'wrist_curl', 'Weighted Plate Seated Wrist Curl - Neutral Grip', 'Weighted Plate Seated Wrist Curl - Neutral Grip', FALSE, 'plate', FALSE, 3, 60, 2, 70, 88, 95, 65),
('fa9b8233-dfa0-48ac-b66f-d616b7e7f9c3', 'Decline Push Up (Flat Bench)', 'Chest', 'Flat Bench, Bodyweight', '{"Chest","Lower Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'Target your chest with the Decline Push Up, an effective pushing movement for upper body strength. You''ll also feel your triceps, front delts working to support the movement. Declining shifts the emphasis to hit the muscles from a different angle. A well-developed chest contributes to upper body strength and aesthetics.', '2801201', '02801201-Decline-Push-up-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled. This exercise is excellent for chest development.', 'Push Up', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 73, 7, 8, TRUE, TRUE, 'push_up', 'Decline Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fa9e930e-2395-41b2-a1ea-02cb97de4271', 'Seated Chest Fly (Chair)', 'Chest', 'Chair', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Target your chest with the Seated Chest Fly On A Chair, an effective flying movement for upper body strength. The front delts assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '91091201', '91091201-Sitting-Chest-Fly-on-a-Chair-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. With a slight bend in your elbows, move the weight in a wide arc. 4. Squeeze your chest muscles at the center/top of the movement. 5. Return with control, feeling the stretch at the bottom. 6. Complete all reps with control before resting. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'chest_fly', 'Seated Chest Fly On A Chair', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('fa9fcc96-347e-4360-9022-f71a0e3e22f9', 'Standing Knee To Chest Stretch', 'Chest', 'Bodyweight', '{"Glutes","Hips"}'::text[], '{"Front Delts"}'::text[], 'The Standing Knee To Chest Stretch provides a deep stretch for your chest, ideal for recovery and mobility work. Your shoulders work as secondary movers, adding to the training stimulus. The standing position engages your core for stability. Include this in your routine for better mobility and reduced muscle tension.', '80621201', '80621201-Standing-Knee-to-Chest-Stretch-(female)_Stretching.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Begin in a standing position with good posture. 2. Move into the stretch position for Standing Knee To Chest Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'chest_stretch', 'Standing Knee To Chest Stretch', 'stretch_shoulder, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('faa4b23f-800a-4968-9808-15c2aabd3b54', 'Lying Split Abductor', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this movement movement focusing on your glute med/abductors. Your glutes work as secondary movers, adding to the training stimulus. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '62801201', '62801201-Lying-Split-Abductor-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying Split Abductor. 2. Set up in the starting position for Lying Split Abductor. 3. Execute the movement with proper form, focusing on your glute med/abductors. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_abduction', 'Lying Split Abductor', 'hip_adduction, glute_bridge, clamshell', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('faaf8bf5-3065-4128-8b32-b67e1fc41e6f', '45 Degrees Reverse Hyperextension (Hyperextension Bench)', 'Back', 'Hyperextension Bench', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This extension exercise isolates your glutes for improved hip strength and power. Your hamstrings, lower back work as secondary movers, adding to the training stimulus. Leg training boosts metabolism and builds functional, real-world strength.', '58021201', '58021201-45-degrees-Reverse-Hyperextension_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Raise your torso by extending at the lower back/hips. 2. Lower with control, maintaining tension. 3. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'back_extension', '45 Degrees Reverse Hyperextension', 'good_morning, bird_dog, superman', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('fab1998c-d64a-4202-841c-5b9d42d3580c', 'Side Place Leg - Alternating', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this movement movement focusing on your hip abductors. Secondary activation of your glutes provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '73951201', '73951201-Alternate-Side-Place-Leg-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Alternate between sides/arms/legs with each repetition. 2. Set up in the starting position for Alternate Side Place Leg. 3. Execute the movement with proper form, focusing on your hip abductors. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Side Place Leg - Alternating', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fab20312-5ebd-454e-af04-701b942ee641', 'Cobra Side Ab Stretch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This stretching exercise engages your abs for improved core stability and strength. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities. Progress gradually by increasing resistance over time. Consistency with this movement will yield noticeable results.', '52121201', '52121201-Cobra-Side-Ab-Stretch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Set up in the starting position for Cobra Side Ab Stretch. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Cobra Side Ab Stretch', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('fabd721b-fd44-41ae-9ea4-eca70070a90a', 'Lying Femoral (Dumbbell)', 'Core', 'Dumbbells, Flat Bench', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Dumbbell Lying Femoral is a lower body movement exercise that targets your core. The lying position provides back support and helps isolate the target muscles. Using dumbbells requires more stabilization than barbell variations. Leg training boosts metabolism and builds functional, real-world strength.', '26691201', '26691201-Dumbbell-Lying-Femoral-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lying Femoral. 2. Lie down in the appropriate position for Dumbbell Lying Femoral. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Femoral', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('fad6ee2a-69c1-4fd0-9cf6-db9d473e45b6', 'Gripless Shrug (Machine)', 'Back', 'Shrug Machine', '{"Traps"}'::text[], '{"Upper Back"}'::text[], 'The Lever Gripless Shrug is a shrugging exercise that develops back strength and muscle. Machine exercises are great for isolating muscles and training to failure safely. A strong back improves posture, prevents injury, and balances pressing movements.', '5801201', '05801201-Lever-Gripless-Shrug_Back.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Gripless Shrug. 2. Shrug your shoulders straight up toward your ears. 3. Hold briefly at the top, then lower with control. 4. Complete all reps with control before resting. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'shrug', 'Lever Gripless Shrug', 'deadlift, bent_over_row, face_pull', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('fadb5417-18fe-4150-a01a-62d89d6b4051', 'Side Plank (Wall Supported)', 'Core', 'Wall', '{"Core","Abs"}'::text[], '{"Shoulders"}'::text[], 'Strengthen your midsection with this stabilization movement that works your abs. Secondary activation of your shoulders, lower back provides additional muscle engagement. Core strength is foundational for athletic performance and injury prevention. Progress gradually by increasing resistance over time.', '65971201', '65971201-Side-Plank-Supported-Wall-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Position yourself at the appropriate distance from a wall. 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Complete all reps with control before resting. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'side_plank', 'Side Plank Supported Wall', 'plank, russian_twist, woodchop', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('fae1f836-9d03-47e9-9ab7-14987ec578e5', 'Sumo Chair Squat (Smith Machine)', 'Legs', 'Smith Machine, Chair', '{Quadriceps}'::text[], '{"Glutes","Inner Thighs","Hamstrings"}'::text[], 'The Smith Sumo Chair Squat is a squatting exercise that primarily loads your quadriceps. You''ll also feel your glutes, hamstrings working to support the movement. The fixed path allows you to focus purely on muscular effort. Strong legs are the foundation for athletic performance and functional fitness.', '67961201', '67961201-Smith-Sumo-Chair-Squat-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Sumo Chair Squat. 2. Position yourself with a sturdy chair for support or as part of the movement. 3. Push your hips back and bend your knees to lower your body. 4. Keep your chest up and knees tracking over your toes. 5. Drive through your heels to stand back up, squeezing your glutes at the top. 6. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 78, 7, 9, TRUE, FALSE, 'squat', 'Smith Sumo Chair Squat', 'Sumo Chair Squat', FALSE, 'smith_machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('fae752fb-7923-48b6-b020-3438021fcb72', 'Decline Pullover (Barbell)', 'Chest', 'Barbell, Decline Bench', '{"Chest","Lower Chest"}'::text[], '{"Lats","Triceps"}'::text[], 'Build a stronger chest with this pulling movement that develops pressing power. You''ll also feel your lats, triceps working to support the movement. Declining shifts the emphasis to hit the muscles from a different angle. Barbells enable bilateral loading for building raw strength. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '70101201', '70101201-Barbell-Decline-Pullover-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Grip a barbell with hands at the appropriate width for Barbell Decline Pullover. 2. With arms slightly bent, lower the weight behind your head in an arc. 3. Pull the weight back over your chest, squeezing your lats and chest. 4. Repeat for the prescribed number of repetitions.', 'Pullover', 'Pull', 'Compound', 'Bilateral', NULL, 3, NULL, 7, 8, NULL, 5, 'Lying (Decline)', NULL, 'Overhand (Pronated)', 'Standard', 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'pullover', 'Decline Pullover', 'bicep_curl, face_pull, lat_pulldown', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('faf66884-885c-4861-9e60-a1deb167c44c', 'Standing Wheel Rollout (Ab Wheel)', 'Core', 'Ab Wheel', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Standing Wheel Rollout is a core movement exercise that primarily targets your abs. You''ll also feel your lats, shoulders working to support the movement. Performing this standing challenges your balance and core engagement. Building core stability helps with everything from heavy deadlifts to daily activities.', '43241201', '43241201-Standing-Wheel-Rollout-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:38.992671+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Wheel Rollout. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'ab_rollout', 'Standing Wheel Rollout', 'plank, crunch, dead_bug', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fb05fff5-b038-4aa8-906e-5fbe5032584b', 'Burpee Twist', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Chest","Quads","Core"}'::text[], 'This dynamic twisting movement gets your heart rate up while developing explosive strength. The chest, quads assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '59681201', '59681201-Burpee-Twist-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Rotate your torso through the movement pattern for Burpee Twist. 2. Control the rotation in both directions—avoid using momentum. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'burpee', 'Burpee Twist', 'mountain_climber, box_jump, jumping_jack', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('fb11fe2c-a743-4649-8297-30e94043efe5', 'Side Step Fly', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity flying exercise that challenges your entire body. You''ll also feel your quads working to support the movement. Plyometric training builds explosive power that transfers to sports and daily activities.', '56011201', '56011201-Side-Step-Fly-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.303932+00', '1. Set up a box or step platform at the appropriate height. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection. Perfect for targeting your full body.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'chest_fly', 'Side Step Fly', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('fb135b3e-1b50-46f5-91d7-adac3f38cf69', 'Kneeling Glute Press', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Kneeling Glute Press is a hip-dominant pressing exercise that targets your glutes. Kneeling helps eliminate lower body momentum from the movement. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '67471201', '67471201-Kneeling-Glute-Press-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Execute the pressing motion for Kneeling Glute Press, extending through the target muscles. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'glute_exercise', 'Kneeling Glute Press', 'hip_thrust, glute_bridge, leg_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fb18162b-7429-491f-a475-4573dd0af815', 'Kneeling Rotation Torso Row To Thread Th - Alternating', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. Secondary activation of your biceps, rear delts provides additional muscle engagement. The kneeling position adds a core stability challenge. This bodyweight exercise requires no equipment and can be done anywhere. A strong back improves posture, prevents injury, and balances pressing movements.', '77651201', '77651201-Kneeling-Rotation-Torso-Alternate-Row-to-Thread-Th.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Alternate between sides/arms/legs with each repetition. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'general_exercise', 'Kneeling Rotation Torso Row To Thread Th - Alternating', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fb18c5d5-90c4-4f67-a4a4-1bad59222da1', 'Single Leg Hip Thrust Jump', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'This dynamic jumping movement gets your heart rate up while developing explosive strength. Secondary activation of your hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '47931201', '47931201-Single-Leg-Hip-Thrust-Jump_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Complete all reps on one side, then switch to the other side. 5. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 65, 9, 8, TRUE, TRUE, 'hip_thrust', 'Single Leg Hip Thrust Jump', 'glute_bridge, romanian_deadlift, leg_curl', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('fb24c41d-8782-4853-b9af-949138df2d2d', 'Seated Criss Cross Legs (Chair)', 'Full Body', 'Chair', '{"Full Body"}'::text[], '{"Shoulders","Core"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. The shoulders, core assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. Plyometric training builds explosive power that transfers to sports and daily activities.', '83121201', '83121201-Seated-Criss-Cross-Legs-on-a-Chair-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'boxing', 'Seated Criss Cross Legs On A Chair', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fb302ea2-ef57-4e31-b692-02df31e8f1b5', 'Incline Curl (Kettlebell) - Alternating', 'Arms', 'Kettlebell, Incline Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Kettlebell Incline Alternate Curl is a curling exercise that isolates your biceps. You''ll also feel your forearms working to support the movement. The incline angle shifts emphasis toward the upper portion of the target muscles. The kettlebell grip position adds a unique training stimulus. Arm strength supports grip, pulling, and pushing in compound movements.', '68191201', '68191201-Kettlebell-Incline-Alternate-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:28.851102+00', '1. Select an appropriately weighted kettlebell for Kettlebell Incline Alternate Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 81, 5, 7, FALSE, TRUE, 'bicep_curl', 'Incline Curl - Alternating', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78),
('fb3422c6-ef17-4a7c-bbfe-fc48456999a7', 'Assisted Parallel Pull Up - Close Grip (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this pulling movement. Secondary activation of your biceps, upper back provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. A strong back improves posture, prevents injury, and balances pressing movements.', '151201', '00151201-Assisted-Parallel-Close-Grip-Pull-up_Back-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Use a close/narrow grip (hands closer than shoulder-width). 2. Pull yourself up by driving your elbows down and back. 3. Continue until your chin clears the bar, then lower with control to a full hang. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Assisted Parallel Pull Up - Close Grip', 'Assisted Parallel Pull Up - Close Grip', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fb350d7a-5235-48b6-ae68-e856ff729887', 'Superman - Alternating', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Upper Back"}'::text[], 'Build leg strength with this movement movement focusing on your lower back. You''ll also feel your glutes working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '47021201', '47021201-Alternating-Superman_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Alternate between sides/arms/legs with each repetition. 2. Set up in the starting position for Alternating Superman. 3. Execute the movement with proper form, focusing on your lower back. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_extension', 'Superman - Alternating', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fb40a2b2-571c-4ed0-8f18-5450f7636b63', 'Squat (Smith Machine)', 'Legs', 'Smith Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Smith Squat is a squatting exercise that primarily loads your quadriceps. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Machine exercises are great for isolating muscles and training to failure safely. Leg training boosts metabolism and builds functional, real-world strength.', '7701201', '07701201-Smith-Squat_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'squat', 'Smith Squat', 'Squat', FALSE, 'smith_machine', FALSE, 4, 120, 5, 80, 75, 20, 88);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('fb456d00-7910-4d6f-97fc-ac2894547923', 'Single Arm Bent Over Row (Cable)', 'Back', 'Cables', '{"Back","Lats"}'::text[], '{"Biceps","Rear Delts"}'::text[], 'The Cable One Arm Bent Over Row is a rowing exercise that builds thickness in your upper back. You''ll also feel your biceps, lats working to support the movement. Bending over allows gravity to provide resistance in a different plane. The cable setup allows you to adjust the angle of resistance. A strong back improves posture, prevents injury, and balances pressing movements.', '1891201', '01891201-Cable-One-Arm-Bent-over-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Adjust the cable machine to the correct height and attachment for Cable One Arm Bent Over Row. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps on one side, then switch to the other side. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'bent_over_row', 'Single Arm Bent Over Row', 'cable_row, dumbbell_row, t_bar_row, lat_pulldown', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('fb63724c-bff1-4817-82f0-ec9fc95ebade', 'Spread Leg Forward Fold Upavista Konasana', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target your hamstrings with this movement stretch that helps restore range of motion. The lower back, calves assist throughout the movement, making this a well-rounded exercise. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '9581201', '09581201-Spread-Leg-Forward-Fold-Upavista-Konasana-(female).mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Move into the stretch position for Spread Leg Forward Fold Upavista Konasana. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'hamstring_stretch', 'Spread Leg Forward Fold Upavista Konasana', 'squat, lunge, leg_press', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('fb6a1898-2481-4733-b594-765a02eb5fe0', 'Concentration Curl (Cable)', 'Arms', 'Cables', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Cable Concentration Curl is a curling exercise that isolates your biceps. Secondary activation of your forearms provides additional muscle engagement. Cable resistance creates smooth, continuous muscle engagement. Arm strength supports grip, pulling, and pushing in compound movements.', '16311201', '16311201-Cable-Concentration-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:25.233728+00', '1. Adjust the cable machine to the correct height and attachment for Cable Concentration Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'concentration_curl', 'Concentration Curl', 'tricep_pushdown, tricep_extension, bicep_curl, hammer_curl', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('fb6a1abd-8f90-4410-b161-9829c41e6110', 'Top Bottom Punch Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'A challenging plyometric exercise, the Top Bottom Punch Squat builds reactive power and improves conditioning. Secondary activation of your glutes, hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '57951201', '57951201-Top-Bottom-Punch-Squat-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:25.233728+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Focus on maintaining proper breathing throughout.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Top Bottom Punch Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fb6a9884-4a3b-4dd0-a8fe-0e56cade0006', 'Seated Triceps Extension (Dumbbell)', 'Arms', 'Dumbbells, Flat Bench', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Dumbbell Seated Triceps Extension targets your triceps through a extension motion. Being seated provides stability, allowing you to focus on the working muscles. The dumbbell variation provides freedom of movement and greater range of motion. Dedicated arm training builds both strength and muscular definition.', '78921201', '78921201-Dumbbell-Seated-Triceps-Extension-(VERSION-2)_Uppe.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Triceps Extension. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Extend at the elbow until your arm is straight, squeezing the tricep. 4. Lower with control, keeping your upper arm stationary. 5. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'tricep_extension', 'Seated Triceps Extension', 'tricep_pushdown, close_grip_bench', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('fb6fc3dd-bd9d-470a-b8d5-77a50a3a159a', 'Bicep Curl (Band) - Alternating', 'Arms', 'Resistance Band', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Band Alternating Biceps Curl is a curling exercise that isolates your biceps. You''ll also feel your forearms working to support the movement. The band creates increasing tension as it stretches, challenging the lockout. Dedicated arm training builds both strength and muscular definition.', '9681201', '09681201-Band-Alternating-Biceps-Curl_Upper-Arms-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Secure the resistance band appropriately for Band Alternating Biceps Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'bicep_curl', 'Biceps Curl - Alternating', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('fb7f3e18-a67b-4aef-aa28-3b355291a677', 'Reverse Lunge (Wall Supported)', 'Legs', 'Wall', '{"Glutes"}'::text[], '{"Quads","Hamstrings"}'::text[], 'Build stronger quads with this lunging movement that develops leg drive and power. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Strong legs are the foundation for athletic performance and functional fitness.', '93571201', '93571201-Wall-Supported-Reverse-Lunge-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Position yourself at the appropriate distance from a wall. 2. Step backward, lowering your back knee toward the floor. 3. Push through your front/working leg to return to the starting position. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'lunge', 'Wall Supported Reverse Lunge', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fb907cf8-830b-4d5e-926e-1dc4a314e44d', 'Side Plank Row (Dumbbell)', 'Back', 'Dumbbells', '{"Core","Abs"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Strengthen your midsection with this rowing movement that works your abs. Secondary activation of your shoulders, lower back provides additional muscle engagement. The dumbbell variation provides freedom of movement and greater range of motion. Core strength is foundational for athletic performance and injury prevention.', '74711201', '74711201-Dumbbell-Side-Plank-Row-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Side Plank Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'side_plank', 'Side Plank Row', 'plank, russian_twist, woodchop', TRUE, 'dumbbell', TRUE, 4, 120, 4, 92, 90, 92, 90),
('fb97961d-9547-4595-b4fa-761ef5eaadb1', 'Sumo Deadlift With High Pull (Kettlebell)', 'Legs', 'Kettlebell', '{"Glutes"}'::text[], '{"Quads","Lower Back","Inner Thighs"}'::text[], 'The Kettlebell Sumo Deadlift With High Pull is a lower body pulling exercise that targets your hamstrings/glutes. Your glutes, lower back work as secondary movers, adding to the training stimulus. The kettlebell''s offset center of mass increases the stability challenge. Leg training boosts metabolism and builds functional, real-world strength.', '41321201', '41321201-Kettlebell-Sumo-Deadlift-with-High-Pull-(male)_Hip.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. Select an appropriately weighted kettlebell for Kettlebell Sumo Deadlift With High Pull. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 93, 7, 8, TRUE, TRUE, 'upright_row', 'Sumo Deadlift With High Pull', 'deadlift, squat, hip_thrust', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('fb998406-85f7-48bb-8fc5-a2b4ac1e2101', 'Lying Knee Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Lying Knee Raise, focusing on your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '81941201', '81941201-Lying-Knee-Raise-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Lie down in the appropriate position for Lying Knee Raise. 2. Raise the weight in the prescribed direction for Lying Knee Raise. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Lying Knee Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('fba39fde-9e7e-487e-990e-fc52438b81c6', 'Lying 90 Degrees Leg Tap Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lying 90 Degrees Leg Tap Crunch is a core crunching exercise that primarily targets your abs. You''ll also feel your hip flexors working to support the movement. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '66381201', '66381201-Lying-90-Degrees-Leg-Tap-Crunch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie down in the appropriate position for Lying 90 Degrees Leg Tap Crunch. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Lying 90 Degrees Leg Tap Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('fba5f65e-8551-45a1-a6d9-ac5d102fb3ac', 'Seated Arm Crossover (Chair)', 'Full Body', 'Chair', '{"Full Body"}'::text[], '{"Shoulders","Core"}'::text[], 'A challenging plyometric exercise, the Seated Arm Crossover On A Chair builds reactive power and improves conditioning. The shoulders, core assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '86191201', '86191201-Seated-Arm-Crossover-on-a-Chair-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'chest_fly', 'Seated Arm Crossover On A Chair', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fba91536-8762-464d-aef3-af2a9dd166f2', 'Walk (high Knees)', 'Legs', 'Bodyweight', '{"Hip Flexors"}'::text[], '{"Quads","Calves"}'::text[], 'This cardio exercise keeps your heart rate elevated for improved cardiovascular fitness. You''ll also feel your hip flexors working to support the movement. Cardiovascular exercise improves heart health, endurance, and helps manage weight.', '8291201', '08291201-Walk-(high-knees)-(female)_Cardio_.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Set up in the starting position for Walk. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'high_knees', 'Walk', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('fbb2d02c-5bec-46ba-b549-364fd9f0d267', '90 To 90 Press Stretch', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Designed to lengthen your hips, the 90 To 90 Press Stretch helps improve mobility and prevent stiffness. You''ll also feel your glutes working to support the movement. Include this in your routine for better mobility and reduced muscle tension.', '105651201', '105651201-90-to-90-Press-Stretch-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Execute the pressing motion for 90 To 90 Press Stretch, extending through the target muscles. 2. Move into the stretch position for 90 To 90 Press Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 60, 2, 6, FALSE, TRUE, 'stretch_general', '90 To 90 Press Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('fbc47734-941b-46dd-ab63-3c9953cc8734', '90 Degree Heel Touch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. Your abs work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '46441201', '46441201-90-Degree-Heel-Touch-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:30.292204+00', '1. Set up in the starting position for 90 Degree Heel Touch. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', '90 Degree Heel Touch', 'crunch, bicycle_crunch, russian_twist', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fbd4d432-4f14-4d32-845c-502634e84ad1', 'Seated Shoulder Press Toe Touch (Chair)', 'Shoulders', 'Chair', '{"Shoulders"}'::text[], '{"Side Delts","Triceps"}'::text[], 'The Seated Shoulder Press Toe Touch On A Chair is a pressing exercise that targets your delts for shoulder development. The triceps assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. Strong shoulders improve overhead strength and support nearly all upper body movements.', '90791201', '90791201-Sitting-Shoulder-Press-Toe-Touch-on-a-Chair-(femal.mp4', 'female', FALSE, '2025-12-03 23:26:37.877283+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Complete all reps with control before resting. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'shoulder_press', 'Seated Shoulder Press Toe Touch On A Chair', 'lateral_raise, front_raise, rear_delt', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fbe6e660-7768-41e3-81d4-38a815ff1265', 'Lying Sole Kick - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lying Alternate Sole Kick is a lower body kicking exercise that targets your core. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '81351201', '81351201-Lying-Alternate-Sole-Kick-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:27.145158+00', '1. Lie down in the appropriate position for Lying Alternate Sole Kick. 2. Alternate between sides/arms/legs with each repetition. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Sole Kick - Alternating', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fbe80ec8-5ab6-4227-b83b-2b422a237e16', 'Half Squat Side Reach', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Half Squat Side Reach is a core squatting exercise that primarily targets your abs. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '59371201', '59371201-Half-Squat-Side-Reach-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep. Ideal for abs strength and endurance.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'lat_stretch', 'Half Squat Side Reach', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fbf42618-0e43-4af2-bb78-d6539b07925a', 'Elbow Plank (TRX)', 'Core', 'TRX', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Build a stronger core with the Suspender Elbow Plank, focusing on your abs. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. The TRX allows you to adjust difficulty by changing your body angle. A strong core improves posture, protects your spine, and enhances all other lifts.', '64891201', '64891201-Suspender-Elbow-Plank-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Elbow Plank. 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'plank', 'Suspender Elbow Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'trx', TRUE, 3, 90, 4, 68, 85, 85, 70),
('fbf7b0d3-73de-443e-b944-1db581e1fd36', 'Seated Single Leg Hamstring Stret (Resistance Band)', 'Legs', 'Resistance Band, Gymnastic Rings', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'Strengthen your midsection with this movement movement that works your core. Being seated provides stability, allowing you to focus on the working muscles. Bands are joint-friendly and portable, perfect for any training environment. A strong core improves posture, protects your spine, and enhances all other lifts.', '107441201', '107441201-Resistance-Band-Seated-Single-Leg-Hamstring-Stret.mp4', 'male', FALSE, '2025-12-03 23:26:25.233728+00', '1. Secure the resistance band appropriately for Resistance Band Seated Single Leg Hamstring Stret. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Complete all reps on one side, then switch to the other side. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 30, 7, 8, TRUE, TRUE, 'leg_exercise', 'Seated Single Leg Hamstring Stret', 'squat, lunge, leg_press', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('fbfec768-c5ad-432a-8095-a58b5a36b586', 'Weighted Backpack Running', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'A challenging plyometric exercise, the Weighted Backpack Running builds reactive power and improves conditioning. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '106771201', '106771201-Weighted-Backpack-Running-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Set up in the starting position for Weighted Backpack Running. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'running', 'Weighted Backpack Running', 'cycling, rowing_cardio, jump_rope', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('fc052163-4eca-4dbf-b802-b5dc050f6702', 'Bulgarian Split Squat (Plate)', 'Legs', 'Weight Plate', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '66781201', '66781201-Weighted-Plates-Bulgarian-Split-Squat_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Start with lighter weight to perfect your form. An effective movement for your legs routine.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'split_squat', 'Weighted Plates Bulgarian Split Squat', 'split_squat, lunge, leg_press', TRUE, 'plate', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fc13d052-ffd3-41c1-9c94-3635f6c45fb9', 'Standing Calf Raise (Machine)', 'Legs', 'Calf Raise Machine', '{"Calves"}'::text[], '{}'::text[], 'Build stronger calves with this targeted raising exercise. The standing position engages your core for stability. The fixed path allows you to focus purely on muscular effort. Strong legs are the foundation for athletic performance and functional fitness.', '22111201', '22111201-Lever-Standing-Calf-Raise-(female)_Calves.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Standing Calf Raise. 2. Stand tall with your feet firmly planted. 3. Lower your heels below the platform to get a full stretch. 4. Rise up onto your toes as high as possible, squeezing your calves. 5. Lower with control and repeat. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'calf_raise', 'Lever Standing Calf Raise', 'calf_raise, seated_calf_raise', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('fc163bba-be51-49bd-ad77-4211780aa277', 'Reverse Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this crunching movement that works your abs. You''ll also feel your hip flexors working to support the movement. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '81311201', '81311201-Reverse-Crunch-(VERSION-2)-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Lift your hips off the floor by contracting your lower abs. 2. Bring your knees toward your chest, then lower with control. 3. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Reverse Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('fc1722f9-9bd7-41e0-80f3-9685768c4b46', 'Standing Deep Breathe And Prayer Pull', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This pulling exercise works your full body for improved shoulder strength and aesthetics. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Strong shoulders improve overhead strength and support nearly all upper body movements.', '95551201', '95551201-Standing-Deep-Breathe-And-Prayer-Pull-(female)_Sho.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Deep Breathe And Prayer Pull. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'breathing', 'Standing Deep Breathe And Prayer Pull', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fc307f50-8c9a-4d71-b0f3-249f339e6de6', 'Back Shuffle Side Kickout', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build power and athleticism with this high-intensity kicking exercise that challenges your entire body. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities. Can be modified for beginners or progressed for advanced athletes.', '75711201', '75711201-Back-Shuffle-Side-Kickout-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Set up in the starting position for Back Shuffle Side Kickout. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'shuffle', 'Back Shuffle Side Kickout', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('fc3d8a6d-d2fc-4368-b710-6cda15002985', 'Alternative Fly (Dumbbell)', 'Chest', 'Dumbbells, Flat Bench', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Dumbbell Alternative Fly is a flying exercise that targets your chest muscles. Your front delts work as secondary movers, adding to the training stimulus. Using dumbbells requires more stabilization than barbell variations. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '93021201', '93021201-Dumbbell-Alternative-Fly-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Alternative Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'chest_fly', 'Alternative Fly', 'bench_press, incline_press, push_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('fc51b289-ca74-4ae2-aa42-bcbaff84cc01', 'Ring Support Hold (Gymnastic Rings)', 'Chest', 'Gymnastic Rings', '{"Chest"}'::text[], '{}'::text[], 'Target your chest with the Ring Support Hold, an effective movement movement for upper body strength. A well-developed chest contributes to upper body strength and aesthetics.', '74531201', '74531201-Ring-Support-Hold_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Hold the position for the prescribed time, maintaining tension. 2. Set up in the starting position for Ring Support Hold. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 33, 7, 8, TRUE, TRUE, 'general_exercise', 'Ring Support Hold', 'squat, bench_press, deadlift', FALSE, 'gymnastic_rings', TRUE, 3, 90, 4, 68, 85, 85, 70),
('fc5648f5-1efb-41db-b49d-14b2787ee2c9', 'Banded Bench Squat (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Secondary activation of your glutes, hamstrings provides additional muscle engagement. The barbell allows you to handle heavier loads for maximum strength gains. Strong legs are the foundation for athletic performance and functional fitness.', '40611201', '40611201-Barbell-Banded-Bench-Squat_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Load a barbell and set it on a bench rack at the appropriate height. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'squat', 'Banded Bench Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', TRUE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('fc57cdcd-d727-479b-8c17-2db8a268cfcd', 'Side Lying Clam', 'Legs', 'Bodyweight', '{"Glutes","Hips"}'::text[], '{"Hamstrings"}'::text[], 'The Side Lying Clam is a lower body movement exercise that targets your glute med/abductors. The lying position provides back support and helps isolate the target muscles. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '24611201', '24611201-Side-Lying-Clam_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Lie on your side with your body aligned. 2. Set up in the starting position for Side Lying Clam. 3. Execute the movement with proper form, focusing on your glute med/abductors. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_abduction', 'Side Lying Clam', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fc58b3df-ef20-41d8-8737-9585b552bbd7', 'Hanging Straight Leg Raise (Pull-Up Bar)', 'Core', 'Pull-Up Bar', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this raising movement focusing on your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. Hanging adds a grip and core stability component to the exercise. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '25301201', '25301201-Hanging-Straight-Leg-Raise-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Grip the bar and hang with arms fully extended, engaging your shoulders. 2. Keeping legs mostly straight, raise them toward the ceiling. 3. Lower with control, stopping just before touching down. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'romanian_deadlift', 'Hanging Straight Leg Raise', 'deadlift, leg_curl, hip_thrust', FALSE, 'pull_up_bar', FALSE, 3, 60, 2, 70, 88, 95, 65),
('fc5e9f02-1a34-489a-a1fd-b12350585f81', 'Plank Pike Slide (Towel)', 'Core', 'Towel', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Build a stronger core with the Plank Pike Slide With Towel, focusing on your abs. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. Core strength is foundational for athletic performance and injury prevention.', '81101201', '81101201-Plank-Pike-Slide-with-Towel-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Plank Pike Slide With Towel', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('fc5f30d7-7b6e-49c2-a215-bf3dada67881', 'Seated Elbow Clap (Chair)', 'Chest', 'Chair', '{"Chest"}'::text[], '{}'::text[], 'Target your chest with the Seated Elbow Clap On A Chair, an effective movement movement for upper body strength. Being seated provides stability, allowing you to focus on the working muscles. A well-developed chest contributes to upper body strength and aesthetics.', '91111201', '91111201-Sitting-Elbow-Clap-on-a-Chair-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Complete all reps with control before resting. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'boxing', 'Seated Elbow Clap On A Chair', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fc6f5540-d235-4a5a-b2fb-c749b5e0fc77', 'Glute Bridge And Open Up', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger glutes with this bridging movement focused on hip extension. Your hamstrings work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength. A staple exercise that belongs in most training programs.', '94421201', '94421201-Glute-Bridge-and-Open-Up-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum. A solid choice for legs day.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'glute_bridge', 'Glute Bridge And Open Up', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fc9a7bfc-2dc6-4888-84cb-9faeefa9df9b', 'Rear Lunge Bicep Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Quads","Glutes","Hamstrings","Biceps"}'::text[], '{"Forearms"}'::text[], 'Build stronger quads with this curling movement that develops leg drive and power. Secondary activation of your glutes, hamstrings provides additional muscle engagement. The dumbbell variation provides freedom of movement and greater range of motion. Strong legs are the foundation for athletic performance and functional fitness.', '104351201', '104351201-Dumbbell-Rear-Lunge-Biceps-Curl-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Rear Lunge Biceps Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 92, 7, 8, TRUE, TRUE, 'bicep_curl', 'Rear Lunge Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('fca606ab-a7d5-47a7-979d-0b184df3cf13', 'Seated Row (Band)', 'Back', 'Resistance Band, Anchor Point', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. You''ll also feel your biceps, lats working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. Bands are joint-friendly and portable, perfect for any training environment. A strong back improves posture, prevents injury, and balances pressing movements.', '9181201', '09181201-Band-seated-row-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Seated Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 87, 7, 8, TRUE, TRUE, 'cable_row', 'Seated Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('fcb224fb-d95f-4929-864f-4c113a6e5586', 'Seated Abduction (Chair)', 'Legs', 'Chair', '{"Glutes","Hips"}'::text[], '{"Hamstrings"}'::text[], 'The Seated Abduction On A Chair is a lower body movement exercise that targets your glute med/abductors. The seated position helps isolate the target muscles by removing momentum. Lower body strength improves everything from walking to heavy compound lifts.', '82801201', '82801201-Seated-Abduction-on-a-Chair-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'hip_abduction', 'Seated Abduction On A Chair', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fcb815b9-d864-4311-b014-1ff168376e72', 'Seated Back Press', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger back with this pressing movement targeting your core. The seated position helps isolate the target muscles by removing momentum. A strong back improves posture, prevents injury, and balances pressing movements.', '87271201', '87271201-Seated-Back-Press-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Execute the pressing motion for Seated Back Press, extending through the target muscles. 3. Complete all reps with control before resting. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'back_exercise', 'Seated Back Press', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fcc19bd0-8523-45f7-9694-b1b01aaabc7d', 'Single Arm Lat Pulldown (Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. Secondary activation of your biceps, upper back provides additional muscle engagement. Cables provide constant tension throughout the full range of motion. A strong back improves posture, prevents injury, and balances pressing movements.', '12041201', '12041201-Cable-One-Arm-Lat-Pulldown_Back-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Adjust the cable machine to the correct height and attachment for Cable One Arm Lat Pulldown. 2. Pull the bar/handle down toward your upper chest. 3. Drive your elbows down and back, squeezing your lats. 4. Control the weight back up without letting it yank your arms. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Single Arm Lat Pulldown', 'pull_up, bent_over_row, cable_row, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('fcc2378a-a3e3-4c53-bfc4-1d71cf57de38', 'Gripless Shrug (Machine)', 'Back', 'Shrug Machine', '{"Traps"}'::text[], '{"Upper Back"}'::text[], 'The Lever Gripless Shrug is a shrugging exercise that develops back strength and muscle. Machine exercises are great for isolating muscles and training to failure safely. Back development is crucial for pulling strength and overall upper body function.', '14391201', '14391201-Lever-Gripless-Shrug-(Version-2)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Gripless Shrug. 2. Shrug your shoulders straight up toward your ears. 3. Hold briefly at the top, then lower with control. 4. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'shrug', 'Lever Gripless Shrug', 'deadlift, bent_over_row, face_pull', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('fcc2f9c9-d604-4dfc-acf4-346638aa8e55', 'Standing Prone Lateral Raise (Kettlebell)', 'Shoulders', 'Kettlebell', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'Target your lateral delts with the Kettlebell Standing Prone Lateral Raise, an effective shoulder raising exercise. The standing position engages your core for stability. The kettlebell''s offset center of mass increases the stability challenge. Shoulder development enhances both performance and upper body aesthetics.', '83361201', '83361201-Kettlebell-Standing-Prone-Lateral-Raise-(male)_Sho.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Select an appropriately weighted kettlebell for Kettlebell Standing Prone Lateral Raise. 2. Begin in a standing position with good posture. 3. Raise your arms out to the sides until parallel to the floor. 4. Lower with control, maintaining tension throughout. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'lateral_raise', 'Standing Prone Lateral Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78),
('fcc31472-4c69-4e58-9d98-bbec9f4a5243', 'Bridge Yoga Pose Setu Bandha Sarvangasana', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Develop your posterior chain with this bridging movement that emphasizes the glutes. Secondary activation of your hamstrings provides additional muscle engagement. The band creates increasing tension as it stretches, challenging the lockout. Leg training boosts metabolism and builds functional, real-world strength.', '81481201', '81481201-Bridge-Yoga-Pose-Setu-Bandha-Sarvangasana-(female).mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Secure the resistance band appropriately for Bridge Yoga Pose Setu Bandha Sarvangasana. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Bridge Yoga Pose Setu Bandha Sarvangasana', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 60, 85, 90, 50),
('fccd8468-40ea-45b7-84f0-8505836f52f8', 'Clap Curtsey Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Clap Curtsey Squat is a squatting exercise that primarily loads your quadriceps. You''ll also feel your glutes, hamstrings working to support the movement. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '55471201', '55471201-Clap-Curtsey-Squat-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Focus on the mind-muscle connection. Ideal for quads strength and endurance.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Clap Curtsey Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fcd3dc68-1574-4c79-8034-dff9887da26b', 'Knee Raise Step Jack', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'A challenging plyometric exercise, the Knee Raise Step Jack builds reactive power and improves conditioning. You''ll also feel your hip flexors working to support the movement. Plyometric training builds explosive power that transfers to sports and daily activities.', '57421201', '57421201-Knee-Raise-Step-Jack-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Set up a box or step platform at the appropriate height. 2. Raise the weight in the prescribed direction for Knee Raise Step Jack. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'leg_raise', 'Knee Raise Step Jack', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('fcd4067c-bb5f-4eba-a775-fb0bf2ab4e62', 'Deadlift (Trap Bar)', 'Back', 'Trap Bar', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'The Trap Bar Deadlift is a lower body hip hinge exercise that targets your hamstrings/glutes. Secondary activation of your glutes, lower back provides additional muscle engagement. Strong legs are the foundation for athletic performance and functional fitness.', '8111201', '08111201-Trap-Bar-Deadlift_Thighs-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Hinge at hips and bend knees to grip the weight. 2. Drive through your heels, extending hips and knees to stand. 3. Lower by reversing the movement with control. 4. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form. Beneficial for overall legs development.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 85, 7, 9, TRUE, FALSE, 'deadlift', 'Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', FALSE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('fcdc7dc9-eb90-42ef-ad12-c8bb0638f935', 'Floor Hyperextension', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Develop your posterior chain with this extension movement that emphasizes the glutes. Secondary activation of your hamstrings, lower back provides additional muscle engagement. Leg training boosts metabolism and builds functional, real-world strength.', '23941201', '23941201-Floor-Hyperextension-(female)_Hips-FIX.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Position yourself on the floor for Floor Hyperextension. 2. Raise your torso by extending at the lower back/hips. 3. Lower with control, maintaining tension. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'back_extension', 'Floor Hyperextension', 'good_morning, bird_dog, superman', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('fce9e011-d8ae-4436-8c6b-9a30fb95ea2c', 'Standing Calf Raise With Support', 'Legs', 'Bodyweight', '{"Calves"}'::text[], '{}'::text[], 'This raising movement focuses on your gastrocnemius and soleus. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '31201201', '31201201-Standing-Calf-Raise-with-Support-(female)_Calves_.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Begin in a standing position with good posture. 2. Lower your heels below the platform to get a full stretch. 3. Rise up onto your toes as high as possible, squeezing your calves. 4. Lower with control and repeat. 5. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'calf_raise', 'Standing Calf Raise With Support', 'calf_raise, seated_calf_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('fcf1cb12-123c-45c9-97a7-29157af161a9', 'Box Single Leg Assisted Pull Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Box Single Leg Assisted Pull Up is a pulling exercise that targets your latissimus dorsi for a wider back. The biceps, upper back assist throughout the movement, making this a well-rounded exercise. Back development is crucial for pulling strength and overall upper body function.', '95121201', '95121201-Box-Single-Leg-Assisted-Pull-up-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Set up a box or step platform at the appropriate height. 2. Pull yourself up by driving your elbows down and back. 3. Continue until your chin clears the bar, then lower with control to a full hang. 4. Complete all reps on one side, then switch to the other side. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'pull_up', 'Box Single Leg Assisted Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fcf64cc4-4c2b-4c26-89d2-6e948a221979', 'Arms Circle Knee Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This dynamic raising movement gets your heart rate up while developing explosive strength. Your hip flexors work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '68881201', '68881201-Arms-Circle-Knee-Raise-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Raise the weight in the prescribed direction for Arms Circle Knee Raise. 2. Lower with control, maintaining tension throughout. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Arms Circle Knee Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('fd2db548-4f6e-452d-be65-f61598009a47', 'Roll Pigeon Stretch', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'The Roll Pigeon Stretch is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Include this in your routine for better mobility and reduced muscle tension.', '54271201', '54271201-Roll-Pigeon-Stretch-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Move into the stretch position for Roll Pigeon Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Roll Pigeon Stretch', 'stretch_hamstring, stretch_glute, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('fd3354ef-3dd6-44e3-86d3-b163a3431103', 'Standing Reach Down Hamsting Crossed Legs Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Designed to lengthen your full body, the Standing Reach Down Hamsting Crossed Legs Stretch helps improve mobility and prevent stiffness. The standing position engages your core for stability. Include this in your routine for better mobility and reduced muscle tension.', '19171201', '19171201-Standing-Reach-Down-Hamsting-Crossed-Legs-Stretch-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Stand tall with your feet firmly planted. 2. Move into the stretch position for Standing Reach Down Hamsting Crossed Legs Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'stretch_general', 'Standing Reach Down Hamsting Crossed Legs Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('fd3ae060-95bc-40db-bcc4-604525072a2f', 'Standing Slight Bent Top Clap Back Clap', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Shoulders","Lats"}'::text[], 'This stretch specifically works on your back, promoting flexibility and reducing muscle tightness. Your shoulders, lats work as secondary movers, adding to the training stimulus. The standing position engages your core for stability. Include this in your routine for better mobility and reduced muscle tension.', '94781201', '94781201-Standing-Slight-Bent-Top-Clap-Back-Clap-(female)_S.mp4', 'female', FALSE, '2025-12-03 23:26:38.992671+00', '1. Stand with feet about shoulder-width apart. 2. Move into the stretch position for Standing Slight Bent Top Clap Back Clap. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'back_exercise', 'Standing Slight Bent Top Clap Back Clap', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fd407043-eddf-4e6f-9b57-f1fcd974f66c', 'Walking Lunge (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this lunging movement that develops leg drive and power. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Using a barbell provides stability for progressive overload. Strong legs are the foundation for athletic performance and functional fitness.', '58231201', '58231201-Barbell-Walking-Lunge_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Grip a barbell with hands at the appropriate width for Barbell Walking Lunge. 2. Step forward into a lunge, then bring your back foot forward for the next step. 3. Push through your front/working leg to return to the starting position. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 82, 9, 8, FALSE, TRUE, 'lunge', 'Walking Lunge', 'split_squat, step_up, squat', FALSE, 'barbell', TRUE, 1, 60, 4, 95, 80, 65, 95),
('fd427a23-ba65-4439-b723-ccc705a76357', 'Neck Side Stretch', 'Neck', 'Bodyweight', '{"Neck"}'::text[], '{"Traps"}'::text[], 'Use this stretch to open up your neck area and enhance overall flexibility. Include this in your routine for better mobility and reduced muscle tension. Keep your core engaged throughout the exercise.', '42891201', '42891201-Neck-Side-Stretch-(female)_Neck.mp4', 'female', FALSE, '2025-12-03 23:26:35.532804+00', '1. Move into the stretch position for Neck Side Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'lat_stretch', 'Neck Side Stretch', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('fd568d67-9ce6-4aa5-b38c-1e1d08c97590', 'Seated Fist Pulse', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Seated Fist Pulse is an arm movement exercise targeting your core. Being seated provides stability, allowing you to focus on the working muscles. Arm strength supports grip, pulling, and pushing in compound movements.', '87311201', '87311201-Seated-Fist-Pulse-(female)_Forearms_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. At the bottom or top, pulse up and down in small movements before completing the rep. 3. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'pulse', 'Seated Fist Pulse', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fd6a9749-a3a9-4927-8ea0-c6ea21042ae9', 'Superman Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Superman Push Up, an effective pushing movement for upper body strength. The glutes assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. A well-developed chest contributes to upper body strength and aesthetics. Control the negative portion for maximum muscle engagement.', '70751201', '70751201-Superman-Push-up-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement. Great for building strength in your chest.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'back_extension', 'Superman Push Up', 'bench_press, chest_fly, dip, tricep_pushdown', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fd708512-ef3a-41bd-8816-663a89da45eb', 'Single Leg Romanian Deadlift (Dumbbell)', 'Legs', 'Dumbbells', '{"Hamstrings"}'::text[], '{"Glutes","Lower Back"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. Your glutes, lower back work as secondary movers, adding to the training stimulus. Using dumbbells requires more stabilization than barbell variations. Lower body strength improves everything from walking to heavy compound lifts.', '97521201', '97521201-Dumbbell-Single-Leg-Romanian-Deadlift-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Push your hips back, lowering the weight along your legs with a flat back. 3. Lower until you feel a stretch in your hamstrings. 4. Drive hips forward to stand, squeezing glutes at the top. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 92, 7, 9, TRUE, FALSE, 'romanian_deadlift', 'Single Leg Romanian Deadlift', 'deadlift, leg_curl, hip_thrust', FALSE, 'dumbbell', FALSE, 4, 120, 6, 92, 90, 92, 90),
('fd730105-2d4b-44b3-a856-8d4ec6a63852', 'Floor Chest Press (Barbell)', 'Chest', 'Barbell', '{"Chest"}'::text[], '{"Front Delts","Lower Chest","Triceps"}'::text[], 'The Barbell Floor Chest Press is a pressing exercise that targets your chest muscles. You''ll also feel your triceps, front delts working to support the movement. The barbell allows you to handle heavier loads for maximum strength gains. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '97531201', '97531201-Barbell-Floor-Chest-Press-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Place a loaded barbell on the floor in front of you. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'bench_press', 'Floor Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', TRUE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('fd93f6c0-14e0-479b-8eea-4c9b3a7d2cb5', 'Decline Chest Fly (Cable)', 'Chest', 'Cables', '{"Chest","Lower Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'This flying exercise focuses on your pectorals for improved chest strength and development. The front delts assist throughout the movement, making this a well-rounded exercise. The decline position targets the lower portion of the muscles more intensely. Cable resistance creates smooth, continuous muscle engagement. A well-developed chest contributes to upper body strength and aesthetics.', '25121201', '25121201-Cable-Decline-Fly-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:28.397686+00', '1. Adjust the cable machine to the correct height and attachment for Cable Decline Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Continue for your target rep count, maintaining good form throughout.', 'Fly', 'Pull', 'Compound', 'Bilateral', NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 83, 5, 7, FALSE, TRUE, 'chest_fly', 'Decline Fly', 'bench_press, incline_press, push_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('fd968fbb-9faf-4224-ae23-8b1c6d17634f', 'Standing Single Shoulder Stretch (Wall Supported)', 'Shoulders', 'Wall', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Use this stretch to open up your shoulders area and enhance overall flexibility. You''ll also feel your upper back working to support the movement. Performing this standing challenges your balance and core engagement. Include this in your routine for better mobility and reduced muscle tension.', '95481201', '95481201-Standing-Single-Shoulder-Stretch-Wall-Supported-(f.mp4', 'female', FALSE, '2025-12-03 23:26:38.992671+00', '1. Position yourself at the appropriate distance from a wall. 2. Stand tall with your feet firmly planted. 3. Move into the stretch position for Standing Single Shoulder Stretch Wall Supported. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 6. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 34, 2, 6, FALSE, TRUE, 'shoulder_stretch', 'Standing Single Shoulder Stretch Wall Supported', 'stretch_chest, stretch_tricep, stretch_lat', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('fd9e376d-f894-4bf3-93e2-c4304608324b', 'Arms Circle Marching On Spot', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements. Aim for full range of motion on every rep.', '85821201', '85821201-Arms-Circle-Marching-On-Spot-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Set up in the starting position for Arms Circle Marching On Spot. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, 'Dynamic', 'Compound', 'Bilateral', NULL, 2, NULL, 2, 2, NULL, 10, 'Standing', NULL, 'Neutral', 'Standard', 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'marching', 'Arms Circle Marching On Spot', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('fdab7815-513f-4f7e-8a3d-e7f500f0e165', 'Raise Single Leg Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pushing movement that develops pressing power. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. A well-developed chest contributes to upper body strength and aesthetics.', '6671201', '06671201-Raise-Single-Leg-Push-up-(female)_Chest-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Complete all reps on one side, then switch to the other side. 5. Complete all reps with control before resting. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'push_up', 'Raise Single Leg Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fdacb1ad-d495-4153-86df-397b2e7d2bd4', 'Seated Air Bike (Chair)', 'Core', 'Air Bike, Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Seated Air Bike On A Chair, focusing on your abs. The seated position helps isolate the target muscles by removing momentum. A strong core improves posture, protects your spine, and enhances all other lifts.', '69041201', '69041201-Sitting-Air-Bike-on-a-Chair-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears. Perfect for targeting your abs.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 20, 9, 8, FALSE, TRUE, 'cycling', 'Seated Air Bike On A Chair', 'crunch, russian_twist, leg_raise', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('fdc094b2-a40f-4f3a-aefb-726dc694fe8a', 'Commando Pull Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Commando Pull Up is a pulling exercise that targets your latissimus dorsi for a wider back. You''ll also feel your biceps, upper back working to support the movement. No equipment needed—your body provides all the resistance. A strong back improves posture, prevents injury, and balances pressing movements.', '52701201', '52701201-Commando-Pull-up-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement. A solid choice for back day.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Commando Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fde5b518-3154-4f03-824c-f583d173343c', 'Standing Raised Leg Hip Adductor Stretch', 'Legs', 'Bodyweight', '{"Inner Thighs"}'::text[], '{}'::text[], 'The Standing Raised Leg Hip Adductor Stretch is a lower body raising exercise that targets your adductors. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '18961201', '18961201-Standing-Raised-Leg-Hip-Adductor-Stretch-(female)_.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Raised Leg Hip Adductor Stretch. 3. Execute the movement with proper form, focusing on your adductors. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 62, 2, 6, FALSE, TRUE, 'hip_adduction', 'Standing Raised Leg Hip Adductor Stretch', 'hip_abduction, squat, lunge', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('fe0b3005-8ae0-4f3c-a5a6-e8469b0acda6', 'Front Lat Pulldown - Close Grip (Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. Your biceps, upper back work as secondary movers, adding to the training stimulus. Cable resistance creates smooth, continuous muscle engagement. Back development is crucial for pulling strength and overall upper body function.', '10471201', '10471201-Cable-Close-Grip-Front-Lat-Pulldown_Back.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Adjust the cable machine to the correct height and attachment for Cable Close Grip Front Lat Pulldown. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Pull the bar/handle down toward your upper chest. 4. Drive your elbows down and back, squeezing your lats. 5. Control the weight back up without letting it yank your arms. 6. Complete all reps with control before resting. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 90, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Front Lat Pulldown - Close Grip', 'Front Lat Pulldown - Close Grip', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('fe0d8e19-eb04-4252-8a2a-ca306aef0026', 'Standing Bicep Curl - Inner (Dumbbell)', 'Arms', 'Dumbbells', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Secondary activation of your forearms provides additional muscle engagement. Performing this standing challenges your balance and core engagement. Dumbbells allow each arm to work independently, helping correct imbalances. Arm strength supports grip, pulling, and pushing in compound movements.', '70251201', '70251201-Dumbbell-Standing-Inner-Biceps-Curl-(version-2)-(f.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Inner Biceps Curl. 2. Begin in a standing position with good posture. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'bicep_curl', 'Standing Inner Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('fe1cc734-6852-49ac-968d-8daf1105137a', 'Hip Abduction (Band)', 'Legs', 'Resistance Band', '{"Glutes"}'::text[], '{"Hip Abductors"}'::text[], 'The Band Hip Abduction is a lower body movement exercise that targets your hip abductors. The glutes assist throughout the movement, making this a well-rounded exercise. Resistance bands provide accommodating resistance that increases through the range of motion. Lower body strength improves everything from walking to heavy compound lifts.', '8991201', '08991201-Band-hip-abduction-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Secure the resistance band appropriately for Band Hip Abduction. 2. Set up in the starting position for Band Hip Abduction. 3. Execute the movement with proper form, focusing on your hip abductors. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'hip_abduction', 'Hip Abduction', 'hip_adduction, glute_bridge, clamshell', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('fe29c871-0485-4eed-9234-8b882ebf4c4b', 'Side Swing Skater Stepback', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Quads","Hip Abductors"}'::text[], 'Elevate your training with this swinging exercise that develops speed, power, and coordination. You''ll also feel your quads working to support the movement. Plyometric training builds explosive power that transfers to sports and daily activities.', '80311201', '80311201-Side-Swing-Skater-Stepback-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.303932+00', '1. Set up a box or step platform at the appropriate height. 2. Hinge at your hips, letting the weight swing back between your legs. 3. Explosively drive hips forward, propelling the weight forward/up. 4. Let gravity bring it back as you hinge for the next rep. 5. Complete all reps with control before resting. Maintain consistent tempo throughout the set. Works well for full body activation.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'kettlebell_swing', 'Side Swing Skater Stepback', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('fe36af96-8ff9-4eba-94ad-3e1bffc8ff80', 'Standing Opposite Grab (Chair)', 'Full Body', 'Chair', '{"Full Body"}'::text[], '{}'::text[], 'This full-body movement exercise challenges multiple muscle groups simultaneously. Performing this standing challenges your balance and core engagement. Full body exercises are time-efficient and build functional, real-world strength.', '94361201', '94361201-Standing-Opposite-Grab-on-a-Chair-(VERSION-2)-(fem.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Begin in a standing position with good posture. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'core_exercise', 'Standing Opposite Grab On A Chair', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fe38f431-5862-4299-8ece-dd029caa8011', 'Renegade Row (Resistance Band)', 'Back', 'Resistance Band, Anchor Point', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Resistance Band Renegade Row is a core rowing exercise that primarily targets your abs. You''ll also feel your biceps, rear delts working to support the movement. Resistance bands provide accommodating resistance that increases through the range of motion. A strong core improves posture, protects your spine, and enhances all other lifts.', '82241201', '82241201-Resistance-Band-Renegade-Row-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:27.145158+00', '1. Secure the resistance band appropriately for Resistance Band Renegade Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'dumbbell_row', 'Renegade Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('fe3d5e9a-bccd-45db-8573-37804e2175f3', 'Overhead Triceps Extension Straight Bar (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Shoulders"}'::text[], 'This extension movement isolates your triceps for improved arm development. The cable setup allows you to adjust the angle of resistance. Dedicated arm training builds both strength and muscular definition.', '97381201', '97381201-Cable-Overhead-Tricep-Extension-Straight-Bar-(fema.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Overhead Triceps Extension Straight Bar. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'tricep_extension', 'Overhead Triceps Extension Straight Bar', 'tricep_pushdown, close_grip_bench', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('fe4c2bd8-2f6a-4fd9-a3d1-9869e81a5d40', 'Wide Squat (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Barbells enable bilateral loading for building raw strength. Strong legs are the foundation for athletic performance and functional fitness. Focus on controlled form throughout each repetition.', '25181201', '25181201-Barbell-Wide-Squat-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Wide Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'squat', 'Wide Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', TRUE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('fe516f19-9284-48bf-a1ff-9f8c68c33e3e', 'Chaturanga Dandasana (four Limbed Staff Pose)', 'Core', 'Bodyweight', '{"Core"}'::text[], '{}'::text[], 'Target your full body with this movement stretch that helps restore range of motion. Flexibility work like this enhances performance and prevents stiffness. Works well as both a primary exercise or accessory movement.', '62901201', '62901201-Chaturanga-Dandasana-(Four-Limbed-Staff-Pose)-(fem.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Move into the stretch position for Chaturanga Dandasana. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Chaturanga Dandasana', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('fe55dfe6-a92a-47d1-bf29-e149e798a958', 'Gate Rock', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Gate Rock is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '89721201', '89721201-Gate-Rock-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Move into the stretch position for Gate Rock. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'dynamic_warmup', 'Gate Rock', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fe564187-1173-43d7-ab37-083589be8214', 'Hamstring Curl Pulldown (Gymnastic Rings) - Alternating', 'Back', 'Gymnastic Rings', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'A challenging plyometric exercise, the Alternating Hamstring Curl Pulldown builds reactive power and improves conditioning. The forearms assist throughout the movement, making this a well-rounded exercise. Plyometric training builds explosive power that transfers to sports and daily activities.', '76761201', '76761201-Alternating-Hamstring-Curl-Pulldown-(male)_Plyomet.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Keep your elbows in a fixed position throughout the movement. 2. Curl the weight up by contracting your biceps, squeezing at the top. 3. Lower with control, resisting the weight on the way down. 4. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'leg_curl', 'Hamstring Curl Pulldown - Alternating', 'romanian_deadlift, hip_thrust', FALSE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('fe56f37c-bbab-4df0-ae0f-157ff48a9e9a', 'Bicep Curl (EZ Bar Cable Attachment)', 'Arms', 'Cables', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Cable Biceps Curl is a curling exercise that isolates your biceps. Your forearms work as secondary movers, adding to the training stimulus. The cable setup allows you to adjust the angle of resistance. Arm strength supports grip, pulling, and pushing in compound movements.', '71111201', '71111201-Cable-Biceps-Curl-(SZ-bar)-(female)_Upper-arms_.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Adjust the cable machine to the correct height and attachment for Cable Biceps Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'bicep_curl', 'Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('fe67df08-1def-46a2-99e0-acb54410fa68', 'Baseball Hit', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities. Works well as both a primary exercise or accessory movement.', '93931201', '93931201-Baseball-Hit-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Set up in the starting position for Baseball Hit. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Baseball Hit', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fe7001fd-9de0-4e28-886c-7939dd1597d8', 'Reverse Flutter Kicks (Bench)', 'Core', 'Bodyweight, Flat Bench', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this kicking movement focusing on your abs. Your hip flexors work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '11791201', '11791201-Flutter-Kicks-(version-2)_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Set up in the starting position for Flutter Kicks. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_raise', 'Flutter Kicks', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('fe767ef4-5cb4-4f81-93cc-60e83fc11403', 'Side Lying Floor Single Leg Kickback (Cable)', 'Legs', 'Cables', '{"Glutes"}'::text[], '{"Rear Delts"}'::text[], 'This kicking exercise isolates your glutes for improved hip strength and power. The hamstrings assist throughout the movement, making this a well-rounded exercise. Performing this lying down removes momentum for stricter form. Cable resistance creates smooth, continuous muscle engagement. Lower body strength improves everything from walking to heavy compound lifts.', '98631201', '98631201-Cable-Side-Lying-Floor-Single-Leg-Kickback-(female.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Side Lying Floor Single Leg Kickback. 2. Position yourself on the floor for Cable Side Lying Floor Single Leg Kickback. 3. Lie on your side with your body aligned. 4. Keep your upper arm stationary and extend your forearm back. 5. Squeeze at full extension, then return with control. 6. Complete all reps on one side, then switch to the other side. 7. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Side Lying Floor Single Leg Kickback', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('fe7d4da9-3811-4e1d-9062-0af51106a89a', 'Bicep Curl (Machine) - Alternating', 'Arms', 'Machine', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Lever Alternate Biceps Curl is a curling exercise that isolates your biceps. Secondary activation of your forearms provides additional muscle engagement. The fixed path allows you to focus purely on muscular effort. Arm strength supports grip, pulling, and pushing in compound movements.', '10321201', '10321201-Lever-Alternate-Biceps-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Alternate Biceps Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 88, 5, 7, FALSE, TRUE, 'bicep_curl', 'Lever Biceps Curl - Alternating', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('fe9086ef-4626-4cfe-b0a5-e934ecf86177', 'Reverse Lat Pulldown - Narrow Grip (Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This rowing exercise emphasizes your lats for improved back development. Secondary activation of your biceps, upper back provides additional muscle engagement. Cable resistance creates smooth, continuous muscle engagement. A strong back improves posture, prevents injury, and balances pressing movements.', '105031201', '105031201-Cable-Reverse-Narrow-grip-Lat-Pulldown-(male)_Bac.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Adjust the cable machine to the correct height and attachment for Cable Reverse Narrow Grip Lat Pulldown. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 90, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Reverse Lat Pulldown - Narrow Grip', 'Reverse Lat Pulldown - Narrow Grip', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('fe940b33-6684-456d-8f26-ef8e14a3ff5a', 'V Sit Under Knee Clap - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the V Sit Alternating Under Knee Clap, focusing on your abs. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '105831201', '105831201-V-Sit-Alternating-Under-Knee-Clap-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Alternate between sides/arms/legs with each repetition. 2. Set up in the starting position for V Sit Alternating Under Knee Clap. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'V Sit Under Knee Clap - Alternating', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('feae8e57-dee4-4149-bc22-a8c3994e48e1', 'Shoulder Grip Pull Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. Your biceps, upper back work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. A strong back improves posture, prevents injury, and balances pressing movements. Aim for full range of motion on every rep.', '39001201', '39001201-Shoulder-Grip-Pull-up-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Complete all reps with control before resting. Keep tension on the target muscles throughout. This variation specifically emphasizes the lats.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Shoulder Grip Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('feb07768-5d2e-4242-9ffb-7f0dca54248a', 'Single Leg Hyperextension (Dumbbell)', 'Back', 'Dumbbells, Hyperextension Bench', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger glutes with this extension movement focused on hip extension. Secondary activation of your hamstrings, lower back provides additional muscle engagement. Dumbbells allow each arm to work independently, helping correct imbalances. Strong legs are the foundation for athletic performance and functional fitness.', '105751201', '105751201-Dumbbell-Single-Leg-Hyperextension-(VERSION-2)-(m.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Extend your legs until straight, squeezing your quads at the top. 3. Lower with control back to the starting position. 4. Complete all reps on one side, then switch to the other side. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'back_extension', 'Single Leg Hyperextension', 'leg_curl, squat, leg_press, lunge', FALSE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('feb0d690-b177-4539-aa88-6546e3ce3856', 'Bent Over Row (Smith Machine)', 'Back', 'Smith Machine', '{Latissimus Dorsi}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. Secondary activation of your biceps, lats provides additional muscle engagement. Bending over allows gravity to provide resistance in a different plane. The fixed path allows you to focus purely on muscular effort. A strong back improves posture, prevents injury, and balances pressing movements.', '74201201', '74201201-Smith-Bent-Over-Row-(VERSION-2)-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Bent Over Row. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 78, 7, 9, TRUE, FALSE, 'bent_over_row', 'Smith Bent Over Row', 'Bent Over Row', FALSE, 'barbell', FALSE, 4, 120, 4, 80, 75, 20, 88),
('fec63b24-3813-41ea-96ff-d9f8cf11eb14', 'Hamstring Bridge March (Gymnastic Rings)', 'Legs', 'Gymnastic Rings', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Strengthen the back of your thighs with this bridging exercise. The hamstrings assist throughout the movement, making this a well-rounded exercise. Lower body strength improves everything from walking to heavy compound lifts.', '93581201', '93581201-Hamstring-Bridge-March-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 38, 7, 8, TRUE, TRUE, 'glute_bridge', 'Hamstring Bridge March', 'hip_thrust, romanian_deadlift', FALSE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('fec8c435-2e26-4a5e-aaaf-40ce712da765', 'Butt Kick Single Fly', 'Legs', 'Bodyweight', '{"Glutes","Hamstrings"}'::text[], '{"Calves"}'::text[], 'A challenging plyometric exercise, the Butt Kick Single Fly builds reactive power and improves conditioning. You''ll also feel your hamstrings working to support the movement. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '97751201', '97751201-Butt-Kick-Single-Fly-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:28.851102+00', '1. With a slight bend in your elbows, move the weight in a wide arc. 2. Squeeze your chest muscles at the center/top of the movement. 3. Return with control, feeling the stretch at the bottom. 4. Continue for your target rep count, maintaining good form throughout. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'glute_kickback', 'Butt Kick Single Fly', 'high_knees, jumping_jack, running', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('fed5bba0-ff9f-41a2-8416-ea4a78fe932f', 'Reverse Wrist Curl (Barbell)', 'Arms', 'Barbell', '{"Forearms"}'::text[], '{}'::text[], 'The Barbell Reverse Wrist Curl strengthens your forearms and grip through a curling motion. You''ll also feel your forearms working to support the movement. Using a barbell provides stability for progressive overload. Arm strength supports grip, pulling, and pushing in compound movements.', '30291201', '30291201-Barbell-Reverse-Wrist-Curl-(female)_Forearms_.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Grip a barbell with hands at the appropriate width for Barbell Reverse Wrist Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction.', 'Curl', 'Pull', 'Isolation', 'Bilateral', NULL, 3, NULL, 5, 7, NULL, 6, 'Seated', NULL, 'Overhand (Pronated)', 'Standard', 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'wrist_curl', 'Reverse Wrist Curl', 'hammer_curl, wrist_curl, bicep_curl', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('fed91884-e894-478a-b9c7-fb652534c778', 'King Pigeon Yoga Pose', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Designed to lengthen your hips, the King Pigeon Yoga Pose helps improve mobility and prevent stiffness. You''ll also feel your glutes working to support the movement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '76051201', '76051201-King-Pigeon-Yoga-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Move into the stretch position for King Pigeon Yoga Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'hip_stretch', 'King Pigeon Yoga Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('fed918b5-a974-4c8a-90a1-15e70499cae8', 'Row (TRX)', 'Back', 'TRX', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. Suspension training adds instability, increasing core activation throughout. A strong back improves posture, prevents injury, and balances pressing movements.', '10921201', '10921201-Suspender-Row-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'general_exercise', 'Suspender Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('fee04ed7-0d3b-4a32-9447-70e67157e74d', 'Glute Bridge Hip Abduction', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Develop your posterior chain with this bridging movement that emphasizes the glutes. The glutes assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '73371201', '73371201-Glute-Bridge-Hip-Abduction-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Continue for your target rep count, maintaining good form throughout. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'glute_bridge', 'Glute Bridge Hip Abduction', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('feeba8fa-3928-4c3a-a2f3-843b67910807', 'Side Punch With Opposite Leg Lift', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Shoulders"}'::text[], 'The Side Punch With Opposite Leg Lift is an explosive exercise that combines cardiovascular training with dynamic movement movements. You''ll also feel your shoulders working to support the movement. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '44331201', '44331201-Side-Punch-with-Opposite-Leg-Lift_Plyometrics.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Set up in the starting position for Side Punch With Opposite Leg Lift. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Side Punch With Opposite Leg Lift', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ff0341c9-b04b-4df5-b517-ecfdf8743171', 'Prone Y Raise', 'Shoulders', 'Bodyweight', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'The Prone Y Raise is a raising exercise that develops back strength and muscle. The upper back assist throughout the movement, making this a well-rounded exercise. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Back development is crucial for pulling strength and overall upper body function.', '58221201', '58221201-Prone-Y-Raise-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Lie face down (prone position) for Prone Y Raise. 2. Raise the weight in the prescribed direction for Prone Y Raise. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'lateral_raise', 'Prone Y Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('ff092520-4431-47c6-84fb-f2d1db0eac7e', 'Walkout To Plank Into Up Dog', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Elevate your training with this stabilization exercise that develops speed, power, and coordination. You''ll also feel your shoulders, lower back working to support the movement. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '83861201', '83861201-Walkout-to-Plank-into-Up-Dog-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Focus on maintaining proper breathing throughout. This exercise is excellent for abs development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Walkout To Plank Into Up Dog', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('ff0a3bb6-4e99-491a-8ee3-27da63133503', 'Single Arm Front Raise (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'Target your front delts with the Dumbbell One Arm Front Raise, an effective shoulder raising exercise. Dumbbells allow each arm to work independently, helping correct imbalances. Shoulder development enhances both performance and upper body aesthetics.', '74301201', '74301201-Dumbbell-One-Arm-Front-Raise-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Raise the weight in front of you to shoulder height. 3. Lower with control, maintaining tension throughout. 4. Complete all reps on one side, then switch to the other side. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'front_raise', 'Single Arm Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('ff0acae8-89e7-4567-a13e-33eeae74f498', 'Lying Arms Curl With Pillow', 'Arms', 'Bodyweight', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Secondary activation of your forearms provides additional muscle engagement. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Arm strength supports grip, pulling, and pushing in compound movements.', '82301201', '82301201-Lying-Arms-Curl-with-Pillow-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie down in the appropriate position for Lying Arms Curl With Pillow. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 10, 5, 7, FALSE, TRUE, 'arm_exercise', 'Lying Arms Curl With Pillow', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('ff101876-1853-42c5-9939-fa397066f747', 'Stiff Leg Deadlift From Stepbox (Cable)', 'Legs', 'Cables', '{"Hamstrings"}'::text[], '{"Glutes","Lower Back"}'::text[], 'The Cable Stiff Leg Deadlift From Stepbox is a lower body hip hinge exercise that targets your hamstrings/glutes. Your glutes, lower back work as secondary movers, adding to the training stimulus. Cables provide constant tension throughout the full range of motion. Strong legs are the foundation for athletic performance and functional fitness.', '28361201', '28361201-Cable-Stiff-Leg-Deadlift-from-Stepbox-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Stiff Leg Deadlift From Stepbox. 2. Set up a box or step platform at the appropriate height. 3. Push your hips back, lowering the weight along your legs with a flat back. 4. Lower until you feel a stretch in your hamstrings. 5. Drive hips forward to stand, squeezing glutes at the top. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 95, 7, 8, TRUE, TRUE, 'romanian_deadlift', 'Stiff Leg Deadlift From Stepbox', 'deadlift, leg_curl, hip_thrust', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('ff11b70c-bccf-4f85-950b-21c4ad3b4e51', 'Circles Arm', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Target your delts with the Circles Arm, an effective shoulder movement exercise. This bodyweight exercise requires no equipment and can be done anywhere. Shoulder development enhances both performance and upper body aesthetics.', '2541201', '02541201-Circles-Arm-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Set up in the starting position for Circles Arm. 2. Execute the movement with proper form, focusing on your delts. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'arm_exercise', 'Circles Arm', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ff158843-6ff5-4fd1-b087-239c07761fd6', 'Standing Leg Curl (Band)', 'Legs', 'Resistance Band', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'Strengthen the back of your thighs with this curling exercise. Secondary activation of your calves provides additional muscle engagement. The standing position engages your core for stability. Resistance bands provide accommodating resistance that increases through the range of motion. Strong legs are the foundation for athletic performance and functional fitness.', '9251201', '09251201-Band-standing-leg-curl-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Standing Leg Curl. 2. Stand tall with your feet firmly planted. 3. Curl your heels toward your glutes by bending at the knees. 4. Squeeze your hamstrings at peak contraction. 5. Extend legs back out with control. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 87, 7, 8, TRUE, TRUE, 'leg_curl', 'Standing Leg Curl', 'romanian_deadlift, hip_thrust', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('ff168dc8-8792-49fb-884c-d3e3677ba842', 'Single Leg Split Squat With The Ring (Band)', 'Legs', 'Resistance Band, Gymnastic Rings', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Bands are joint-friendly and portable, perfect for any training environment. Lower body strength improves everything from walking to heavy compound lifts.', '66821201', '66821201-Band-Single-Leg-Split-Squat-with-the-Ring_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Secure the resistance band appropriately for Band Single Leg Split Squat With The Ring. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 73, 7, 8, TRUE, TRUE, 'split_squat', 'Single Leg Split Squat With The Ring', 'lunge, bulgarian_split_squat, squat', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('ff1eab2d-a854-46d4-a1c4-8a847ec72dd9', 'Single Arm Incline Fly (Cable, Stability Ball)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'This flying exercise focuses on your pectorals for improved chest strength and development. Your front delts work as secondary movers, adding to the training stimulus. The incline angle shifts emphasis toward the upper portion of the target muscles. Cable resistance creates smooth, continuous muscle engagement. A well-developed chest contributes to upper body strength and aesthetics.', '12641201', '12641201-Cable-One-Arm-Incline-Fly-on-Exercise-Ball_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Adjust the cable machine to the correct height and attachment for Cable One Arm Incline Fly On Exercise Ball. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'chest_fly', 'Single Arm Incline Fly On Exercise Ball', 'bench_press, incline_press, push_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('ff2fafe5-602c-47ba-b3ef-124b06366f0a', 'Oblique Twist (Cable)', 'Core', 'Cables', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Cable Oblique Twist targets your obliques through a twisting motion, building rotational core strength. You''ll also feel your abs working to support the movement. The cable setup allows you to adjust the angle of resistance. Core strength is foundational for athletic performance and injury prevention.', '93921201', '93921201-Cable-Oblique-Twist-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Adjust the cable machine to the correct height and attachment for Cable Oblique Twist. 2. Rotate your torso through the movement pattern for Cable Oblique Twist. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 60, 5, 7, FALSE, TRUE, 'russian_twist', 'Oblique Twist', 'plank, crunch, leg_raise', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('ff34d0c8-d2f0-4507-b2f7-7e36b21d25b9', 'Single Arm Clean (Kettlebell)', 'Full Body', 'Kettlebell', '{"Full Body"}'::text[], '{"Quads","Glutes","Traps"}'::text[], 'This full-body movement exercise challenges multiple muscle groups simultaneously. The quads, glutes, traps assist throughout the movement, making this a well-rounded exercise. The kettlebell grip position adds a unique training stimulus. Full body exercises are time-efficient and build functional, real-world strength.', '45301201', '45301201-Kettlebell-Single-Arm-Clean-(female)_Weightlifts_.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Select an appropriately weighted kettlebell for Kettlebell Single Arm Clean. 2. Explosively pull the weight upward from the starting position. 3. Pull yourself under the weight and catch it at shoulder level. 4. Stand to complete the lift, then lower with control. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 53, 7, 8, TRUE, TRUE, 'clean', 'Single Arm Clean', 'power_clean, deadlift, front_squat', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('ff469987-cad5-42d5-8d92-0f67d001f075', 'Jump Squat (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Barbells enable bilateral loading for building raw strength. Strong legs are the foundation for athletic performance and functional fitness.', '531201', '00531201-Barbell-Jump-Squat_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Jump Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Explode upward from the bottom, jumping as high as possible. 5. Land softly with bent knees and immediately descend into the next rep. 6. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 97, 9, 8, TRUE, TRUE, 'squat_jump', 'Jump Squat', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', TRUE, 'barbell', FALSE, 3, 60, 4, 95, 80, 65, 95),
('ff5a08c3-85c2-450e-b68c-a38459e78906', 'Potty Squat With Support', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Potty Squat With Support is a squatting exercise that primarily loads your quadriceps. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '31311201', '31311201-Potty-Squat-with-Support-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form. An effective movement for your legs routine. Variation: Potty Squat With Support.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Potty Squat With Support', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ff75b193-be64-48d8-b6ea-0c463a44bc82', 'Lying Single Leg Circle', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Performing this lying down removes momentum for stricter form. Flexibility work like this enhances performance and prevents stiffness. This is a great exercise for all fitness levels with proper scaling.', '28541201', '28541201-Lying-Single-Leg-Circle-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying Single Leg Circle. 2. Move into the stretch position for Lying Single Leg Circle. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 5. Switch sides and repeat for equal time. 6. Complete all reps on one side, then switch to the other side.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'leg_exercise', 'Lying Single Leg Circle', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ff769bc9-cfbe-4275-b4f3-6e664e0535d7', 'Air Bike (Chair)', 'Core', 'Air Bike, Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Air Bike On A Chair, focusing on your abs. A strong core improves posture, protects your spine, and enhances all other lifts.', '76631201', '76631201-Air-Bike-on-a-Chair-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Set up in the starting position for Air Bike On A Chair. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 20, 9, 8, FALSE, TRUE, 'cycling', 'Air Bike On A Chair', 'crunch, russian_twist, leg_raise', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('ff7915f9-f963-44d0-8a6b-887c22e1ff6a', 'Double Rack Squat (Kettlebell)', 'Legs', 'Kettlebell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. The kettlebell''s offset center of mass increases the stability challenge. Leg training boosts metabolism and builds functional, real-world strength.', '98411201', '98411201-Kettlebell-Double-Rack-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Position two kettlebells for Kettlebell Double Rack Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 93, 7, 8, TRUE, TRUE, 'squat', 'Double Rack Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('ff971d02-07bd-488c-a934-64a0bf13d662', 'Banded Hip Thrust (Dumbbell)', 'Legs', 'Dumbbells', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'Develop your posterior chain with this thrusting movement that emphasizes the glutes. You''ll also feel your hamstrings working to support the movement. Dumbbells allow each arm to work independently, helping correct imbalances. Strong legs are the foundation for athletic performance and functional fitness.', '104251201', '104251201-Dumbbell-Banded-Hip-Thrust_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Banded Hip Thrust. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'hip_thrust', 'Banded Hip Thrust', 'glute_bridge, romanian_deadlift, leg_curl', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('ffa20994-da4e-4430-973e-e1b54c7b1826', 'Front Seated Row (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. You''ll also feel your biceps, lats working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. The cable setup allows you to adjust the angle of resistance. Back development is crucial for pulling strength and overall upper body function.', '1631201', '01631201-Cable-Front-Seated-Row_Back.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable Front Seated Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 92, 7, 8, TRUE, TRUE, 'cable_row', 'Front Seated Row', 'bent_over_row, lat_pulldown, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('ffa75c94-3ef8-4149-914f-279d9cf0dad8', 'Standing Diagonal Grab', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'This movement exercise focuses on your pectorals for improved chest strength and development. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Chest strength improves pushing power for sports, daily tasks, and other lifts. This is a great exercise for all fitness levels with proper scaling.', '88841201', '88841201-Standing-Diagonal-Grab-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:24.203368+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Diagonal Grab. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Diagonal Grab', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ffa8b799-b1fb-4717-9293-deae9a4d412a', 'Rocking Half Frog Stretch', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Target your full body with this stretching stretch that helps restore range of motion. Regular stretching improves flexibility, reduces injury risk, and aids recovery. This is a great exercise for all fitness levels with proper scaling.', '67081201', '67081201-Rocking-Half-Frog-Stretch-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Move into the stretch position for Rocking Half Frog Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'hip_stretch', 'Rocking Half Frog Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('ffa9aaa5-db09-441d-a05e-10453ded7c6f', 'Forward Step Air Bike (Air Bike)', 'Full Body', 'Air Bike', '{"Full Body"}'::text[], '{"Quads"}'::text[], 'This dynamic stepping movement gets your heart rate up while developing explosive strength. Your quads work as secondary movers, adding to the training stimulus. Plyometric training builds explosive power that transfers to sports and daily activities. A staple exercise that belongs in most training programs.', '84651201', '84651201-Forward-Step-Air-Bike-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Forward Step Air Bike. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 35, 9, 8, FALSE, TRUE, 'cycling', 'Forward Step Air Bike', 'crunch, russian_twist, leg_raise', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('ffb84a33-15ba-45cb-8727-70e6003b94ba', 'Kneeling Single Arm Horizontal Row (Band)', 'Back', 'Resistance Band, Anchor Point', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. Kneeling helps eliminate lower body momentum from the movement. Bands are joint-friendly and portable, perfect for any training environment. Back development is crucial for pulling strength and overall upper body function.', '106681201', '106681201-Band-Kneeling-Single-Arm-Horizontal-Row-(male)_Ba.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Secure the resistance band appropriately for Band Kneeling Single Arm Horizontal Row. 2. Kneel on the floor (use a pad for comfort if needed). 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps on one side, then switch to the other side. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'arm_exercise', 'Kneeling Single Arm Horizontal Row', 'bent_over_row, lat_pulldown, bicep_curl', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('ffbf8a41-7e3a-4c47-8254-0c693859d5c4', 'Bulgarian Split Squat With The Ring (Plate)', 'Legs', 'Weight Plate', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. You''ll also feel your glutes, hamstrings working to support the movement. Leg training boosts metabolism and builds functional, real-world strength. Focus on controlled form throughout each repetition.', '66791201', '66791201-Weighted-Plates-Bulgarian-Split-Squat-with-the-Ring_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction.', 'Squat', NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'split_squat', 'Weighted Plates Bulgarian Split Squat With The Ring', 'split_squat, lunge, leg_press', TRUE, 'plate', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ffc0fffd-1ead-473f-b636-a5ecf4ad4ffe', 'Bulgarian Split Squat From Deficit (Dumbbell, Step Platform)', 'Legs', 'Step Platform', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Dumbell Bulgarian Split Squat From Deficit is a squatting exercise that primarily loads your quadriceps. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. The dumbbell variation provides freedom of movement and greater range of motion. Leg training boosts metabolism and builds functional, real-world strength.', '75501201', '75501201-Dumbell-Bulgarian-Split-Squat-from-Deficit-(male)_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbell Bulgarian Split Squat From Deficit. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 85, 7, 9, TRUE, FALSE, 'split_squat', 'Dumbell Bulgarian Split Squat From Deficit', 'split_squat, lunge, leg_press', FALSE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('ffc7abe6-eabb-474f-916f-03f792fab2c4', 'Reverse Curl (Cable)', 'Arms', 'Cables', '{"Forearms"}'::text[], '{"Biceps"}'::text[], 'The Cable Reverse Curl is a curling exercise that isolates your biceps. Secondary activation of your biceps provides additional muscle engagement. The cable setup allows you to adjust the angle of resistance. Dedicated arm training builds both strength and muscular definition.', '2061201', '02061201-Cable-Reverse-Curl_Forearm.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Reverse Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'bicep_curl', 'Reverse Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('ffc9a28e-e542-44d7-b683-67dd432ae823', 'Ring L Sit Chin Up (Gymnastic Rings)', 'Back', 'Gymnastic Rings', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this movement movement. You''ll also feel your biceps working to support the movement. Back development is crucial for pulling strength and overall upper body function.', '72271201', '72271201-Ring-L-Sit-Chin-up-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Pull yourself up, focusing on bicep and lat engagement. 2. Raise until chin is over the bar, lower with full control. 3. Continue for your target rep count, maintaining good form throughout. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'pull_up', 'Ring L Sit Chin Up', 'lat_pulldown, bent_over_row, bicep_curl', FALSE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('ffd1dbbf-55d1-46f2-9639-29d8ba900340', 'Triceps Press', 'Arms', 'Bodyweight', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build stronger triceps with this pressing exercise for bigger arms. This bodyweight exercise requires no equipment and can be done anywhere. Dedicated arm training builds both strength and muscular definition.', '8161201', '08161201-Triceps-Press_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Keep your upper arms stationary and extend at the elbow. 2. Squeeze your triceps at full extension, then control the return. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'arm_exercise', 'Triceps Press', 'bicep_curl, tricep_pushdown, skull_crusher, dip', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ffdc26f6-b972-4fa6-a2ec-cac1714d4ec0', 'Vibrate Plate Standing (Vibration Plate)', 'Back', 'Vibration Plate', '{"Lats"}'::text[], '{"Shoulders"}'::text[], 'Target your lats with this movement stretch that helps restore range of motion. You''ll also feel your shoulders working to support the movement. The standing position engages your core for stability. Include this in your routine for better mobility and reduced muscle tension.', '25251201', '25251201-Vibrate-Plate-Standing-(female)_Stretching.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Begin in a standing position with good posture. 2. Move into the stretch position for Vibrate Plate Standing. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'back_exercise', 'Vibrate Plate Standing', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ffe007d1-1178-441b-90e3-fd374f16c0d2', 'Inverted Row With Straps', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Inverted Row With Straps is a rowing exercise that builds thickness in your upper back. You''ll also feel your biceps working to support the movement. A versatile bodyweight movement perfect for home or gym training. Back development is crucial for pulling strength and overall upper body function.', '4981201', '04981201-Inverted-Row-with-Straps_Back.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'general_exercise', 'Inverted Row With Straps', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ffe2f3cb-78f5-40fa-ba49-30ad42d18e3c', 'Single Arm Bent Over Row (Resistance Band)', 'Back', 'Resistance Band, Anchor Point', '{"Back","Lats"}'::text[], '{"Biceps","Rear Delts"}'::text[], 'The Resistance Band One Arm Bent Over Row is a rowing exercise that builds thickness in your upper back. You''ll also feel your biceps, lats working to support the movement. The bent over position requires core engagement to maintain a neutral spine. The band creates increasing tension as it stretches, challenging the lockout. Back development is crucial for pulling strength and overall upper body function.', '45691201', '45691201-Resistance-Band-One-Arm-Bent-Over-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Secure the resistance band appropriately for Resistance Band One Arm Bent Over Row. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps on one side, then switch to the other side. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'bent_over_row', 'Single Arm Bent Over Row', 'cable_row, dumbbell_row, t_bar_row, lat_pulldown', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('ffe5112a-d544-48a3-833c-423c010cae91', 'Standing Butt Kick Pulldown', 'Back', 'Bodyweight', '{"Glutes","Hamstrings"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This dynamic pulling movement gets your heart rate up while developing explosive strength. You''ll also feel your hamstrings working to support the movement. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '92581201', '92581201-Standing-Butt-Kick-Pulldown-(front-POV)-(female)_P.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Stand tall with your feet firmly planted. 2. Pull the bar/handle down toward your upper chest. 3. Drive your elbows down and back, squeezing your lats. 4. Control the weight back up without letting it yank your arms. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'glute_kickback', 'Standing Butt Kick Pulldown', 'high_knees, jumping_jack, running', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ffe563c6-2af2-4b01-8fc6-74798ba6bec3', 'Spider To Cross Body Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'This dynamic stabilization movement gets your heart rate up while developing explosive strength. Your shoulders, core work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '105671201', '105671201-Spider-to-Cross-Body-Plank-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'shoulder_stretch', 'Spider To Cross Body Plank', 'crunch, leg_raise, russian_twist, dead_bug', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('ffeb6035-15ec-4a01-906f-7823c5515a11', 'Bent Over Rear Delt Fly', 'Shoulders', 'Bodyweight', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'Build stronger shoulders with this flying movement focusing on your rear delts. Secondary activation of your upper back provides additional muscle engagement. The bent over position requires core engagement to maintain a neutral spine. This bodyweight exercise requires no equipment and can be done anywhere. Strong shoulders improve overhead strength and support nearly all upper body movements.', '41721201', '41721201-Bodyweight-Bent-Over-Rear-Delt-Fly_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Hinge at your hips, pushing them back while keeping your back flat. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Repeat for the prescribed number of repetitions. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'rear_delt', 'Bent Over Rear Delt Fly', 'bench_press, incline_bench_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('fff190cd-5c43-470e-874e-e417cc43f9d6', 'Standing Calf Raise (Dumbbell)', 'Legs', 'Dumbbells', '{"Calves"}'::text[], '{}'::text[], 'This raising movement focuses on your gastrocnemius and soleus. The standing position engages your core for stability. Using dumbbells requires more stabilization than barbell variations. Strong legs are the foundation for athletic performance and functional fitness.', '22101201', '22101201-Dumbbell-Standing-Calf-Raise-(female)_Calves.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Calf Raise. 2. Begin in a standing position with good posture. 3. Lower your heels below the platform to get a full stretch. 4. Rise up onto your toes as high as possible, squeezing your calves. 5. Lower with control and repeat. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'calf_raise', 'Standing Calf Raise', 'calf_raise, seated_calf_raise', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('fffe2d2c-faf5-4fda-b230-7c7b1e2d4ba5', 'Seated Front Raise (Kettlebell)', 'Shoulders', 'Kettlebell', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'Build stronger shoulders with this raising movement focusing on your front delts. The seated position helps isolate the target muscles by removing momentum. Kettlebells are excellent for building functional, real-world strength. Shoulder development enhances both performance and upper body aesthetics.', '68311201', '68311201-Kettlebell-Seated-Front-Raise_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Select an appropriately weighted kettlebell for Kettlebell Seated Front Raise. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Raise the weight in front of you to shoulder height. 4. Lower with control, maintaining tension throughout. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'front_raise', 'Seated Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78);
